  str_monster_name_2000271_en = "Lumo Ranger",
  str_monster_desc_2900063 = "Kabarnya adalah anggota Eclipse, sebuah organisasi misterius. Tak hanya punya serangan yang kuat, ia juga bisa memerintah para Eclipsite.",
  str_monster_desc_2900141 = "Anggota organisasi misterius Eclipse, dia dan saudarinya Shire membentuk Viper Twins. Dia akan melakukan apa pun untuk mencapai tujuannya.",
  str_monster_desc_2900181 = "Sebagai anggota organisasi misterius Eclipse, dia dan saudarinya Shelt membentuk Viper Twins. Dia impulsif, membunuh musuh dengan kekejaman dan kebrutalan.",
  str_monster_desc_2900201 = "Kabarnya adalah anggota Eclipse, sebuah organisasi misterius. Tak hanya punya serangan yang kuat, ia juga bisa memerintah para Eclipsite.",
  str_monster_desc_2900211 = "Ganas dan bertubuh besar, Eclipsite kuat yang tampaknya merasakan penderitaan tanpa akhir. Sebaiknya jangan dekat-dekat.",
  str_monster_desc_2900221 = "Gabungan antara Shelt dan Shire. Menderita dari rasa sakit yang luar biasa, ia punya hasrat yang kuat untuk balas dendam, membuatnya menjadi Eclipsite yang brutal dan kuat.",
  str_monster_desc_2900231 = "Makhluk yang melindungi Colossus Mantiz dengan teknologi kuno yang misterius. Berhati-hatilah.",
  str_monster_desc_2900232 = "Makhluk yang melindungi Colossus Mantiz dengan teknologi kuno yang misterius. Berhati-hatilah.",
  str_monster_desc_2900241 = "Kekuatan penghancurnya mampu membasmi seluruh pasukan. Dikatakan sebagai bawahan setia dari seorang anggota organisasi Eclipse.",
  str_monster_desc_2900251 = "Sangat gesit, sama seperti hantu yang datang dan pergi tanpa meninggalkan jejak, dan cara biasa takkan bisa menyakitinya. Dikenal juga sebagai Soul Hunter.",
  str_monster_desc_2000011 = "Dengan keterampilan bertarung yang jauh melebihi Dretcher, ia adalah unit tempur utama Eclipsite. Mereka juga dikenal sebagai Kapten dan sering terlihat memimpin Dretcher.",
  str_monster_desc_2000071 = "Eclipsite raksasa yang bertugas untuk menghancurkan berbagai benteng dan dikenal sebagai Demolisher.",
  str_monster_desc_2000101 = "Bertugas untuk menyelidiki pergerakan Aurorian dan dikenal sebagai Scout. Biasanya menyerang Aurorian bersama dengan Eclipsite lainnya.",
  str_monster_desc_2000111 = "Pelayan dari Evil Eye dengan Skill ATK dan Skill RES yang kuat. Terkadang mereka membantu Dretcher.",
  str_monster_desc_2000121 = "Eclipsite yang ahli dalam mendeteksi pergerakan Aurorian. Dikenal juga sebagai Seer dan bisa mendeteksi dari kejauhan.",
  str_monster_desc_2000131 = "Pasukan makhluk reptil abu-abu yang bertanggung jawab atas berbagai tugas tempur dasar. Dikenal juga sebagai Cleaner.",
  str_monster_desc_2000141 = "Makhluk pendek yang membawa kotak hitam yang mengangkut suplai organisasi Eclipse, juga dikenal sebagai Runner.",
  str_monster_desc_2000151 = "Mereka adalah petarung Eclipsite. Sangat kuat dalam pertempuran dan bisa memerintah Eclipsite. Dikenal juga sebagai Officer.",
  str_monster_desc_2000161 = "Mahir dalam berkamuflase. Mereka sering menyusup ke pertemuan Aurorian untuk membunuh dan dikenal sebagai Assassin.",
  str_monster_desc_2000171 = "Salah satu dari \"Materialized Eclipsite.\" Biasanya berbentuk seperti manik hitam dan dibawa oleh Shadow atau Eclipsite lainnya. Sering dikeluarkan di saat genting dalam pertempuran untuk melawan.",
  str_monster_desc_2000181 = "Salah satu dari \"Materialized Eclipsite.\" Biasanya berbentuk seperti manik hitam dan dibawa oleh Shadow atau Eclipsite lainnya. Sering dikeluarkan di saat genting dalam pertempuran untuk melawan.",
  str_monster_desc_2000211 = "Kurang cocok untuk bertempur, tetapi mampu memulihkan HP Eclipsite lainnya. Diduga evolusi dari Shadowgeist, dan terkadang disebut sebagai Healer.",
  str_monster_desc_2000221 = "Mereka kurang cocok untuk pertempuran, tapi dapat memunculkan paku dari tanah, langit-langit, dan dinding batu lainnya untuk menyerang orang yang lewat! Terkadang disebut sebagai Spiker.",
  str_monster_desc_4000221 = "Tidak ada kekuatan tempur.",
  str_monster_desc_2000231 = "Kakinya mampu menyerap Lumina di sekitar, menjadi sangat kuat. Disebut berevolusi dari Gloom Ghouls, dan juga dikenal sebagai \"Penghisap Energi.\"",
  str_monster_desc_2000241 = "Sebuah elite dari Evil Eye dengan kemampuan observasi yang kuat, menyulitkan Aurorian untuk bersembunyi. Juga dikenal sebagai Seeker.",
  str_monster_desc_2000251 = "Anggota junior yang menjadi basis kekuatan militer Lumopolis dengan jumlah sangat banyak dan aktif secara luas dalam Patrol.",
  str_monster_desc_2000261 = "Mereka bertanggung jawab untuk melindungi kota sepanjang hari tanpa mengeluh sekali pun. Tidak pernah beristirahat, mereka dianggap sebagai tulang punggung Guard.",
  str_monster_desc_2000271 = "Mereka adalah penjaga yang juga berperan sebagai pengintai. Setelah melewati latihan khusus, mereka memiliki mobilitas, ketangkasan dan kelincahan yang sangat tinggi.",
  str_monster_desc_2000281 = "Guard dipersenjatai dengan defense shield yang kuat. Dengan kemampuan untuk bertahan dalam pertempuran sengit, mereka bagaikan tembok kuat yang melindungi rekan-rekannya.",
  str_monster_desc_2000291 = "Piker yang telah menjalani pelatihan tempur. Serangan serbu yang kuat membuat mereka jadi tak terkalahkan di medan tempur.",
  str_monster_desc_2000293 = "Piker yang telah menjalani pelatihan tempur. Serangan serbu yang kuat membuat mereka jadi tak terkalahkan di medan tempur.",
  str_monster_desc_2000301 = "Armored Eclipsite dari White Night, Black Underbelly. Dulunya mereka ganas, tapi setelah ditangkap berubah menjadi sumber hiburan.",
  str_monster_desc_2000302 = "Versi diperkuat dari Armored Eclipsite. Meskipun armor-nya terlihat lebih gagah, mereka tetap saja menjadi sumber hiburan bagi yang lain.",
  str_monster_desc_2000311 = "Ia senang melawan Aurorian dengan pedang ganda dan sangat terampil. Namun, ia jarang bekerja sama dengan Eclipsite lainnya dan dikenal sebagai Swordsman.",
  str_monster_desc_2000321 = "Berevolusi dari serangga yang bergerak cepat sebelum perang. Ia lincah dan sangat sulit untuk dilawan. Dikenal dengan nama Chaser.",
  str_monster_desc_2000341 = "Penjarah profesional yang mencari nafkah dengan mencuri barang dari peradaban kuno. Karena semua energi mereka digunakan untuk mencuri, kemampuan tempur mereka sangat rendah, dan mereka hanya akan melarikan diri saat bertemu musuh.",
  str_monster_desc_2000351 = "Dikatakan sebagai versi Crusher yang lebih lemah. Dianggap sebagai Crusher yang terluka parah lalu berevolusi setelah menerima perawatan.",
  str_monster_desc_2000411 = "Dipengaruhi oleh energi yang kuat, beberapa Eclipsite Evil Eye mengalami mutasi yang aneh.",
  str_monster_desc_2000421 = "Dikatakan sebagai mutasi Shadow Eclipsite, dapat meningkatkan ATK Eclipsites lainnya.",
  str_monster_desc_2000431 = "Eclipsite spesial yang diciptakan oleh para leluhur sandworm. Darkflow-nya sangat tidak stabil dan meledak setelah mati.",
  str_monster_desc_2000441 = "Beberapa Eclipsite dipengaruhi oleh energi kuat dan berevolusi dengan hebat. Mereka memiliki resistansi tinggi terhadap elemen tertentu.",
  str_monster_desc_2000442 = "Eclipsite jenis ini mengumpulkan energi elemen dalam jumlah besar sehingga ia mampu memengaruhi elemen di sekitarnya.",
  str_monster_desc_2000451 = "Prajurit Lumopolis yang ditipu oleh Gertzurde kehilangan kemampuan mereka untuk berpikir dan menyerang setelah dikendalikan oleh Eclipsite. Mereka akan maju ke dalam pertempuran di bawah perintah Gertzurde.",
  str_monster_desc_2000401 = "Eclipsite level rendah dengan kecerdasan nol. Mereka hanya bisa mematuhi perintah summoner dan menahan serangan untuknya.",
  str_monster_desc_2000491 = "Klona ciptaan Eclipsite level tinggi berkemampuan khusus. Tampak identik dengan aslinya hingga menimbulkan kekacauan di kalangan musuh.",
  str_monster_desc_2000501 = "Eclipsite ini memiliki kait khusus untuk menarik target ke dalam serangan grup. Berhati-hatilah.",
  str_monster_desc_2000511 = "Eclipsite jenis ini memiliki kristal abu-abu yang memancarkan sinar unik dan mengganggu aliran Lumina target, sehingga sangat sulit untuk dikendalikan.",
  str_monster_desc_2000521 = "Mutan yang muncul setelah beberapa Eclipsite melahap mayat Eclipsite lainnya. Mereka dapat melepaskan medan kekuatan khusus yang mengunci Lumina dan membuatnya tidak bisa mengalir.",
  str_monster_desc_2000531 = "Prober Eclipsite yang bermutasi; dikatakan memiliki kemampuan penglihatan jarak jauh termutasi dengan metode serangan jarak jauh yang kuat dan akurat.",
  str_monster_desc_2000541 = "Eclipsite Warmonger yang bermutasi. Mereka tidak hanya memiliki peningkatan kekuatan tempur tetapi juga kemampuan khusus untuk mengikis Lumina.",
  str_monster_desc_2000551 = "Eclipsites jenis baru yang muncul di Secret Territory. Mereka dikatakan terlahir dari perasaan benci sebuah ras kuno yang dimusnahkan oleh Eclipsite. Ini adalah satu-satunya cara untuk menjelaskan sumber kemampuan kutukan kuat yang mereka kuasai.",
  str_monster_desc_2000561 = "Eclipsite langka. Mereka terlihat seperti Phantom yang melayang, bergerak cepat, dan pada dasarnya tidak bisa diserang. Juga dikenal sebagai Ghost.",
  str_monster_desc_2000571 = "Saksi ledakan kekuatan White Schummer. Eclipsite spesial ini terbentuk dari campuran antara kejahatan dan kebenciannya. Tidak bisa bergerak, aura gelapnya menutupi langit, cukup untuk memiliki kemampuan mengutuk yang kuat.",
  str_monster_desc_2000581 = "Konon salah satu varian Eclipsite level rendah, Chasm. Mematuhi panggilan dari Eclipsite level tinggi dan bisa menghancurkan diri dengan kekuatan besar. Satu-satunya cara untuk menghentikan hal ini terjadi adalah dengan menyingkirkannya sebelum meledak.",
  str_monster_desc_2000601 = "Eclipsite spesial yang kecil dan nyaris tak terlihat dengan mata telanjang. Tubuhnya telah membengkak ke ukuran saat ini karena efek dari emosi negatif yang kuat.",
  str_monster_desc_2000602 = "Ilusi ciptaan Luminatics Dawn yang mengandung kekuatan magis.",
  str_monster_desc_2000611 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000701 = "Eclipsite spesial ini telah terbangun dari tidur panjang mereka. Mereka berjumlah banyak, tetapi taktik mereka cukup sederhana. Namun, awas, mereka memiliki kemampuan untuk berubah!",
  str_monster_desc_2000702 = "Sebuah kastel yang rusak terkubur di dasar laut. Tiap kali loncengnya berdering, Desolate Monarch melampiaskan amarahnya kepada musuh-musuhnya.",
  str_monster_desc_2000703 = "Kuda perang ini hanyalah mayat sebelum dibangkitkan oleh Desolate Monarch. Dengan mempertahankan kekuatan dan kesetiaan masa lalunya, ia menyerang semua musuh masternya tanpa menanyakan apa pun.",
  str_monster_desc_2000704 = "Karena dahulu adalah pembantu raja, mereka bisa melihat lorong-lorong dalam kehampaan yang tidak diketahui orang lain, lalu bergerak cepat untuk menyerang.",
  str_monster_desc_2000705 = "Dahulu adalah seorang bangsawan, balas dendam mendorongnya untuk datang ke laut ini, di mana dia menghidupkan kembali raja kuno yang legendaris... Namun, kekuatan gelap yang dia panggil juga menelan jiwanya, mengubahnya menjadi Eclipsite.",
  str_monster_desc_2000711 = "Para Lost Pawn ini telah mendapatkan kekuatan dari kehampaan. Meskipun taktik mereka tetap sederhana, efektivitas tempur mereka telah meningkat secara signifikan. Mereka tidak bisa diremehkan.",
  str_monster_desc_2000712 = "Sebuah kastel yang menghancurkan semua yang menghalangi jalannya, loncengnya yang berdering menjadi mimpi buruk terparah bagi tiap musuh.",
  str_monster_desc_2000713 = "Dengan suara dan tapak kaki seram yang mengguncang tanah, ketika para penunggang kuda yang ganas ini menyerbu ke medan tempur, satu-satunya hal yang dapat menghentikan mereka adalah kematian.",
  str_monster_desc_2000714 = "Ucapan kekejaman dan kejahatan mengelilingi... Waspadai serangan dari samping.",
  str_monster_desc_2000715 = "Caroline... Gila akan kekuatan, dia telah menyatu dengan kehampaan, meraih kekuatan yang tak terhingga.",
  str_monster_desc_2000901 = "Eclipsite jenis baru yang konon diciptakan oleh Eclipse untuk menembus pertahanan Aurorian. Eclipsite ini menghancurkan medan di sekitarnya dengan cara meledakkan diri sendiri.",
  str_monster_desc_2001001 = "Sesosok Eclipsite yang pernah menghuni kedalaman Secret Territory ini unggul dalam melancarkan serangan dari bawah tanah. Konon, ia juga mampu menggali lorong bawah tanah untuk Eclipsite lainnya.",
  str_monster_desc_2001301 = "Debu telah mereda dan identitas musuh asing yang familier akan segera terungkap. Saatnya untuk membuktikan tekad.",
  str_monster_desc_2101301 = "Eclipsite Minion yang dipanggil oleh High-Level Eclipsite.",
  str_monster_desc_4001301 = "Eclipsite Minion yang dipanggil oleh High-Level Eclipsite.",
  str_monster_desc_2001401 = "Tentakel-tentakel simbiosis dari Kittypus secara langsung mentransfer damage yang berdatangan ke inangnya.",
  str_monster_desc_2900271 = "Eclipsite semacam ini telah mengalami mutasi yang aneh. Dikatakan bahwa kekuatan tempurnya sebanding dengan High-level Eclipsite. Ia adalah kepala dari semua Armored Eclipsite dengan HP yang sangat tinggi.",
  str_monster_desc_2900262 = "Aurorian yang dirusak oleh kekuatan gelap yang kuat. Ia telah kehilangan kesadaran akan dirinya dan sangat berbahaya.",
  str_monster_desc_2900263 = "Di masa lalu, Eve dibuat menjadi gila berkat \"perawatan\" wanita misterius yang menyebabkannya hilang kendali atas kekuatannya dan membakar Undercity \"itu\". Kemarahan dan rasa bersalah mencabik-cabik hatinya saat tragedi itu terulang lagi dan lagi... Redakan amarahnya sekarang.",
  str_monster_desc_2900264 = "Gadis misterius yang kamu temui di Red-Eye Gorge. Dia \"memerintahkan\" Eclipsite untuk membawa Eve pergi dengan tujuan yang tidak diketahui.",
  str_monster_desc_2900281 = "Jenis Eclipsite yang tidak terlalu cerdas dan tidak memiliki kehendak sendiri. Tujuannya tidak diketahui, dan sepertinya terkait dengan Darkover Crisis. Juga dikenal sebagai Darkover Omen.",
  str_monster_desc_2900391 = "Meskipun gerakannya lambat, ia punya DEF tinggi dan bisa meluncurkan Abyssal Bomb dengan kekuatan luar biasa. Juga dikenal sebagai Transporter.",
  str_monster_desc_2900401 = "Dulunya Caelestite, lalu bergabung dengan Eclipse dan kekuatannya meningkat tajam.",
  str_monster_desc_2900402 = "Dulunya Caelestite, lalu bergabung dengan Eclipse dan kekuatannya meningkat tajam.",
  str_monster_desc_2900403 = "Dulunya Caelestite, lalu bergabung dengan Eclipse dan kekuatannya meningkat tajam.",
  str_monster_desc_2900411 = "Awalnya anggota dari Lumopolis Guardian. Berhasil dibujuk oleh Shelt dan rela menghancurkan Lumopolis untuk mereka.",
  str_monster_desc_2900421 = "Setelah Nozard dikalahkan, tubuhnya diambil oleh organisasi yang tidak dikenal dan secara eksperimental diubah menjadi monster yang menakutkan.",
  str_monster_desc_2900422 = "Eclipsite berukuran besar yang berwujud naga raksasa, berkeliaran di sekitar Blazing Tooth Canyon.",
  str_monster_desc_2900431 = [[
Cacing pasir raksasa kuno yang telah menghuni situs ini semenjak dihancurkan. Baru-baru ini, 
setelah terbangun dari tidur panjangnya, ia mulai menyerang semua penyusup yang datang.]],
  str_monster_desc_2900441 = "Eclipse mengubah Umbrahulk dan menjadikannya lebih kuat. Sejak itu, ia ditugaskan oleh Eclipse untuk memeriksa sisa-sisa Spire dan menangani berbagai kejadian tak terduga.",
  str_monster_desc_2900451 = "Monster yang awalnya berwujud hantu, lalu berevolusi karena kekuatan Light setelah memasuki negeri ini. Bisa menciptakan berbagai ilusi dengan cahaya yang dibiaskan di medan tempur.",
  str_monster_desc_2900452 = "Portal yang diciptakan oleh Eclipsite Phorosion. Digunakan untuk bersembunyi dan menyergap ketika melihat kelemahan musuh.",
  str_monster_desc_2900501 = "Berevolusi dari Siphorb, ia menyerap begitu banyak Lumina sehingga tidak dapat mengontrol warna cahaya di sekitarnya. Ia juga dapat menggunakan mana untuk menyerap Aurorian di dekatnya untuk menyerang.",
  str_monster_desc_2900601 = "Mutan yang muncul setelah Solmorph dari organisasi Eclipse, menyerap kekuatan Spire. Mereka bisa tiba-tiba melepaskan Lumina yang diserapnya untuk melancarkan serangan mematikan.",
  str_monster_desc_2900611 = "Mutan yang dibuat oleh Organisasi Eclipse menggunakan sisa-sisa High-level Eclipsite seperti Phantom. Mereka memiliki kemampuan membelah diri yang lebih kuat dan hanya bisa dihancurkan dengan mengalahkannya dan semua klonnya.",
  str_monster_desc_2900641 = "Beberapa Caracalite digabungkan dan bermutasi menjadi High-level Eclipsite yang bahkan memiliki penguasaan Eclipsium lebih kuat. Dengan teknik khusus mengunci Lumina, ia sangat sulit untuk dihadapi.",
  str_monster_desc_2900651 = "Dikatakan bahwa ketika gen Tabaad disuntikkan ke Eclipsite yang kuat, High-level Eclipsite yang mirip Tabaad muncul dengan kemampuan yang lebih kuat dan kepatuhan yang tidak perlu dipertanyakan lagi.",
  str_monster_desc_2900661 = "Mainan baru yang lain milik Forsakin. Berbeda dengan Boredom sebelumnya, selain memiliki kekuatan besar, ia juga memiliki kemampuan mengerikan yang dapat mengikis Lumina. Jangan pernah menganggapnya remeh.",
  str_monster_desc_2900671 = "Setelah benih di dalam tubuhnya tumbuh menjadi parasit, wujudnya yang telah menyerap sejumlah besar energi menjadi sangat berbeda dari sebelumnya. Bahkan penampilannya telah sedikit berubah.",
  str_monster_desc_2900681 = "Flicker Eclipsite yang telah bermutasi. Sangat gesit, sama seperti hantu yang datang dan pergi tanpa meninggalkan jejak, dan cara biasa takkan bisa menyakitinya.",
  str_monster_desc_2900701 = "Robot yang ditinggalkan oleh peradaban kuno. Dirancang secara unik, ia dapat terus bekerja meskipun hancur sebagian. Ia sangat sulit untuk dihadapi.",
  str_monster_desc_2900711 = "Robot yang muncul setelah T-1024 terbelah. Ia akan berusaha mencari T-256 lain terlebih dahulu dan mencoba membentuk T-1024 lain.",
  str_monster_desc_2910711 = "Sebuah droid fungsional dengan asal-usul yang tidak diketahui. Kemampuan ofensifnya tidak bisa diremehkan.",
  str_monster_desc_29107141 = "\"Beep! Beep!\"",
  str_monster_desc_29107111 = "\"Beep! Bzz!\"",
  str_monster_desc_2800241 = "\"Lihat apa kamu? Jangan harap kamu bisa menemukan informasi apa pun tentangku di sini. Baik Aurorian atau Caelestite tidak bisa memahami keinginan di level yang LEBIH TINGGI...\"",
  str_monster_desc_2900801 = "Sesosok raja kuno yang terkubur jauh di dalam lautan selama ribuan tahun. Dibangkitkan oleh Deceptive Queen, dia kini bersumpah untuk menjebak musuh-musuhnya dalam kehampaan untuk selamanya.",
  str_monster_desc_2900811 = "Raja kuno yang marah mengendalikan dan mempermainkan semua serta tiap penyusup hingga pada akhirnya, kematian menjemput mereka.",
  str_monster_desc_2900911 = "Dikabarkan sebagai Eclipsites tingkat tinggi yang sebelumnya terlibat dalam beberapa pertempuran sengit. Tidak diketahui jumlahnya dan memiliki kemampuan langka untuk terbang, mereka sekarang telah terbangun dari tidur mereka dan bersiap untuk menjerumuskan Aurorian ke dalam mimpi buruk yang baru.",
  str_monster_desc_2900912 = "Eclipsite ini mengikuti Hylingerr dan dapat membantunya dalam pertempuran.",
  str_monster_desc_2901001 = "Setelah diusir dari kota, kebencian mantan bangsawan Lumopolis ini terhadap bekas negaranya pun berkobar. Dia membelot ke Eclipse dan berusaha menggulingkan kepemimpinan Lumopolis. Rencananya yang gagal membuatnya makin tenggelam dalam kegilaan. Akibatnya, kebenciannya yang memuncak menjadi pemicu kekuatannya...",
  str_monster_desc_2901101 = "Karena tidak bisa mengatasi ketakutannya, dan putus asa mewujudkan ambisinya, dia mengalami transformasi sementara yang berbahaya tanpa berpikir panjang. Membuatnya bermutasi menjadi makhluk mengerikan ini.",
  str_monster_desc_2901201 = "Seorang pahlawan kuno yang menjadi Eclipsite untuk melawan mereka. Dia sekarang telah menjadi monster yang dungu.",
  str_monster_desc_2901300 = "Eclipsite misterius yang asalnya tidak diketahui dan kehadirannya tampaknya tidak sesuai dengan kenyataan yang kau lihat.",
  str_monster_desc_2901301 = "Debu telah mereda dan identitas musuh asing yang familier akan segera terungkap. Saatnya untuk membuktikan tekad.",
  str_monster_desc_2901401 = "Teman spesial Gretel. Biasanya tenang dan kalem, tetapi dikenal mengamuk dalam pertempuran. Dekati sambil waspada.",
  str_monster_desc_2901501 = "Teman spesial Gretel. Ia menyenangkan dan energik, serta sangat menikmati pertarungan melawan segerombolan musuh.",
  str_monster_desc_2901601 = "Teman spesial Gretel. Ia memiliki sepasang kaki yang sangat kuat yang dapat mengusir siapapun musuhnya.",
  str_monster_desc_2901701 = "Teman spesial Gretel. Ia menyerupai kucing dengan banyak kaki... Ia lucu, tetapi entah kenapa sedikit mengganggu.",
  str_monster_desc_2901801 = "Penghuni Lost City dan keturunan penjelajah Illumina—Seamus. Sepertinya mereka beranggapan bahwa merekalah pemilik tempat ini.",
  str_monster_desc_2901901 = "Mantan kepala Wisp yang berdedikasi untuk memerangi penjajah Cloud Island.",
  str_monster_desc_2901911 = "Nagi yang gila akan menyerang siapa saja yang dia anggap sebagai penyusup.",
  str_monster_desc_2902001 = "Seorang tiran yang datang dari pulau Far East lain untuk memerintah Cloud Island, dan dia akan melakukan apa saja untuk menyatakan kedaulatan atasnya.",
  str_monster_desc_2902101 = "Karena obsesinya, ia berubah menjadi pria yang mengerikan dan bersumpah untuk melenyapkan semua yang melawan.",
  str_monster_desc_2902201 = "Eclipsite kuat yang tinggal seorang diri di tengah reruntuhan selama bertahun-tahun. Kehilangan akal sehatnya, dia akan bertarung dengan orang luar hinggs titik darah penghabisan.",
  str_monster_desc_2902202 = "Mantan prajurit Illumina yang berubah menjadi Eclipsite akibat pengaruh Darkflow. Kebencian melahap kewarasannya dan merenggut semua kejayaan masa lalunya.",
  str_monster_desc_2902301 = "AI di markas bawah tanah Eraveil yang telah menjaga markas selama ribuan tahun dan bertanggung jawab memusnahkan seluruh musuh yang menyerang.",
  str_monster_desc_2902401 = "AI di markas bawah tanah Eraveil yang tampak besar dan berat itu adalah teman Claudia.",
  str_monster_desc_2902501 = "Kepala pelayan unggulan Andersen yang tak akan membiarkan adanya noda, sampah, atau hama.",
  str_monster_desc_2902601 = "Konon, dia adalah \"saudara\" Phantom di Eternal Night. Dia mampu melancarkan taktik yang berbeda berdasarkan waktu saat itu dan sangat sulit untuk dihadapi.",
  str_monster_desc_2902701 = "\"Lihat apa kamu? Jangan harap kamu bisa menemukan informasi apa pun tentangku di sini. Baik Aurorian atau Caelestite tidak bisa memahami keinginan di level yang LEBIH TINGGI...\"",
  str_monster_ability_2900063 = "Menyerang target depan dengan cakar raksasanya dan dapat terbang ke udara untuk mengebom area tertentu di tanah.",
  str_monster_ability_2900141 = "Ahli dalam serangan jarak dekat, serangannya akan men-stun target dengan kemampuan untuk memanggil Gloom Ghoul. Setelah berubah menjadi Rabid, serangan normalnya menjadi serangan ganda dengan jangkauan skill yang sangat meningkat, dan dapat memanggil Shadowgeist dan Gloom Ghoul pada saat yang bersamaan.",
  str_monster_ability_2900142 = "Unggul dalam serangan jarak dekat & memiliki kemampuan untuk memanggil Eclipsite lainnya. Saat dalam mode Rabid, memulihkan 20% dari HP maksimumnya. Setelah mode Rabid berakhir, Normal Attack-nya bisa menyerang dua kali, dan jangkauan skill-nya meningkat pesat.",
  str_monster_ability_2900181 = "Ahli dalam serangan jarak jauh, serangannya akan men-stun target dan memanggil Shadowgeist. Saat menjadi Rabid, serangan normalnya menjadi serangan ganda dengan jangkauan skill yang meningkat tajam, dan dapat memanggil Shadowgeist dan Gloom Ghoul pada saat yang bersamaan.",
  str_monster_ability_2900182 = "Eclipsite yang unggul dalam pertempuran jarak jauh ini mampu mendorong target dengan serangannya. Ia memiliki kemampuan untuk memanggil Eclipsite lainnya. Saat dalam mode Rabid, memulihkan 20% dari HP maksimumnya. Setelah mode Rabid berakhir, Normal Attack-nya bisa menyerang dua kali, dan jangkauan skill-nya meningkat pesat.",
  str_monster_ability_2900201 = "Ia pandai menggunakan tubuhnya yang besar untuk menyerang target di depannya. Ia menggali ke dalam tanah dan merusak target di dekatnya saat muncul.",
  str_monster_ability_2900211 = "Serangan jarak dekatnya dilengkapi dengan knockback, dan memiliki kemampuan untuk memanggil Pebble untuk menyerang. Target yang terkena akan dipukul mundur, dan area yang dipukul mundur akan mengeluarkan Pebble baru. Ia juga dapat meluncurkan Full-Screen Attack, dan damage yang diberikan ditentukan oleh jumlah Pebble.",
  str_monster_ability_2900221 = "Serangan normalnya disertai knockback. Mengubah area tempur menjadi Lumina dari elemennya dan menyerang berdasarkan elemennya: Fire - Damage area luas dengan efek Burning, Thunder - Damage layar penuh dengan Spikepest acak.",
  str_monster_ability_2900231 = "Serangan jarak dekat Philex disertai dengan knockback, dan ATK skill-nya men-stun target.",
  str_monster_ability_2900232 = "Vani bisa menggunakan Energy untuk menyerang dari kejauhan dan memulihkan HP ke Philex.",
  str_monster_ability_2900241 = "Ia melempar Incendiary Rounds ke zona pertempuran, menyebabkan unit yang lewat terkena Burn. Ia bisa menyerang target dan men-stun mereka saat kena, menggunakan aura pedang untuk menyerang dua baris target di depannya.",
  str_monster_ability_2900251 = "Menimbulkan serangan area berbentuk menyilang dan memanggil klon untuk bertarung di sampingnya. Setelah membuat klon, ia akan menyerap HP klon sebelumnya untuk memulihkan HP-nya sendiri. Ketika HP-nya kurang dari 50%, serangan normalnya akan menjadi serangan ganda, dan area serangan akan menjadi Full-Screen Attack.",
  str_monster_ability_2000011 = "Unit tempur utama Eclipsite, ahli dalam pertempuran jarak dekat dengan cakar.",
  str_monster_ability_2000071 = "Eclipsite berukuran besar yang pernah menghancurkan berbagai benteng dan jauh lebih kuat dari sekadar menghancurkan bangunan.",
  str_monster_ability_2000101 = "Pengintai Eclipsite yang mampu menggunakan cahaya yang dipancarkan dari mulutnya untuk menyerang musuh dari jarak jauh.",
  str_monster_ability_2000111 = "Lebih dikenal karena menggunakan penghalang untuk menahan serangan.",
  str_monster_ability_2000121 = "Eclipsite dengan kemampuan pemanggilan kelas bawah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Dretcher.",
  str_monster_ability_20001211 = "Eclipsite dengan kemampuan pemanggilan yang rendah. Tidak dapat bergerak sendiri dan bertarung dengan cara memanggil Eclipsite.",
  str_monster_ability_20001221 = "Eclipsite dengan kemampuan pemanggilan yang rendah. Tidak dapat bergerak sendiri dan bertarung dengan cara memanggil Spellhound.",
  str_monster_ability_20001231 = "Eclipsite dengan kemampuan pemanggilan kelas bawah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Darkwasp.",
  str_monster_ability_20001241 = "Eclipsite dengan kemampuan pemanggilan kelas bawah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Dreadblade.",
  str_monster_ability_20001251 = "Eclipsite dengan kemampuan pemanggilan level rendah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Slasher.",
  str_monster_ability_20001261 = "Eclipsite dengan kemampuan pemanggilan dasar. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Prober.",
  str_monster_ability_2000131 = "Eclipsite kelas rendah, hanya mampu melakukan serangan dasar berdasarkan insting.",
  str_monster_ability_2000141 = "Eclipsite dengan ATK sedang yang bertugas untuk mengumpulkan suplai.",
  str_monster_ability_2000151 = "Mahir bertarung dengan dua tinju besarnya. Ability Hammer Bash-nya menimbulkan ground damage dan mengakibatkan Stun pada target.",
  str_monster_ability_2000161 = "Menggunakan tombaknya untuk menyerang target dan mendapatkan kemampuan untuk memanggil Shadowgeist.",
  str_monster_ability_2000171 = "Materialized Eclipsite Type II: Healer Eclipsite. Biasanya berbentuk seperti manik hitam dan mampu menyembuhkan Eclipsite saat dilepaskan.",
  str_monster_ability_2000181 = "Materialized Eclipsites Type I: Ranged Eclipsite. Biasanya berbentuk seperti manik hitam. Mampu ikut pertempuran saat dilepaskan, tapi kekuatan tempurnya relatif rendah.",
  str_monster_ability_2000211 = "Eclipsite dengan kemampuan menyembuhkan, biasanya berperan memulihkan HP Eclipsite lainnya.",
  str_monster_ability_2000221 = "Kurang cocok untuk pertempuran, tapi dapat memunculkan paku dari tanah, langit-langit, dan dinding batu lainnya untuk menyerang orang yang lewat.",
  str_monster_ability_4000221 = "Biasanya, monster jenis ini menggunakan paku di tanah untuk menyerang orang yang lewat. Tapi kemampuan yang satu ini tampaknya berbeda dalam beberapa hal.",
  str_monster_ability_2000231 = "Eclipsite jarak jauh yang keterampilan tempur utamanya adalah memperkuat dirinya sendiri dengan menyerap Lumina. Ahli dalam serangan jarak jauh dan meskipun kekuatan pertempuran aslinya kurang, setelah menyerap Lumina, kekuatan pertempurannya meningkat secara signifikan.",
  str_monster_ability_2000241 = "Eclipsite dengan kemampuan pemanggilan tingkat menengah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Prober yang memiliki kemampuan serangan jarak jauh.",
  str_monster_ability_20002411 = "Seorang Eclipsite dengan kemampuan pemanggilan yang kuat. Dapat memanggil berbagai jenis Eclipsites untuk bertarung.",
  str_monster_ability_20002421 = "Eclipsite dengan kemampuan pemanggilan tingkat menengah. Bertarung dengan memanggil Dreadblades yang memiliki kemampuan serangan jarak dekat yang hebat.",
  str_monster_ability_20002422 = "Eclipsite dengan kemampuan pemanggilan tingkat menengah. Bertarung dengan memanggil Dreadblades yang memiliki kemampuan serangan jarak dekat yang hebat dan Spellhound dengan kemampuan defensif besar.",
  str_monster_ability_20002423 = "Eclipsite dengan kemampuan pemanggilan menengah. Itu bertarung dengan memanggil Dreadblade yang memiliki kemampuan jarak dekat yang kuat dan Vinesmark yang meluncurkan serangan jarak jauh yang mematikan.",
  str_monster_ability_2000251 = "Anggota junior pangkalan militer Lumopolis. Jumlahnya banyak, mode tempur utama mereka adalah penggunaan senjata yang dilengkapi untuk serangan jarak jauh.",
  str_monster_ability_2000261 = "Penjaga mekanik Lumopolis. Saat berhadapan dengan musuh, mereka bertempur dengan menciptakan prajurit longsword.",
  str_monster_ability_2000271 = "Pengintai Elite Lumopolis yang akan langsung pindah ke lokasi lain setelah menyerang target mereka. Mobilitas dan ketangkasan mereka menjadikannya target yang sulit untuk diserang dalam pertempuran biasa.",
  str_monster_ability_2000281 = "Penjaga bersenjata perisai dengan DEF tinggi. Perisai di lengan mereka tidak hanya berfungsi sebagai alat pertahanan, tetapi juga sebagai senjata jarak dekat.",
  str_monster_ability_2000291 = "Piker yang menjalani pelatihan tempur. Mereka punya keinginan kuat untuk bertarung dan memiliki keterampilan jarak dekat yang kuat.",
  str_monster_ability_2000293 = "Piker yang menjalani pelatihan tempur. Mereka punya keinginan kuat untuk bertarung dan memiliki keterampilan jarak dekat yang kuat.",
  str_monster_ability_2000301 = "Eclipsite carrier normal. Biasanya mengangkut pengiriman Nightium yang ringan. Kalahkan mereka untuk mendapatkan uang.",
  str_monster_ability_2000302 = "Eclipsite carrier diperkuat. Biasanya mengangkut pengiriman Nightium yang besar. Kalahkan mereka untuk mendapatkan uang.",
  str_monster_ability_2000311 = "Eclipsite baru yang muncul dan mungkin berevolusi dari Eclipsite lainnya. Ia mahir dalam menggunakan pedang ganda dan meluncurkan serangan ganda pada targetnya saat berhadapan.",
  str_monster_ability_2000321 = "Eclipsite tipe serangga yang bergerak cepat, diperintahkan untuk mengejar dan memburu targetnya dari jarak dekat.",
  str_monster_ability_2000341 = "Sejumlah besar bandit yang jago melarikan diri.",
  str_monster_ability_2000351 = "Eclipsite kuat yang bisa mendorong target dengan serangannya.",
  str_monster_ability_2000411 = "Eclipsite mutan yang ahli dalam serangan jarak jauh. Ketika elemennya adalah Fire, ia dapat memanggil Burning Rain untuk membakar target yang terkena. Ketika elemennya adalah Thunder, ia dapat memanggil Lightning Power untuk melumpuhkan target yang terkena.",
  str_monster_ability_2000421 = "Mahir dalam serangan jarak jauh dan memberikan buff ke Eclipsite di dekatnya dalam pertempuran.",
  str_monster_ability_2000431 = "Mahir dalam pertarungan jarak dekat. Di ambang kematian, ia akan menghampiri pemain dan meledak, menimbulkan damage pada semua target di sekitarnya.",
  str_monster_ability_2000441 = "Menyerang target dengan serangan jarak dekat. Efek serangan Aurorian yang tidak melawan elemennya akan banyak berkurang.",
  str_monster_ability_2000442 = "Melancarkan serangan jarak dekat terhadap targetnya, dan mengubah semua ubin di sepanjang jalur pergerakannya menjadi ubin dengan elemen yang sama dengan dirinya sendiri.",
  str_monster_ability_2000451 = "Memberikan debuff pada musuhnya.",
  str_monster_ability_2000501 = "Bisa menarik target yang jauh ke dekatnya dan menimbulkan damage besar pada target-target dalam 1 klaster di sekitar.",
  str_monster_ability_2000511 = "Attack Range sangat kecil. Namun, serangannya membuat Aurorian kehilangan energy dan meningkatkan jumlah putaran cooldown Active Skill.",
  str_monster_ability_2000521 = "Bisa mengunci elemen Tile. Elemen Tile di sekitar target akan terkunci setelah target terkena serangan. Elemen Tile di sekitarnya akan terkunci setelah bergerak.",
  str_monster_ability_2000531 = "Eclipsites yang sangat bagus dalam menyerang dari jarak jauh. Semakin jauh target yang diserang dari Vinesmark, semakin besar damage yang diterima target.",
  str_monster_ability_2000541 = "Serangan kuat Doomskull dapat menghancurkan ubin dalam jangkauan area yang luas.",
  str_monster_ability_2000551 = "Eclipsite langka dengan kemampuan untuk mengutuk. Ia akan melepaskan kutukan pada target. Aurorian yang dikutuk tidak dapat menggunakan Active Skill, bergerak, atau ditunjuk sebagai Kapten selama beberapa putaran.",
  str_monster_ability_2000561 = "Pemburu jarak jauh yang berganti posisi sebelum menyerang pada tiap putaran.",
  str_monster_ability_2000571 = "Daemon yang dikendalikan oleh Schummer. Mereka akan mengganggu pengerahan Aurorian. Jika Aurora Time tidak dapat dipicu dalam beberapa putaran, para Aurorian akan terjerumus ke dalam kegelapan.",
  str_monster_ability_2000581 = "Eclipsite yang dipanggil Formless. Monster tak berakal ini meluncurkan serangan bunuh diri pada musuhnya. Meledak jika tidak dihancurkan dalam sejumlah putaran tertentu dan menghancurkan lokasinya saat ini.",
  str_monster_ability_2000582 = "Sebuah Eclipsite dipanggil oleh Formless, monster tak berakal ini meluncurkan serangan bunuh diri pada musuh-musuhnya. Meledak jika tidak dihancurkan dalam jumlah putaran tertentu, memanggil Area yang Mengkhawatirkan.",
  str_monster_ability_2000601 = "Eclipsite tanpa kemampuan bertempur, tetapi dapat menempel pada Eclipsite dalam 1 klaster di sekitar. Setelah menempelkan diri, ia memberikan Shield pada Eclipsite dan meningkatkan serangannya.",
  str_monster_ability_2000602 = "Ia menempelkan diri pada Dawn dan memulihkan HP-nya saat berada dalam 1 klaster di sekitar Dawn.",
  str_monster_ability_2000611 = "Eclipsite yang tak bisa bertarung, tetapi bisa menempelkan dirinya pada seorang Aurorian dalam 1 klaster di sekitarnya. Begitu menempel, ia akan menurunkan poin Sanity Aurorian secara terus-menerus.",
  str_monster_ability_2000701 = "Setelah bergerak, menimbulkan damage dalam 4 tile berbentuk silang di sekitarnya. Begitu mencapai tepi Alchemy Board, mereka akan naik tingkat menjadi Enraged Rook, Fallen Knight, Eclipse Bishop, atau Deceptive Queen, sesuai dengan urutan kedatangannya.",
  str_monster_ability_2000702 = "Hanya dapat bergerak secara horizontal atau vertikal dari posisinya sendiri. Setelah bergerak, ia menimbulkan damage pada target dalam 1 klaster di sekitarnya. Saat menabrak target selagi bergerak, ia akan menimbulkan damage lebih tinggi pada target ini dan menjatuhkannya ke tepi papan.",
  str_monster_ability_2000703 = "Hanya dapat melompat secara diagonal. Setelah mendarat, ia menimbulkan damage di 4 Tile di sekitarnya dalam bentuk silang. Jika ada target di titik pendaratannya, ia akan menimbulkan damage yang sangat besar, memberikan efek Stun pada target, serta mendorong mundur target.",
  str_monster_ability_2000704 = "Hanya dapat bergerak secara diagonal. Menimbulkan damage pada target dalam jangkauan maksimum berbentuk silang.",
  str_monster_ability_2000705 = "Menimbulkan damage yang setara dengan persentase HP maksimum target kepada target dalam jangkauan maksimum berbentuk lingkaran.",
  str_monster_ability_2000711 = "Setelah bergerak, menimbulkan damage dalam 4 Tile berbentuk silang di sekitarnya. Begitu mencapai tepi Alchemy Board, mereka akan naik tingkat menjadi Enraged Rook - RAM, Fallen Knight - CHARGE, Eclipse Bishop - EX, atau Deceptive Queen, sesuai dengan urutan kedatangannya.",
  str_monster_ability_2000712 = "Hanya dapat bergerak secara horizontal atau vertikal dari posisinya sendiri. Setelah bergerak, ia menimbulkan damage pada target dalam 2 klaster di sekitarnya. Saat menabrak target selagi bergerak, ia akan menimbulkan damage lebih tinggi pada target ini dan menjatuhkannya ke tepi papan.",
  str_monster_ability_2000713 = "Hanya dapat melompat secara diagonal. Setelah mendarat, ia menimbulkan damage pada 1 klaster di sekitarnya. Jika ada target di titik pendaratannya, ia akan menimbulkan damage parah dan men-stun target, serta menjatuhkannya.",
  str_monster_ability_2000714 = "Hanya dapat bergerak secara diagonal. Menimbulkan damage pada target dalam jangkauan maksimum berbentuk silang dan mengurangi DEF target.",
  str_monster_ability_2000715 = "Menimbulkan damage yang setara dengan persentase HP maksimum target kepada target dalam jangkauan maksimum berbentuk lingkaran. Jika tidak ada target di 8 arah di sekitarnya, ia mendapatkan pembatas defensif.",
  str_monster_ability_2000901 = "Hancur sendiri setelah menghitung mundur ke nol, menghancurkan tile di tempatnya berada dan membuatnya tidak dapat digunakan.",
  str_monster_ability_2001001 = [[
Unggul dalam memanfaatkan medan yang hancur, memiliki kemampuan untuk memberikan damage besar pada unit di sekitar tile yang rusak.
Ketika Aurorian melewati tile yang rusak, penghitung kombo mereka tidak akan meningkat.]],
  str_monster_ability_2001301 = "Dengan skill ATK yang kuat dan biasanya tersembunyi di medan tempur, ia tidak dapat diserang kecuali ia menampakkan dirinya selama Aurora Time.",
  str_monster_ability_2001341 = "Menimbulkan damage dalam jumlah besar dan kebal saat berada di Tile Hijau.",
  str_monster_ability_2101301 = "Eclipsite Minion tidak melancarkan serangan dan biasanya tersembunyi di medan tempur, ia tidak dapat diserang kecuali ia menampakkan dirinya selama Aurora Time.",
  str_monster_ability_4001301 = "Menangani banyak kerusakan.",
  str_monster_ability_2001401 = "Sensitif dan lemah lembut, ia akan menghindari serangan Aurorian dengan segala cara.",
  str_monster_ability_2900271 = "Eclipsite bersenjata canggih yang mampu menggunakan skill dengan jangkauan layar penuh.",
  str_monster_ability_2900262 = "Tidak bisa bergerak sendiri, tetapi memiliki jangkauan serangan yang luas. Ia dapat menyerap materi gelap dan menjadikannya penghalang. Ia juga bisa menyerang dan mendorong tiga baris musuh di depannya.",
  str_monster_ability_2900263 = "Tidak bisa bergerak sendiri, tetapi memiliki jangkauan serangan yang luas. Ia dapat menyerap materi gelap dan menjadikannya penghalang. Ia juga bisa menyerang dan mendorong tiga baris musuh di depannya.",
  str_monster_ability_2900264 = "Menimbulkan damage pada 2 klaster di sekitar dan musuh dalam layar penuh. Bisa berubah menjadi Dawn Sprite untuk memulihkan HP.",
  str_monster_ability_2900281 = "Itu bisa memanggil beacon dan memulihkan HP beacon sambil memperoleh pengurangan damage berdasarkan jumlah beacon di sekitarnya. Ia memiliki serangan dengan jangkauan berbentuk menyilang, dan damage serta jangkuan skill-nya, yang bisa diisi ulang, ditentukan oleh jumlah beacon.",
  str_monster_ability_2900391 = "Tidak bisa bergerak sendiri dan hanya rentan terhadap Bomb Damage. Ia bisa memanggil bom, dan setelah terisi penuh, ia akan terus memanggil bom dan melepaskan Damage Skill area luas.",
  str_monster_ability_2900401 = "Tahan terhadap serangan fisik dan dapat menahan damage Serangan Normal. Memberikan damage pada target di depan dan dapat meluncurkan serangan layar penuh. Mampu memanggil Lightning Crystal.",
  str_monster_ability_2900402 = "Tahan terhadap damage Serangan Normal. Menimbulkan damage kepada target dalam jangkauan berbentuk silang atau layar penuh, memanggil petir pada area tertentu secara berkala. Menimbulkan damage layar penuh secara terus-menerus setelah berubah menjadi Rabid.",
  str_monster_ability_2900403 = "Ahli dalam serangan jarak jauh dan AoE, serta dapat menyinkronkan HP-nya. Schummer dengan HP terendah akan menyinkronkan HP-nya dengan Schummer HP dengan tertinggi di medan tempur, hingga 30% per regenerasi.",
  str_monster_ability_2900411 = "Memanggil bala bantuan dalam pertempuran. Jangkauan serangan kini menjadi seluruh lapangan, dan serangan akan menambahkan debuff pada musuh yang terkena yang menurunkan pertahanan mereka. Serangan normal yang marah akan mengenai dua kali.",
  str_monster_ability_2900421 = "Bisa menyerang area tertentu dan memanggil Spellhound untuk meminta bantuan. Menimbulkan damage pada target di depan atau di seluruh layar.",
  str_monster_ability_2900422 = "Menimbulkan damage pada target di depan atau di seluruh layar dan mendorong mundur unit musuh. Dapat memanggil Spikepest tepat di hadapannya.",
  str_monster_ability_2900431 = "Memanfaatkan tubuhnya yang besar untuk menyerang target di depannya. Ia menggali ke dalam tanah dan menyerang target terdekat saat muncul. Ia juga bisa memanggil Burst Bug.",
  str_monster_ability_2900441 = "Serangan normalnya disertai dengan knockback dan bisa memanggil Duplicate Crystal untuk membuat 1 elemental Pebble per putaran. Ia bisa mengonsumsi semua Pebble untuk meluncurkan serangan ke target yang damage-nya ditentukan oleh jumlah Pebble.",
  str_monster_ability_2900451 = "Akan bersembunyi di Lumiwall terjauh dari pemain; serangannya bisa mengubah elemen tile di jalur serangannya.",
  str_monster_ability_2920451 = "Menciptakan ilusi di sekitar target setelah menabrak mereka. Setiap Lumiwall mengurangi damage yang diterima oleh Phorosion, serta ATK-nya. Saat Awakened, Lumiwall menciptakan lebih banyak ilusi di setiap putaran.",
  str_monster_ability_2900452 = "Akan bersembunyi di Lumiwall terjauh dari pemain; serangannya bisa mengubah elemen tile di jalur serangannya.",
  str_monster_ability_2900501 = "Memiliki kemampuan untuk mengubah warna Tile Alchemy Board. Target yang terkena skill akan ditarik ke arahnya.",
  str_monster_ability_2900601 = "Ahli dalam serangan jarak luas. Bisa menarik target yang jauh ke arahnya dan mengubah elemen tile dari target yang dikenai dan tile dengan jarak luas di sekitarnya.",
  str_monster_ability_2900611 = "Tidak bisa bergerak, tetapi ahli dalam serangan berbentuk menyilang dan jarak luas; serangan akan membuat Aurorian kehilangan energi, sehingga meningkatkan jumlah putaran cooldown Active Skill; ia akan terbelah saat mati.",
  str_monster_ability_2900641 = "Cekatan dalam serangan jarak jauh. Mengunci elemen Tile di sekitarnya setelah bergerak, dan memiliki kemampuan untuk melakukan serangan balasan, mengunci elemen Tile di 1 klaster di sekitar Aurorian setiap kali mereka menggunakan Active Skill.",
  str_monster_ability_2900651 = "Ahli dalam serangan jarak luas; serangan jarak sangat jauh menimbulkan lebih banyak damage pada target yang lebih jauh; dapat memanggil Vinesmark untuk meminta bantuan.",
  str_monster_ability_2900661 = "Shatterblast akan menghancurkan semua tile di medan tempur. Serangan ini dapat menjatuhkan target dan melakukan serangan balik. Ini akan menghancurkan 2 tile acak di medan tempur tiap kali Aurorian melepaskan Active Skill.",
  str_monster_ability_2900662 = "Shatterblast akan menghancurkan semua tile di medan tempur. Serangan ini dapat menjatuhkan target.",
  str_monster_ability_2900671 = [[
Dapat menggunakan serangan berbentuk silang atau layar penuh dan memanggil petir. Saat marah, ia memperoleh kemampuan untuk menjatuhkan target kembali secara signifikan dan memberikan damage layar penuh dan damage besar.
Catatan: Ketika semua Daemon Schummer diaktifkan, Schummer akan mengeluarkan skill layar penuh yang memusnahkan semua Aurorian.]],
  str_monster_ability_2900681 = "Memanggil Nonentity yang bisa menghancurkan diri. Berkemampuan teleportasi yang andal dan bisa berteleportasi menjauh dari pemain, menyerang dari tepi Alchemy Board.",
  str_monster_ability_2900701 = "Serangannya menyebabkan efek knockback pada target; ia akan memantulkan damage jika diserang selagi bertahan; memiliki kekuatan pemulihan yang kuat; memanggil T256 setelah mati.",
  str_monster_ability_2900711 = "Sebuah konstruksi mekanis kuno yang muncul setelah T-1024 terbelah. Memiliki kemampuan serangan jarak jauh bawaan.",
  str_monster_ability_2910711 = "Sebuah droid fungsional dengan asal-usul yang tidak diketahui dan mampu melakukan serangan jarak jauh normal.",
  str_monster_ability_29107141 = "\"Beep! Beep!\"",
  str_monster_ability_29107111 = "\"Beep! Bzz!\"",
  str_monster_ability_2800241 = "Ia terlihat seperti lawan yang sangat kuat dengan kekuatan tersembunyi yang akan mendorong target di setiap putaran.",
  str_monster_ability_2900801 = "Mampu memerintahkan Lost Pawn untuk menimbulkan damage ke target di 1 klaster di sekitarnya. Dapat menjatuhkan target di sekitarnya dan meluncurkan Full-Screen Attack.",
  str_monster_ability_2900811 = "Mampu memerintahkan Lost Pawn untuk menimbulkan damage ke target di 1 klaster di sekitarnya. Dapat menjatuhkan target di sekitarnya dan meluncurkan Full-Screen Attack.",
  str_monster_ability_2900911 = "Dapat memberikan damage ke target di area yang luas di depannya dan memiliki kemampuan untuk melacak target.",
  str_monster_ability_29009111 = "Bisa menimbulkan damage pada target dalam area luas di depannya, serta mampu melacak target. Bisa memanggil Tentaclaw yang akan memengaruhi Sanity Aurorian.",
  str_monster_ability_2900912 = "Menyerang di mana pun pemain berada di ronde sebelumnya. Serangan areanya memberikan damage pada target dan melumpuhkannya. Monster ini akan bangkit kembali di lokasinya beberapa ronde setelah mati.",
  str_monster_ability_2901001 = "Menyerang dan mendorong mundur musuh di sekitar Tile Rusak. Menerjang unit musuh yang berada dalam jangkauan serangnya, lalu memukul mundur mereka. Berteleportasi berkali-kali akan merusak tile.",
  str_monster_ability_2901101 = "Bisa menyerang Aurorian dari jarak jauh dan berkemampuan mengendalikan Eclipsite.",
  str_monster_ability_2901201 = "Memiliki kekuatan yang unik dan menakutkan. Ketika HP Claymore turun ke jumlah tertentu, maka ia akan □□□□.",
  str_monster_ability_2901300 = "Ia memiliki kemampuan mengurangi damage yang mumpuni. Hanya bisa menimbulkan damage selama Aurora Time.",
  str_monster_ability_2901301 = "Ia memiliki kemampuan mengurangi damage yang mumpuni. Hanya bisa menimbulkan damage selama Aurora Time. Mampu memanggil Fearmonger Minion dengan ATK yang kuat untuk membantunya.",
  str_monster_ability_2901341 = "Memiliki DEF yang sangat kuat serta bisa memanggil Fearmonger Minion yang memiliki ATK kuat untuk membantunya. Namun, DEF Fearmonger akan menurun saat Fearmonger Minion tersingkir.",
  str_monster_ability_2901401 = "Serangan memanggil jenis Spikepest spesial yang tidak bisa disingkirkan menggunakan serangan penghapus papan. Jika pemain berdiri terlalu dekat saat menyerang, damage mereka terhadap kerumunan berkurang secara signifikan.",
  str_monster_ability_2901501 = "Mengeluarkan zat beracun sehingga sebagian dari serangan jarak dekat akan membuat pemain mengalami efek Paralyze. Jika pemain berdiri terlalu dekat saat menyerang, damage mereka terhadap kerumunan berkurang secara signifikan.",
  str_monster_ability_2901601 = "Ironstomp terus berbaris melintasi medan tempur, memberikan damage yang menghancurkan pada Tile apa pun yang dilaluinya.",
  str_monster_ability_2901701 = "Kittypus melepaskan tentakelnya dan menimbulkan damage besar pada Aurorian. (Ingat: Tentaclaw Kittypus mentransfer semua damage yang masuk ke inangnya!)",
  str_monster_ability_2901801 = "Menjaga jarak dari target dan mampu memanggil serta mengendalikan perangkap untuk membantu dirinya dalam pertempuran.",
  str_monster_ability_2901901 = "Mampu membuat pilihan taktis yang berbeda berdasarkan jarak dari Aurorian.",
  str_monster_ability_2901911 = "Saat menggila, ilmu pedang Castellan diperkuat dan menimbulkan sejumlah besar damage.",
  str_monster_ability_2902001 = "Licik dan berbahaya, dia pun ahli dalam serangan jarak jauh. Ketika musuh mendekat, dia melarikan diri dan meninggalkan bayangannya. Dia juga dapat memanggil beberapa hantu untuk membantunya bertempur di setiap putaran.",
  str_monster_ability_2902101 = "Munculkan banyak hantu dan lancarkan beragam skill hebat berdasarkan jarak antara Aurorian dan musuh di setiap putaran. Saat Fujikumo Nobutora - Devour menyingkirkan hantu, HP kamu akan dipulihkan.",
  str_monster_ability_2902201 = "Eclipsite mengerikan yang mengumpulkan Bruise Point saat terkena damage di siang hari. Mampu menyerang balik, Eclipsite ini memberikan DMG pada target di sekitar dan selalu memulihkan HP sesuai jumlah Bruise Point yang dia kumpulkan saat Aurorian melancarkan Active Skill. Kekuatannya tampak meningkat pesat saat malam tiba!",
  str_monster_ability_2902202 = "Mengumpulkan Bruise Point saat terkena damage di siang hari. Mampu menyerang balik, Helios memberikan DMG pada target di sekitar dan selalu memulihkan HP sesuai jumlah Bruise Point yang dia kumpulkan saat Aurorian melancarkan Active Skill. Dia berubah menjadi Eclipsite yang jauh lebih kuat lagi saat malam tiba, kehilangan efek Bruise untuk sementara, tetapi dapat bergerak 3 kali dalam setiap putaran.",
  str_monster_ability_2902301 = "Mampu berpindah-pindah dengan cerdik di medan tempur dan kebal terhadap Normal Attack Aurorian serta Ground Damage menggunakan rintangan. Saat rintangan hancur, langsung berpindah ke rintangan terdekat yang berada di sekitar. Skill yang dilancarkan oleh Claudia di dekat rintangan akan menjadi lebih kuat jika dilancarkan di darat.",
  str_monster_ability_2902401 = "Memiliki DEF kuat yang menyebabkan Claudia hampir tak terkalahkan di medan tempur.",
  str_monster_ability_2902501 = "Minos akan beralih antara kedua State berdasarkan jumlah tumpukan Mark. Saat berada dalam Mortal State, ia akan mereset semua tile yang dilewati menjadi Enhanced Tile dan saat berada dalam Minotaur State, ia akan mereset semua tile yang dilewati menjadi Weakened Tile. Semakin banyak Enhanced Tile yang tersebar di papan, semakin meningkat pula kekuatan Minos.",
  str_monster_ability_2902601 = "Dia bisa mengumpulkan Bruise ketika menerima damage saat siang hari, lalu mengonversinya menjadi HP saat malam hari, serta berubah menjadi Eclipsite yang jauh lebih kuat karena mampu menimbulkan damage pada semua musuh di layar.",
  str_monster_ability_2902701 = "Tampak seperti lawan tangguh yang mampu memukul mundur target di setiap putaran dan memanggil Eclipsite untuk membantunya dalam pertempuran. Bahkan, dia mampu mengendalikan kemunculan Dark Region.",
  str_monster_name_2910271 = "Coagulating Goldor",
  str_monster_ability_2910271 = "Tak hanya punya Full-Screen Attack, tapi pertahanannya juga sangat tinggi. Setelah menerima sejumlah tertentu damage di setiap putaran, ia tidak bisa lagi menerima damage.",
  str_monster_name_2100111 = "Spellhound Warden",
  str_monster_ability_2100111 = "Spellhound yang bermutasi dengan penghalang yang lebih kuat daripada Spellhound lainnya. Ia memiliki resistansi lebih besar terhadap damage.",
  str_monster_name_2910211 = "Bloodthirsty Umbrahulk",
  str_monster_ability_2910211 = "Eclipsite haus darah yang memulihkan HP setelah menyerang target. Serangan jarak dekatnya disertai dengan efek knockback, dan dapat memanggil Pebble. Ia juga dapat meluncurkan Full-Screen Attack, menimbulkan damage berdasarkan jumlah Pebble yang dipanggil.",
  str_monster_name_2910701 = "Modified T1024",
  str_monster_ability_2910701 = "Setelah modifikasi, T1024 dapat memperbaiki dirinya sendiri dengan menyerang. Serangan menyebabkan efek knockback pada target; ia akan memantulkan damage jika diserang selagi bertahan; memiliki kekuatan pemulihan yang kuat; memanggil T256 setelah mati.",
  str_monster_name_2910501 = "Shifting Solmorph",
  str_monster_name_2920501 = "Evolved Solmorph",
  str_monster_name_2910601 = "Shadowborn Solfall",
  str_monster_name_2910451 = "Umbral Phorosion",
  str_monster_ability_2910451 = "Akan bersembunyi di Lumiwall terjauh dari pemain. Serangannya bisa mengubah elemen tile di jalur serangannya. Hancurkan 3 Lumiwall untuk membuatnya muncul.",
  str_monster_name_2910403 = "Grievous Schummer",
  str_monster_ability_2910403 = "Ahli dalam serangan jarak jauh dan AoE, serta dapat menyinkronkan HP-nya. Sinkronisasi: Schummer dengan HP terendah akan menyinkronkan HP-nya dengan Schummer dengan HP tertinggi di medan tempur untuk memulihkan HP-nya.",
  str_monster_name_2920403 = "Shattered Schummer",
  str_monster_ability_2920403 = "Memulihkan HP saat diserang oleh Aurorian dengan elemen yang berlawanan. Ahli dalam serangan jarak jauh dan AoE, serta dapat menyinkronkan HP-nya. Sinkronisasi: Schummer dengan HP terendah akan menyinkronkan HP-nya dengan Schummer dengan HP tertinggi di medan tempur untuk memulihkan HP-nya.",
  str_monster_name_2910411 = "Rueful Gertzurde",
  str_monster_ability_2910411 = "Saat Gertzurde sedang dalam mode Rage, Normal Attack akan mengenai dua kali dan memanggil bala bantuan dalam pertempuran. Attack akan menambahkan debuff Attack dan Defense ke musuh yang terkena. Jangkauan Attack dari Gertzurde sekarang menjadi Full Grid.",
  str_monster_name_2910441 = "Ferocious Herkeros",
  str_monster_name_2910611 = "Augmented Deathless",
  str_monster_ability_2910611 = "Tidak bisa bergerak, tapi ahli dalam serangan berbentuk menyilang dan jarak luas; serangan akan membuat Aurorian kehilangan energi, sehingga meningkatkan jumlah putaran cooldown Active Skill; ia akan terbelah saat mati. Setiap kali satu Deathless mati, HP Deathless yang tersisa akan penuh kembali.",
  str_monster_name_2910252 = "Berserk Phantom",
  str_monster_ability_2910252 = "Memperoleh sejumlah ATK per putaran, dan setelah menerima sejumlah damage tertentu di setiap putaran, tidak ada damage lebih lanjut yang dapat ditimbulkan padanya. Meluncurkan serangan area berbentuk menyilang dan memanggil klon untuk bertarung di sampingnya. Setelah membuat kloning, ia akan menyerap HP klon sebelumnya untuk memulihkan HP dirinya sendiri. Ketika HP-nya kurang dari 50%, serangan normalnya akan menjadi serangan ganda, dan area serangan akan menjadi Full-Screen Attack.",
  str_monster_name_2100241 = "Ravenous Croweye",
  str_monster_ability_2100241 = "Eclipsite dengan kemampuan pemanggilan kelas menengah. Tidak dapat bergerak sendiri dan bertarung dengan memanggil Flatline.",
  str_monster_name_2910431 = "Earthsplitting Mara Sol",
  str_monster_ability_2910431 = "Lihai menggunakan tubuhnya yang besar untuk menyerang target di depannya. Ia menggali ke dalam tanah dan menyerang target terdekat saat muncul, sekaligus memanggil Burst Bug.",
  str_monster_name_2910141 = "Rabid Shelt",
  str_monster_ability_2910141 = "Ahli dalam serangan jarak dekat, ia dapat meluncurkan dua serangan normal di setiap putaran. Serangannya men-stun target yang terkena, dan juga dapat memanggil Shadowgeist serta Gloom Ghoul. Memiliki kemampuan untuk counterattack, memanggil Shadowgeist atau Gloom Ghoul untuk membantu dalam pertempuran saat Aurorian menggunakan skill.",
  str_monster_name_2910182 = "Rabid Shire",
  str_monster_ability_2910182 = "Ahli dalam serangan jarak dekat, ia dapat meluncurkan dua serangan normal di setiap putaran. Serangannya mendorong mundur target yang kena, dan juga dapat memanggil Shadowgeist serta Gloom Ghoul. Memiliki kemampuan untuk counterattack, memanggil Shadowgeist atau Gloom Ghoul untuk membantu dalam pertempuran saat Aurorian menggunakan skill.",
  str_monster_name_2910231 = "Bloodthirsty Philex",
  str_monster_ability_2910231 = "Eclipsite haus darah yang memulihkan HP setelah menyerang target. Pukulan senjatanya menimbulkan efek knockback dan serangan skill-nya mengakibatkan stun pada target.",
  str_monster_name_2910232 = "Analeptic Vani",
  str_monster_ability_2910232 = "Eclipsite haus darah yang memulihkan HP setelah menyerang target. Bisa menggunakan Energy untuk menyerang dari kejauhan dan memulihkan HP ke Philex.",
  str_monster_name_2910221 = "Boredom Splitter",
  str_monster_ability_2910221 = "Mengabaikan damage dari Aurorian dengan elemen yang sama seperti dirinya, dan memulihkan HP ketika diserang oleh Aurorian berlawanan terhadap elemen ini. Serangan normalnya memberikan efek knockback. Melepaskan berbagai serangan berdasarkan elemennya: Fire - Damage area besar dengan efek Burn, Thunder - damage layar penuh yang secara acak menghasilkan Spikepest.",
  str_monster_name_2100311 = "Augean Annihilator",
  str_monster_ability_2100311 = "Bisa menyerang targetnya hingga empat kali. Kebal terhadap skill damage. Movement Counter: Setiap kali Aurorian menggunakan Active Skill di putaran ini, jangkauan gerakan Augean Annihilator bertambah 2 di putaran berikutnya.",
  str_monster_name_21003111 = "Augean",
  str_monster_ability_21003111 = "Kebal terhadap damage skill.",
  str_monster_ability_21003112 = "Penghitung Gerakan: Setiap kali Aurorian menggunakan Skill Aktif di ronde ini, jangkauan pergerakan Augean Annihilator meningkat +2 di ronde berikutnya.",
  str_monster_name_21003111_en = "Augean",
  str_monster_ability_21003111_en = "Immune to skill damage.",
  str_monster_name_2250281 = "Enslaved Dark Summoner",
  str_monster_name_9100161 = "Necrotic Shadow",
  str_monster_desc_9100161 = "Ketika suatu Shadow memasuki Spire, kekuatan cahaya spesial yang ada di sini menyebabkan mereka berubah, meningkatkan kemampuan mereka untuk memburu mangsanya. Karena inilah, mereka dikerahkan secara khusus untuk mengatasi para penjelajah yang berani memasuki Spire.",
  str_monster_ability_9100161 = "Menggunakan tombaknya untuk menyerang target. Memiliki kemampuan untuk memanggil Darkwasp.",
  str_monster_name_5400231 = "Bloodthirsty Philex",
  str_monster_ability_5400231 = "Eclipsite haus darah yang memulihkan HP setelah menyerang target. Serangan jarak dekatnya memberikan efek knockback dan skill serangannya men-stun target.",
  str_monster_name_5400232 = "Analeptic Vani",
  str_monster_ability_5400232 = "Eclipsite haus darah yang memulihkan HP setelah menyerang target. Bisa menggunakan Energi untuk menyerang dari kejauhan dan memulihkan HP ke Philex.",
  str_monster_name_20005011 = "Rhein",
  str_monster_desc_20005011 = "Demi menghindar dari hukuman Lumopolis, dia menggunakan penguat untuk mengubah dirinya dari mantan pemimpin guild menjadi monster jahat.",
  str_monster_ability_20005011 = "Rhein yang sudah bermutasi dapat menarik target yang jauh untuk mendekat, lalu meluncurkan serangan dan Spikepest ke target dalam 1 klaster di sekitarnya.",
  str_monster_name_20002441 = "Lachon Hermes",
  str_monster_desc_20002441 = "Melalui hasrat berkuasa dan berumur panjang, ia turun derajat menjadi antek Eclipse, dan ujungnya menjadi monster seperti yang kau lihat di depanmu.",
  str_monster_ability_20002441 = "Lachon yang sudah bermutasi memperoleh kemampuan pemanggilan yang canggih. Dia tidak bisa bergerak dan bertarung dengan memanggil kelompok Eclipsite.",
  str_monster_name_3900281 = "Nefarious Dark Summoner",
  str_monster_alias_3900281 = "Codex Kehancuran",
  str_monster_desc_3900281 = [[
