  str_monster_ability_3910451 = "Illusion tercipta di lokasi tetap saat menggunakan Ranged Attack, dan tercipta di samping target saat menabraknya.",
  str_monster_name_2001501 = "Hantu",
  str_monster_desc_2001501 = "Monster Far East spesial yang disebut \"hidup segan mati tak mau\" dan sangat memusuhi yang hidup.",
  str_monster_ability_2001501 = "Kemampuan bertarung mereka mungkin tidak menakutkan, tetapi jumlah mereka menggertak.",
  str_monster_name_21601191 = "Revy",
  str_monster_name_21601191_en = "Revy",
  str_monster_name_21601171 = "Gram",
  str_monster_name_21601171_en = "Gram",
  str_monster_name_21601291 = "Luke",
  str_monster_name_21601291_en = "Luke",
  str_monster_name_21500991 = "Areia",
  str_monster_name_21500991_en = "Areia",
  str_monster_name_21500751 = "Odi",
  str_monster_name_21500751_en = "Odi",
  str_monster_name_21300531 = "Jomu",
  str_monster_name_21300531_en = "Jomu",
  str_monster_name_21400401 = "Joanie Boom",
  str_monster_name_21400401_en = "Joanie Boom",
  str_monster_desc_21601191 = "Seorang rekrutan baru di Illumina. Meskipun genius dalam pertempuran, dia suka menyendiri, impulsif, dan komunikator yang buruk. Dia sangat ingin meraih kemenangan dalam pertempuran dan membuktikan dirinya.",
  str_monster_desc_21601171 = "Veteran yang pernah bertugas di garis pertahanan Illumina ini sudah pensiun dan kini bekerja di bidang logistik. Keras di luar, tetapi lembut di dalam, dia adalah teman yang bisa diandalkan di medan tempur.",
  str_monster_desc_21601291 = "Vice Komandan pasukan tentara bayaran Umbraton. Seorang pria terhormat, tahu segalanya tentang seluk-beluk kota. Sekarang dia bekerja keras untuk memperluas pasukan tentara bayaran.",
  str_monster_desc_21500991 = "Pedagang pengembara di Umbraton. Lahir dengan kutukan yang membuatnya sakit anemia, dan harus memakai pedang ajaibnya untuk bertahan hidup.",
  str_monster_desc_21500751 = "Pegawai teknisi Rediesel Wrench yang sangat percaya diri dengan teknologi komunikasinya. Dia suka mengeluh dan meneriaki orang lain di Comm Channel, tapi dia kebingungan saat ada masalah.",
  str_monster_desc_21300531 = "Pedagang dari Rediesel Wrench. Tipikal pedagang pengumpul uang, dia tidak pernah melewatkan kesempatan untuk menghasilkan keuntungan... Bahkan ketika dihadapkan dengan beberapa tugas berat, pisau pendeknya biasanya berhasil.",
  str_monster_desc_21400401 = "Gadis kecil yang terkagum-kagum dengan ledakan, dan menjadi sangat bersemangat ketika sesuatu meledak. Kegilaan seperti itu merupakan tiket masuknya ke Rediesel Wrench. Sebagai seorang Rediesel, dia menghabiskan seluruh waktunya mempelajari bahan peledak dan tidak peduli jika hidupnya dalam bahaya...",
  str_monster_ability_21601191 = "Mahir melancarkan serangan jarak jauh, menimbulkan damage pada satu area kolom.",
  str_monster_ability_21601171 = "Mahir melancarkan serangan jarak dekat, dia menggunakan skill-nya untuk memberikan damage area yang luas kepada musuh di sekitarnya.",
  str_monster_ability_21601291 = "Mahir melancarkan serangan jarak jauh, dia menggunakan skill dengan jangkauan layar penuh miliknya untuk memberikan damage dan Parasitic Mark pada musuh. Setiap kali musuh bergerak, mereka akan terkena damage dari Parasitic Mark.",
  str_monster_ability_21500991 = "Mahir melancarkan serangan area, skill-nya meningkatkan ACT dan ATK-nya sendiri untuk memberikan damage area yang luas.",
  str_monster_ability_21500751 = "Mahir melancarkan serangan jarak jauh, serangannya memberi efek Poison.",
  str_monster_ability_21300531 = "Mahir melancarkan serangan jarak dekat, serangannya memberikan efek Bleed.",
  str_monster_ability_21400401 = "Dia tidak bergerak, melainkan melancarkan serangan di area yang luas, mengubah elemen ubin yang berada dalam jangkauan, dan memberikan efek Burn.",
  str_monster_name_1300221 = "Chainsaw Rick",
  str_monster_desc_1300221 = "Bocah pendek yang berisik, gila, tak pernah lelah dan selalu mengenakan helm kelinci. Dia terus-menerus mendorong dirinya dalam pertempuran dan sering disalah artikan sebagai orang yang nekat. Dia masih hidup sampai sekarang ini adalah sebuah keajaiban.",
  str_monster_ability_1300221 = "Chainsaw Rick menimbulkan damage pada unit musuh terdekat di sekitar tile Merah.",
  str_monster_name_1300521 = "Dove",
  str_monster_desc_1300521 = "Pembawa surat yang bekerja untuk Illumina Federation, tapi dia bukan seorang anggota. Dia hanya menyediakan layanan pos, dan benar-benar pemalas yang tak profesional. Dia bersedia melakukan apa saja untuk menunda atau meninggalkan pekerjaan.",
  str_monster_ability_1300521 = "Dove menimbulkan damage pada unit musuh terdekat di sekitar tile Hijau.",
  str_monster_name_1400321 = "Angel",
  str_monster_desc_1400321 = "Staf Lumo Hall of Justice dan malaikat bersayap satu. Dia orang yang sensitif dan memiliki harga diri tinggi. Meskipun masih muda, Angel telah hidup melewati masa perang.",
  str_monster_ability_1400321 = "Angel menimbulkan damage pada unit musuh terdekat di sekitar tile Kuning.",
  str_monster_name_1501491 = "Roy",
  str_monster_desc_1501491 = "Manajer logistik Rediesel Wrench. Meskipun dia tampak berantakan, sebenarnya dia sangat memedulikan dan protektif terhadap semua orang di Rediesel Wrench.",
  str_monster_ability_1501491 = "Roy menimbulkan damage pada unit musuh terdekat di sekitar tile Kuning.",
  str_monster_name_1400411 = "Ms. Blanc",
  str_monster_desc_1400411 = "Wanita yang tenang dan elegan, dia bertindak sebagai pemandu bagi pendatang baru di Lumopolis. Dia tetap tenang bahkan di tengah bencana, mengisyaratkan masa lalu yang luar biasa. Namun, ketika ditanya tentang hal itu, dia hanya memberikan senyuman misterius...",
  str_monster_ability_1400411 = "Ms. Blanc tak hanya menimbulkan damage pada unit musuh terdekat di sekitar tile Biru, tetapi juga mengubah semua tile di sekelilingnya menjadi Biru.",
  str_monster_name_1300471 = "Zoya",
  str_monster_desc_1300471 = "Peneliti jenius dari Illumina Federation yang fokus pada rasa haus akan pengetahuan... Itu dan seorang Legion Commander. Meskipun dia tampak pendiam, mendekatinya dengan tergesa-gesa mungkin akan mengundang cemoohan. Demi kebaikan semua orang, sebaiknya jangan terlalu sering mengganggunya.",
  str_monster_ability_1300471 = "Zoya memulihkan HP rekan tim yang memiliki HP terendah.",
  str_monster_name_1300531 = "Jomu",
  str_monster_desc_1300531 = "Pedagang dari Rediesel Wrench. Tipikal pedagang pengumpul uang, dia tidak pernah melewatkan kesempatan untuk menghasilkan keuntungan... Bahkan ketika dihadapkan dengan beberapa tugas berat, pisau pendeknya biasanya berhasil.",
  str_monster_ability_1300531 = "Jomu memberikan damage pada musuh dalam 1 klaster di sekitar.",
  str_monster_name_1201631 = "Tourdog",
  str_monster_desc_1201631 = "Makhluk misterius dari utara yang menyukai permainan, dan setiap kali menemukan seseorang, ia akan selalu bertanya, \"Kamu punya ide?\".",
  str_monster_ability_1201631 = "Memiliki semangat yang membara untuk berdansa.",
  str_monster_name_1600061 = "Carleen",
  str_monster_desc_1600061 = "Lumo Gardens Kapten yang juga merupakan putri Schwartz. Wanita bangsawan yang tak pernah bisa menoleransi perbuatan keji, dia menghormati ketertiban dan membenci kejahatan. Yang lebih menakjubkan adalah dia menjadi seorang kesatria, bukan dengan nama ayahnya, tetapi dengan usahanya sendiri.",
  str_monster_ability_1600061 = "Carleen tak hanya menimbulkan damage pada unit musuh terdekat di sekitar tile Biru, tetapi juga mendorong mundur dan menimbulkan damage pada musuh lain di kolom yang sama.",
  str_monster_name_1600111 = "Sharona",
  str_monster_desc_1600111 = "Seorang Legion Commander dari Illumina Federation dan perempuan cantik nan dingin yang memiliki kekuatan naga. Meskipun terlihat tidak ramah, dia orang yang bisa diandalkan. Asal usulnya diselimuti misteri. Setelah bergabung dengan Illumina Federation, dia menjadi Legion Commander karena prestasi militernya. Dia selalu membawa pedang Azure Flame, yang menunjukkan latar belakangnya.",
  str_monster_ability_1600111 = "Sharona memberikan damage pada musuh dalam 2 klaster di sekitar.",
  str_monster_name_1500331 = "Vice",
  str_monster_desc_1500331 = "Anggota Illumina Federation dengan kepribadian yang lembut. Tidak hanya sangat berbakat, pekerja keras, dan bersemangat, dia juga telah menerima pelatihan intensif sejak usia muda berkat pengakuan dari pejabat tinggi. Dia sekarang ditunjuk sebagai kapten ekspedisi yang bertanggung jawab atas pencarian dan penggalian reruntuhan kuno.",
  str_monster_ability_1500331 = "Vice tak hanya menimbulkan damage pada unit musuh terdekat di sekitar tile Biru, tetapi juga menimbulkan damage beruntun pada musuh terdekat.",
  str_monster_name_1600021 = "Hiiro",
  str_monster_desc_1600021 = "Gadis dengan kemampuan bertarung yang tak tertandingi. Sebagai Legion Commander dari Illumina Federation, dia dikenal sebagai orang yang tegas, serius, dan tekun. Menghadapi setiap pertempuran dengan penuh keyakinan, dia mencetak banyak kemenangan dengan katana di tangannya.",
  str_monster_ability_1600021 = "Hiiro tak hanya menimbulkan damage pada unit musuh terdekat di sekitar tile Hijau, tetapi juga melancarkan Crimson Sakura pada musuh terdekat.",
  str_monster_name_2800601 = "Bullock 8",
  str_monster_desc_2800601 = "Dirancang khusus untuk balapan dan mampu beradaptasi pada medan yang berat, kendaraan ini tak hanya kuat, melainkan juga dilengkapi dengan senjata lengkap",
  str_monster_ability_2800601 = "Tidak bisa mengeluarkan skill tanpa pengemudi.",
  str_monster_name_2000191 = "Toto",
  str_monster_desc_2000191 = "Kenyataannya, setiap Slasher kecil juga mempunyai mimpi. Hanya saja, tak ada yang menunjukkan rasa peduli untuk menanyakannya.",
  str_monster_name_1500901 = "Barbara",
  str_monster_desc_1500901 = "Penyanyi idola dari Rediesel Wrench. Barbara terlihat lembut dan baik di permukaan tetapi menunjukkan sikapnya yang mudah tersinggung saat bertemu dengan penggemar yang terlalu mengganggu. Dia melancong ke mana-mana untuk menjadi idola paling populer.",
  str_monster_ability_1500901 = "Barbara memberikan kerusakan pada semua musuh yang menempati ubin Merah.",
  str_monster_name_1501141 = "Genevieve",
  str_monster_desc_1501141 = "Pemburu hadiah yang elegan dari True Order, penikmat jus yang berpembawaan ceria. Saat ini, dia sedang berusaha membangun jaringan intelijen untuk melacak keberadaan seseorang.",
  str_monster_ability_1501141 = "Genevieve melompat ke arah musuh yang terletak secara diagonal dari posisinya, dan setelah mendarat, memberikan damage ke 1 cluster di sekitarnya. Jika ada target di titik pendaratan, dia memberikan kerusakan parah pada target dan memukul mundur mereka.",
  str_monster_name_1600141 = "Schwartz",
  str_monster_desc_1600141 = "Governor of Lumopolis dan penguasanya saat ini. Posisi dan statusnya menempatkan dia jauh di atas yang lain. Keberhasilan seperti itu tidak didapatkannya secara cuma-cuma, dan rasa kesepian menjadi teman baiknya. Meski begitu, Schwartz terus menghabiskan waktu berjam-jam untuk menjaga ketertiban di Lumopolis, dan selalu berusaha melakukan yang terbaik tanpa pernah lengah.",
  str_monster_ability_1600141 = "Schwartz memberikan kerusakan pada semua musuh di medan perang sambil memanggil Penjaga Lumo untuk melenyapkan musuhnya.",
  str_monster_name_2001701 = "Wailer",
  str_monster_desc_2001701 = "Eclipsite yang sebagian besar aktivitasnya dilakukan di malam hari. Saat siang hari, ia hanya meringkuk di tanah dan tak bisa bergerak.",
  str_monster_ability_2001701 = "Saat siang hari, ia hanya meringkuk di tanah dan berada dalam posisi bertahan. Saat malam tiba, ia kembali menampakkan wujud aslinya.",
  str_monster_name_3902501 = "Minos",
  str_monster_name_3902501_en = "Minos",
  str_monster_alias_3902501 = "Codex Kehancuran",
  str_monster_desc_3902501 = [[
1. Monster Nefarious akan terus memperkuat dirinya sesuai dengan jumlah damage yang diterimanya. Setiap tumpukan peningkatan meningkatkan ATK sebesar 10%.
2. Masing-masing ATK dan DEF monster meningkat sebesar 8% dan 5% pada setiap putaran.]],
  str_monster_ability_3902501 = "Memanggil ubin yang melemah pada posisi acak setiap putaran. Memberikan kerusakan pada target satu kali setiap kali melewati ubin yang melemah. Keahlian yang dapat ditagih memberikan kerusakan layar penuh.",
  str_monster_name_3903101 = "Barbara",
  str_monster_name_3903101_en = "Barbara",
  str_monster_alias_3903101 = "Codex Kehancuran",
  str_monster_desc_3903101 = [[
1. Monster Nefarious akan terus memperkuat dirinya sesuai dengan jumlah damage yang diterimanya. Setiap tumpukan peningkatan meningkatkan ATK sebesar 10%.
2. Masing-masing ATK dan DEF monster meningkat sebesar 8% dan 5% pada setiap putaran.]],
  str_monster_ability_3903101 = "Selalu berpindah ke titik yang paling jauh dari target. Menimbulkan Area Damage yang besar, kecuali ke sejumlah zona aman tertentu. Skill yang bisa diisi ulang menimbulkan Full-screen Damage dan mendorong mundur target.",
  str_monster_name_3903201 = "Connolly",
  str_monster_name_3903201_en = "Connolly",
  str_monster_name_3903301 = "Beryl",
  str_monster_name_3903301_en = "Beryl",
  str_monster_alias_3903201 = "Codex Kehancuran",
  str_monster_alias_3903301 = "Codex Kehancuran",
  str_monster_desc_3903201 = [[
1. Monster Nefarious akan terus memperkuat dirinya sesuai dengan jumlah damage yang diterimanya. Setiap tumpukan peningkatan meningkatkan ATK sebesar 10%.
2. Masing-masing ATK dan DEF monster meningkat sebesar 8% dan 5% pada setiap putaran.]],
  str_monster_desc_3903301 = [[
1. Monster Nefarious akan terus memperkuat dirinya sesuai dengan jumlah damage yang diterimanya. Setiap tumpukan peningkatan meningkatkan ATK sebesar 10%.
2. Masing-masing ATK dan DEF monster meningkat sebesar 8% dan 5% pada setiap putaran.]],
  str_monster_ability_3903201 = "Tentakel akan muncul di titik acak pada setiap putaran untuk menghambat pergerakan Aurorian. HP tentakel meningkat pada setiap putaran. Skill menimbulkan Area Damage dan skill yang bisa diisi ulang menimbulkan Full-screen Damage.",
  str_monster_ability_3903301 = "Sanguine Crystal akan muncul di titik acak pada setiap putaran untuk menghambat pergerakan Aurorian. Saat Nefarious Beryl melewati Crystal, ia akan menghancurkan Crystal itu dan memperoleh tambahan ATK. Skill menimbulkan Area Damage dan skill yang bisa diisi ulang menimbulkan Full-screen Damage.",
  str_monster_name_3903401 = "Schwartz",
  str_monster_name_3903401_en = "Schwartz",
  str_monster_ability_2900913 = "Menyerang di mana pun pemain berada di babak sebelumnya. Monster ini akan bangkit kembali di lokasinya beberapa ronde setelah mati.",
  str_monster_name_2903001 = "Penjaga Inti",
  str_monster_name_2903001_en = "Core Guardian",
  str_monster_desc_2903001 = "Penjaga raksasa yang melindungi inti energi kapal. Itu akan bangun dan bertarung ketika Core berada di bawah ancaman.",
  str_monster_ability_2903001 = "Makhluk kuat ini memiliki kemampuan untuk mengubah seluruh papan, tetapi juga memiliki kelemahan.",
  str_monster_name_2001801 = "Roda Penghancur",
  str_monster_desc_2001801 = "Salah satu sistem pertahanan Inti Energi dan sulit dihancurkan. Ini akan meluncurkan serangan tanpa akhir pada musuh.",
  str_monster_ability_2001801 = "Makhluk yang tidak bisa dihancurkan. Ketika HP-nya turun ke nol, ia akan memasuki keadaan lumpuh. Itu menjadi tak terkalahkan dalam keadaan itu dan secara otomatis akan memulihkan HP setiap putaran. Ketika HP-nya penuh, ia akan mendapatkan kembali kemampuan untuk bergerak dan mengambil tindakan.",
  str_monster_name_2001802 = "Modul Pembekuan",
  str_monster_desc_2001802 = [[
Modul pendingin memungkinkan Core Guardian yang kuat berfungsi secara normal.
Itu mungkin satu-satunya kelemahan penjaga, tetapi jika Anda mendekatinya dengan gegabah, Anda akan terbakar oleh panas yang dipancarkannya.]],
  str_monster_ability_2001802 = "Mengacaukan suatu area dan menimbulkan damage pada Aurorian untuk setiap Tile yang dipindahkan dalam area yang dikacaukan.",
  str_monster_desc_2900311 = "Eclipsite yang luar biasa kuat. Konon, peperangan yang ia ikuti sudah tak terhitung jumlahnya. Makhluk kuat yang berhasil selamat dari hujan peluru dan bom. Tak ada yang tahu berapa banyak musuh yang berhasil ia tumbangkan dengan pedangnya.",
  str_monster_passiveskill_name_2900144 = "Tiba-tiba: Gloom Ghoul",
  str_monster_passiveskill_desc_2900144 = "Memanggil Rune di lokasi acak, yang berubah menjadi Gloom Ghoul dalam 3 ronde.",
  str_monster_passiveskill_name_2900184 = "Tiba-tiba: Shadowgeist",
  str_monster_passiveskill_desc_2900184 = "Memanggil Rune di lokasi acak, yang berubah menjadi Shadowgeist dalam 3 ronde.",
  str_monster_passiveskill_name_2000451 = "Pengorbanan hamba",
  str_monster_passiveskill_desc_2000451 = "Memulihkan sejumlah HP ke pemain saat terbunuh.",
  str_monster_passiveskill_name_2900611 = "Tanpa kematian: Klon",
  str_monster_passiveskill_desc_2900611 = "Terbagi menjadi unit tempur yang lebih kecil saat terbunuh.",
  str_monster_passiveskill_name_2900641 = "Caracalune: Kontaminasi",
  str_monster_passiveskill_desc_2900641 = "Memberikan sedikit kerusakan pada pemain dan mengunci ubin dalam 1 kelompok pemain yang mengelilinginya.",
  str_monster_passiveskill_name_2900661 = "Shatterblast: Earth Rift",
  str_monster_passiveskill_desc_2900661 = "Menghasilkan 2 ubin yang rusak secara acak di lapangan.",
  str_monster_passiveskill_name_2900671 = "Schummer: Pemusnahan",
  str_monster_passiveskill_desc_2900671 = "Ketika semua Daemon Schummer telah diaktifkan, Schummer mengeluarkan keterampilan yang mengalahkan semua yang ada di layar.",
  str_monster_passiveskill_name_2902200 = "Night Counterattack",
  str_monster_passiveskill_desc_2902200 = "Memberikan kerusakan pada target dalam 2 cluster di sekitarnya dan memulihkan beberapa HP berdasarkan akumulasi Memar.",
  str_monster_passiveskill_name_2902301 = "Claudia: Platform",
  str_monster_passiveskill_desc_2902301 = "Claudia tidak dapat dirusak oleh serangan normal saat dia berdiri di atas platform atau Asher.",
  str_monster_passiveskill_name1_2902301 = "Claudia: Teleportasi",
  str_monster_passiveskill_desc1_2902301 = "Ketika platform di bawahnya rusak, atau Asher tersingkir, Claudia berteleportasi ke platform lain dalam 2 cluster di sekitarnya atau jatuh ke tanah.",
  str_monster_passiveskill_name_9000101 = "Penerbangan",
  str_monster_passiveskill_desc_9000101 = "Musuh ini dapat bergerak melintasi jurang.",
  str_monster_passiveskill_name_2000311 = "Double Slash",
  str_monster_passiveskill_desc_2000311 = "Dreadblades menyerang target dua kali.",
  str_monster_passiveskill_name_2000221 = "Spikepest",
  str_monster_passiveskill_desc_2000221 = "Menghasilkan Spikepest pada ubin yang telah diinjak.",
  str_monster_passiveskill_name_2000511 = "Confusion",
  str_monster_passiveskill_desc_2000511 = "Saat mengenai target, meningkatkan putaran cooldown dari skill aktif Aurorian ini.",
  str_monster_passiveskill_name_2000521 = "Lumina Imprisonment",
  str_monster_passiveskill_desc_2000521 = "Mengunci ubin di 1 cluster di sekitarnya setelah dipindahkan. Kehilangan efek saat tertegun, ketakutan, lumpuh, atau terkena efek kontrol lainnya.",
  str_monster_passiveskill_name_2000551 = "Grudge",
  str_monster_passiveskill_desc_2000551 = "Saat menyerang, memberikan Curse kepada Aurorian yang elemennya sama. Aurorian yang terkena Curse tidak akan bisa menyerang atau menggunakan Active Skill.",
  str_monster_passiveskill_name1_2000551 = "Pembuangan Dendam",
  str_monster_passiveskill_desc1_2000551 = "Saat terbunuh, menghilangkan kutukan yang ditempatkan oleh Fay Terkutuklah pada Aurorian dari elemen yang sama.",
  str_monster_passiveskill_name_2001701 = "Parade Wailer",
  str_monster_passiveskill_desc_2001701 = "Ia bersujud di tanah dalam posisi bertahan di siang hari. Begitu malam dimulai, ia kembali ke keadaan aslinya dan menyerang Aurorian.",
  str_monster_passiveskill_name_2901001 = "Pria dalam Bingkai",
  str_monster_passiveskill_desc_2901001 = "Bersembunyi saat berada di ubin yang rusak, hanya menerima kerusakan area, dan menjadi kebal terhadap serangan dan keterampilan normal saat ubin dipilih.",
  str_monster_passiveskill_name_2901301 = "Aurora Melemah",
  str_monster_passiveskill_desc_2901301 = "Damage yang timbul selama Aurora Time meningkat tajam.",
  str_monster_passiveskill_name_2001301 = "Aurora Vital",
  str_monster_passiveskill_desc_2001301 = "Hanya bisa diserang oleh Aurorian selama Aurora Time.",
  str_monster_passiveskill_name_2903001 = "Penjaga Inti Utuh",
  str_monster_passiveskill_desc_2903001 = "Saat Penjaga Inti waspada, hanya menerima kerusakan target tunggal dari serangan yang tidak memilih ubin dan menjadi kebal terhadap serangan normal dan area.",
  str_monster_passiveskill_name1_2903001 = "Penjaga Inti Lumpuh",
  str_monster_passiveskill_desc1_2903001 = "Lebih banyak titik lemah terekspos setelah Core Guardian dilumpuhkan, dan kekebalan kerusakan hilang.",
  str_monster_passiveskill_name_2000901 = "Penghancuran Diri Berwaktu",
  str_monster_passiveskill_desc_2000901 = "Menghancurkan diri sendiri setelah hitungan mundur mencapai nol, menghancurkan ubin di bawahnya.",
  str_monster_passiveskill_name_2001801 = "Roda Penghancur Lumpuh",
  str_monster_passiveskill_desc_2001801 = "Ketika HP Crusher Wheel berkurang menjadi nol, ia memasuki keadaan lumpuh. Ketika HPnya penuh lagi, ia mendapatkan kembali kemampuan untuk bergerak dan mengambil tindakan.",
  str_monster_passiveskill_name_2001802 = "Kegagalan Modul Pembekuan",
  str_monster_passiveskill_desc_2001802 = "Kelemahan Penjaga Inti. Ketika HP Modul Pembekuan berkurang menjadi nol, Penjaga Inti memasuki keadaan lumpuh.",
  str_monster_passiveskill_name_2900301 = "Perisai Bowling",
  str_monster_passiveskill_desc_2900301 = "Energy Shield melindungi Bowlinger dari kerusakan. (Melumpuhkannya dengan menyerang area yang tidak terlindungi dengan Deathrider untuk memberikan kerusakan pada Bowlinger secara efektif)",
  str_monster_passiveskill_name_2910281 = "Perisai Catu Daya",
  str_monster_passiveskill_desc_2910281 = "Setiap Dark Summoner Beacon di field mengurangi damage yang diterima oleh Dark Summoner.",
  str_monster_passiveskill_name_2010481 = "Lumiwall",
  str_monster_passiveskill_desc_2010481 = "Aurorian hanya dapat memberikan kerusakan pada Lumiwall setelah Phorosion bersembunyi di Lumiwall ini. Lumiwall lain tidak dapat diserang.",
  str_monster_passiveskill_name_2901201 = "Light of the Deceiver",
  str_monster_passiveskill_desc_2901201 = "Claymore memiliki kemampuan untuk menghubungkan dan bergerak di sepanjang ubin dengan warna yang sama.",
  str_monster_passiveskill_name1_2901201 = "Tomb of the Undying",
  str_monster_passiveskill_desc1_2901201 = "Setelah Call of the Grave menghilang, Claymore mendapatkan skill counter yang memberikan damage kepada Aurorian berdasarkan ATK dari Aurorian yang menggunakan skill tersebut dan memulihkan HPnya sendiri.",
  str_monster_passiveskill_name_2900312 = "Double Slash",
  str_monster_passiveskill_desc_2900312 = "Augan menyerang target dua kali.",
  str_monster_passiveskill_name1_2900312 = "Burrow",
  str_monster_passiveskill_desc1_2900312 = "Meningkatkan jarak gerakan sebanyak 2 ubin dan pulih di ronde berikutnya.",
  str_monster_passiveskill_name_3900451 = "Kekuatan Jahat",
  str_monster_passiveskill_desc_3900451 = [[
Saat monster jahat menerima kerusakan, efek penghitung elemen meningkat 100%.
Monster jahat akan terus meningkatkan diri mereka sendiri sesuai dengan kerusakan yang mereka terima. Setiap tumpukan peningkatan meningkatkan ATK mereka sebesar 10%.
ATK monster jahat meningkat sebesar 8%, dan DEF meningkat sebesar 5% setiap putaran.]],
  str_monster_passiveskill_name_3910281 = "Energi Magnet",
  str_monster_passiveskill_desc_3910281 = "Setiap Dark Summoner Beacon di field meningkatkan ATK Dark Summoner.",
  str_monster_passiveskill_name_3903101 = "Perisai Jahat",
  str_monster_passiveskill_desc_3903101 = "Kebal terhadap kerusakan selama fase aksinya.",
  str_monster_passiveskill_name_3903301 = "Jahat: Pemanggilan Kristal",
  str_monster_passiveskill_desc_3903301 = "Menghasilkan Kristal Sanguine di lokasi acak di lapangan setiap putaran (ada batasan jumlah maksimum).",
  str_monster_passiveskill_name_3903201 = "Jahat: Lahir dari Ketakutan",
  str_monster_passiveskill_desc_3903201 = "Menghasilkan Tentacles di lokasi acak di lapangan setiap putaran (ada batasan jumlah maksimum).",
  str_monster_passiveskill_name_3902501 = "Jahat: Ditunjuk Melemah",
  str_monster_passiveskill_desc_3902501 = "Menghasilkan ubin yang melemah di lokasi acak di lapangan setiap putaran.",
  str_monster_passiveskill_name_2901341 = "Shattered Heart",
  str_monster_passiveskill_desc_2901341 = "Mengurangi DEF Fearmonger setiap kali Minion Fearmonger mati.",
  str_monster_passiveskill_name_29009211 = "Collapsed Armor",
  str_monster_passiveskill_desc_29009211 = "DEF awal Hylingerr sangat tinggi, tetapi akan menurun hingga minimum 40% seiring menurunnya Sanity Aurorian.",
  str_monster_passiveskill_name_2912101 = "Ghost Devourer",
  str_monster_passiveskill_desc_2912101 = [[
Memulihkan 1% dari maksimum HP saat menerima hantu.
Mengurangi DEF sendiri sebesar 1% saat hantu di lapangan mati.]],
  str_monster_name_2903901 = "Casta",
  str_monster_name_2903901_en = "Casta",
  str_monster_desc_2903901 = "Terlihat menyendiri, tapi sebenarnya sangat bertanggung jawab. Bekerja sama dengan Pollux untuk membentuk duo tentara bayaran yang dijuluki \"Darah Raven\" untuk membela anak-anak yang tinggal di gereja dengan lebih baik.",
  str_monster_ability_2903901 = "Menyerang musuh dalam jarak dekat dengan bayonet atau menyerang mereka dari jarak jauh dengan peluru. Menyerang musuh dengan keterampilan yang berbeda sesuai dengan lokasi mereka.",
  str_monster_passiveskill_name_29039011 = "Roulette Rusia: Penghitung",
  str_monster_passiveskill_desc_29039011 = "Setiap kali Aurorian menggunakan Skill Aktif, Casta memindahkan 2 ubin ke arah Aurorian. Ketika ada Aurorian dalam 1 cluster sekitar Casta, dia mengeluarkan skill untuk menyerang Aurorian.",
  str_monster_passiveskill_desc_29039012 = "Setiap kali Aurorian menggunakan Skill Aktif, Casta memindahkan 3 ubin ke arah Aurorian. Ketika ada Aurorian dalam 1 cluster sekitar Casta, dia mengeluarkan skill untuk menyerang Aurorian.",
  str_monster_passiveskill_desc_29039013 = "Setiap kali Aurorian menggunakan Skill Aktif, Casta memindahkan 3 ubin ke arah Aurorian dan menerapkan 2 lapis perisai hitungan untuk dirinya sendiri. Ketika ada Aurorian dalam 1 cluster sekitar Casta, dia mengeluarkan skill untuk menyerang Aurorian.",
  str_monster_name_2903701 = "Meriam Self-Propelled",
  str_monster_name_2903701_en = "Self-Propelled Cannon",
  str_monster_desc_2903701 = "Penjaga yang kuat mampu berpatroli sendiri. Baik meriam utama dan bahu sangat kuat. Hanya satu penjaga seperti itu yang dapat menyebabkan kerusakan besar.",
  str_monster_ability_2903701 = "Itu dapat menggunakan menara untuk memberikan kerusakan terus-menerus pada musuh dan mengusir musuh yang datang terlalu dekat dengannya. Penjaga akan memperkuat dirinya sendiri ketika merasakan ancaman besar.",
  str_monster_ability_4000445 = "Meluncurkan serangan jarak dekat terhadap target, dan mengubah semua ubin di sepanjang jalur pergerakannya menjadi ubin elemennya sendiri, menghasilkan spikepest di sepanjang jalan.",
  str_monster_passiveskill_name_4000445 = "Api Murkmite",
  str_monster_passiveskill_desc_4000445 = "Menghasilkan spikepest di sepanjang jalur pergerakannya dan mengubah ubin yang dilewati menjadi ubin Merah.",
  str_monster_name_21500781 = "Robyn",
  str_monster_name_21500781_en = "Robyn",
  str_monster_desc_21500781 = "Anggota Spearows di Umbraton. Seorang introvert pemalu, dia tetap dekat dengan adiknya, Dayna, ketika mencoba untuk bertahan hidup di Umbraton.",
  str_monster_ability_21500781 = "Dayna menjadi lebih kuat saat dikalahkan.",
  str_monster_name_21400481 = "Dayna",
  str_monster_name_21400481_en = "Dayna",
  str_monster_desc_21400481 = "Sudah menjadi pemimpin Spearows meskipun usianya masih muda. Dia terkenal karena membangun tempat yang aman di lorong-lorong gelap dan kotor Umbraton dengan tekadnya yang tak tertandingi dan senjata licik yang kejam.",
  str_monster_ability_21400481 = "Mahir melancarkan serangan jarak jauh, menimbulkan damage pada satu area kolom.",
  str_monster_name_21400911 = "Chloe",
  str_monster_name_21400911_en = "Chloe",
  str_monster_desc_21400911 = "Musisi Lumopolis yang lembut dan ramah serta mudah tenggelam dalam kenangan sedihnya. Dia kehilangan keluarganya karena perang, sehingga dia hidup dalam kesedihan dan merasa sulit melepaskannya.",
  str_monster_ability_21400911 = "Meningkatkan ATK sekutu berdasarkan jumlah ubin Biru di lapangan.",
  str_monster_ability_21400912 = "Meningkatkan ATK sekutu berdasarkan jumlah ubin Biru di lapangan. Juga meningkatkan ACT.",
  str_monster_name_21200501 = "Korgon",
  str_monster_name_21200501_en = "Korgon",
  str_monster_desc_21200501 = "Ia adalah hiu yang menakutkan bahkan saat tersenyum! Ia adalah pelindung sebuah pemukiman kecil. Meskipun penampilannya ganas dan menakutkan, sebenarnya ia adalah pecinta kucing yang sangat lembut.",
  str_monster_ability_21200501 = "Memberikan serangan kuat yang dapat menyebabkan knockback saat mengenai target.",
  str_monster_name_21300491 = "Seleucid",
  str_monster_name_21300491_en = "Seleucid",
  str_monster_desc_21300491 = "Prajurit tinggi dan kuat yang sering berkelana ke seluruh Umbraton dengan armor lengkap dan pedang besar. Pria yang tak banyak bicara, dia tidak pernah melepas helmnya dan lebih suka menyelesaikan masalah dengan kekerasan.",
  str_monster_ability_21300491 = "Mengatur ulang ubin non-Biru dalam 1 cluster sekitarnya saat menangani kerusakan.",
  str_monster_ability_4900251 = "Menawarkan serangan area berbentuk silang dan memanggil klon untuk bertarung bersama. Saat mengkloning dirinya sendiri, ia menyerap HP mantan klon untuk memulihkan HP dan meningkatkan ATK-nya. Ketika klon hadir, bentuk asli Phantom juga dapat menghindari serangan, tetapi juga akan menerima kerusakan ketika klon terluka.",
  str_monster_ability_4910252 = "Pada saat kedatangan, ia menjadi gila dan memanggil klon untuk bertarung bersama. Jika Phantom menyerap clone, memulihkan HP dan sangat meningkatkan ATK.",
  str_monster_passiveskill_name_290370113 = "Mekanisme Reaksi",
  str_monster_passiveskill_desc_290370113 = "Memindahkan 1 ubin dan memanggil 1 T256 di depan",
  str_monster_name_4910181 = "Regina",
  str_monster_name_4910181_en = "Regina",
  str_monster_desc_4910181 = "Sifatnya yang berani, apa adanya, dan impulsif adalah tanda dari jiwa rock n 'roll sejati! Gaya musiknya yang keras membuatnya sangat populer di Rediesel Wrench. Dia tak hanya menginspirasi pasukan, tetapi juga memimpin mereka dalam serangan.",
  str_monster_ability_4910181 = "Mengejar musuh dan melancarkan serangan dengan aksi mengintimidasi.",
  str_monster_name_4903101 = "Barbara",
  str_monster_name_4903101_en = "Barbara",
  str_monster_desc_4903101 = "Penyanyi idola dari Rediesel Wrench. Barbara terlihat lembut dan baik di permukaan tetapi menunjukkan sikapnya yang mudah tersinggung saat bertemu dengan penggemar yang terlalu mengganggu. Dia melancong ke mana-mana untuk menjadi idola paling populer.",
  str_monster_ability_4903101 = "Melempar \"bom\" ke lapangan untuk menghambat musuh.",
  str_monster_ability_49031011 = "Memanggil item ke lapangan untuk menghambat musuh.",
  str_monster_name_4910301 = "Sinsa",
  str_monster_name_4910301_en = "Sinsa",
  str_monster_desc_4910301 = "Pemimpin Rediesel Wrench yang blak-blakan, sangat dekat dengan anggotanya dan sangat protektif terhadap adik perempuannya. Dia memastikan kelangsungan hidup gengnya.",
  str_monster_ability_4910301 = "Seorang penyerang kuat yang kekuatannya berubah setelah kekalahan Eve.",
  str_monster_name_4911051 = "Eve",
  str_monster_name_4911051_en = "Eve",
  str_monster_desc_4911051 = "Adik perempuan Sinsa yang dipengaruhi Eclipsite dan kehilangan kendali saat kecil. Dia telah mendapatkan kembali kepolosannya setelah disembuhkan.",
  str_monster_ability_4911051 = "Mampu melakukan serangan presisi dan damage area yang luas.",
  str_monster_ability_4900141 = "Unggul dalam serangan jarak dekat dan memiliki kemampuan untuk memanggil Eclipsites lainnya. Setelah berubah menjadi Rabid, serangan normalnya memberikan damage dua kali dengan jangkauan skill yang sangat ditingkatkan.",
  str_monster_ability_4900181 = "Unggul dalam serangan jarak jauh yang akan melumpuhkan target dan memanggil Eclipsites. Setelah berubah menjadi Rabid, serangan normalnya memberikan damage dua kali dengan jangkauan skill yang sangat ditingkatkan.",
  str_monster_passiveskill_name_21500781 = "ikatan saudara",
  str_monster_passiveskill_desc_21500781 = "Robyn menjadi lebih kuat ketika Dayna dikalahkan.",
  str_monster_ability_4900641 = "Unggul dalam menggunakan serangan area besar. Mengunci elemen ubin di sekitarnya setelah bergerak.",
  str_monster_ability_4900661 = "Shatterblast akan menghancurkan ubin di awal pertempuran. Serangan ini dapat menjatuhkan target.",
  str_monster_name_2903801 = "Astor",
  str_monster_name_2903801_en = "Astor",
  str_monster_desc_2903801 = "Roh wanita yang berkeliaran tanpa tuan atau keinginannya sendiri; selain dari penampilannya yang feminin, yang tersisa hanyalah permusuhan yang mengerikan terhadap yang hidup. Melalui ritual jahat, roh ini dapat digabungkan dengan Darkflow untuk menciptakan entitas supernatural yang kuat.",
  str_monster_ability_2903801 = "Mengamuk melalui area yang ditentukan dan menyerap energi Lilin Maut untuk memperkuat dirinya sendiri.",
  str_monster_ability_39038011 = "Mengamuk melalui area yang ditentukan, membangkitkan energi Lilin Kematian untuk memberikan kerusakan.",
  str_monster_passiveskill_name_2903801 = "keinginan cahaya lilin",
  str_monster_passiveskill_desc_2903801 = [[
Ketika tidak ada Aurorian dalam jangkauan serangan, Astor mulai menyalakan Lilin Kematian di dekatnya (jika semua Lilin Maut menyala, Astor memulihkan 20% dari HP maksimalnya).
Selain itu, setiap Deathly Candle yang menyala memberikan pengurangan damage 10% kepada Astor.]],
  str_monster_passiveskill_name_39038011 = "keinginan cahaya lilin",
  str_monster_passiveskill_desc_39038011 = [[
Saat tidak ada Aurorian yang berada dalam jangkauan serangan, Astor mulai menyalakan Lilin Kematian di medan perang.
Jika semua Lilin Kematian dinyalakan, Astor memberikan kerusakan parah pada Aurorian.]],
  str_monster_passiveskill_name_39038012 = "keinginan cahaya lilin",
  str_monster_passiveskill_desc_39038012 = [[
Saat tidak ada Aurorian yang berada dalam jangkauan serangan, Astor mulai menyalakan Lilin Kematian di medan perang.
Jika semua Lilin Kematian dinyalakan, Astor memberikan kerusakan parah pada Aurorian.
Jika tidak semua Lilin Kematian menyala, Astor memberikan sedikit kerusakan pada Aurorian.]],
  str_monster_passiveskill_name_2903802 = "keinginan cahaya lilin",
  str_monster_passiveskill_desc_2903802 = [[
Ketika tidak ada Aurorian dalam jangkauan serangan, Astor mulai menyalakan Lilin Kematian di dekatnya (jika semua Lilin Maut menyala, Astor memulihkan 20% dari HP maksimalnya).
Selain itu, setiap Deathly Candle yang menyala meningkatkan pengurangan damage Astor, dan setiap Deathly Candle yang padam meningkatkan ATK Astor.]],
  str_monster_name_2903600 = "Bunga Diavola",
  str_monster_name_2903601 = "Diavola",
  str_monster_name_2903601_en = "Diavola",
  str_monster_desc_2903601 = "Diavola suka bersembunyi dan menghabisi musuhnya secara diam-diam dengan racun.",
  str_monster_ability_2903601 = "Diavola tidak bisa bergerak. Ia memiliki daya tahan yang kuat, tubuhnya terbungkus duri beracun. Bunganya dapat menarik Dawn Sprite, tetapi juga memperlihatkan kelemahannya.",
  str_monster_desc_2000609 = "Ilusi yang diciptakan oleh Diavola yang mengandung kekuatan magis.",
  str_monster_ability_2000609 = "Menempelkan dirinya ke Diavola dan meningkatkan ATK-nya saat berada dalam 1 klaster Diavola di sekitarnya.",
  str_monster_passiveskill_name_2903600 = "Penghindaran Kerusakan",
  str_monster_passiveskill_desc_2903600 = "Bunga Diavola hanya bisa dirusak oleh skill Sniper dan kebal terhadap serangan normal dan damage area. Ketika bunganya memiliki sisa HP nol, Diavola lumpuh dan tidak lagi menimbulkan Toksin pada Aurorian.",
  str_monster_passiveskill_name_2903601 = "Korosi",
  str_monster_passiveskill_desc_2903601 = "Saat terbangun, Diavola menyerang balik setiap serangan normal, menimbulkan 1 tumpukan Toxin pada Aurorian.",
  str_monster_passiveskill_name_2000609 = "Heal",
  str_monster_passiveskill_desc_2000609 = "Ketika Dawn Sprite dikalahkan, itu memulihkan sejumlah kecil HP tim dan mengurangi jumlah tumpukan Toxin tim.",
  str_monster_passiveskill_desc_2000639 = "Mengembalikan sedikit HP ke Dawn Sprite setelah dikalahkan oleh Aurorian.",
  str_monster_name_2001901 = "Roh Lentera",
  str_monster_name_2001901_en = "Lantern Spirit",
  str_monster_desc_2001901 = "Eclipsite yang dimodifikasi oleh Asmodeus. Keinginannya dikendalikan oleh Asmodeus, jadi dia mematuhi setiap perintahnya.",
  str_monster_ability_2001901 = "Serangan membuat rantai yang menyebabkan kerusakan yang diterima dan pemulihan HP di antara pihak terkait untuk dibagikan.",
  str_monster_passiveskill_name_2001901 = "Rantai",
  str_monster_passiveskill_desc_2001901 = "Ketika salah satu pihak yang terhubung oleh rantai menerima kerusakan atau memulihkan HP, pihak lain akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama. Ketika rantai terhubung ke Aurorian, itu akan putus setelah melebihi panjang tertentu.",
  str_monster_passiveskill_name_2001902 = "Teleportasi",
  str_monster_passiveskill_desc_2001902 = "Lantern Spirit dapat berteleportasi jika dapat melewati petak tempat Aurorian berada dan berpindah ke petak di sisi lain.",
  str_monster_name_2903401 = "Asmodeus",
  str_monster_name_2903401_en = "Asmodeus",
  str_monster_desc_2903401 = "Wraith yang kuat memiliki kemampuan yang mengerikan untuk melihat semua keinginan lawannya dan senang memanipulasi mereka.",
  str_monster_ability_2903401 = "Ketika Asmodeus yang kebal terhadap serangan normal dan Asmodeus yang kebal terhadap kerusakan keterampilan keduanya berada di lapangan, HP mereka dibagi melalui Rantai Keinginan, dan dia juga dapat menyiksa mangsanya dengan Rantai Mimpi Buruknya.",
  str_monster_passiveskill_name_29034001 = "Asmodeus: Rantai Keinginan",
  str_monster_passiveskill_desc_29034001 = "Ketika salah satu Asmodeus yang terhubung dengan Chain of Desire mengalami kerusakan atau memulihkan HP, Asmodeus lainnya akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama. Setelah Asmodeus mengambil tindakan, Wilayah Gelap akan dihasilkan di bawah Rantai Keinginan.",
  str_monster_passiveskill_name_29034002 = "Asmodeus: Matikan",
  str_monster_passiveskill_desc_29034002 = "Sebelum Asmodeus mengambil tindakan, kedua tubuhnya mungkin berganti posisi untuk memudahkannya memburu target.",
  str_monster_passiveskill_name_2903401 = "Asmodeus: Rantai Mimpi Buruk",
  str_monster_passiveskill_desc_2903401 = "Aurorian yang terhubung dengan Chain of Nightmares akan menerima damage untuk setiap petak yang mereka lalui. Meninggalkan jangkauan efektif Chain of Nightmares akan menghancurkannya.",
  str_monster_passiveskill_name_2903411 = "Asmodeus: Pemutusan Jiwa",
  str_monster_passiveskill_desc_2903411 = "Saat hubungan antara Aurorian dan Chain of Nightmares terputus, Aurorian menerima damage tinggi.",
  str_monster_name_2903501 = "Cerritus",
  str_monster_name_2903501_en = "Cerritus",
  str_monster_desc_2903501 = "Eclipsite baru yang ditemui selama eksplorasi tampaknya merupakan varian dari Eclipsite yang kuat, kecuali itu lebih gila dan jauh lebih merusak.",
  str_monster_ability_2903501 = "Cerritus menyerang Aurorian dengan menabrak mereka dan memiliki kemampuan yang kuat untuk memanggil Kerikil dan mengubah medan. Cerritus tumbuh lebih kuat saat pertempuran berlangsung. Serangan yang tidak membunuh Cerritus hanya membuatnya lebih kuat! Setiap beberapa putaran, Cerritus mengaum dengan marah dan memasuki keadaan gila.",
  str_monster_passiveskill_name_29034011 = "Cerritus: Lolongan Marah",
  str_monster_passiveskill_desc_29034011 = "Setiap 2 putaran, Cerritus melolong marah dan menyembuhkan, mendapatkan ATK dan gerakan tetapi kehilangan DEF. Pada saat yang sama, ia memanggil Kerikil di seluruh lapangan.",
  str_monster_passiveskill_name_29034012 = "Cerritus: Lolongan Marah",
  str_monster_passiveskill_desc_29034012 = "Setiap 2 putaran, Cerritus melolong marah dan menyembuhkan, mendapatkan ATK dan gerakan tetapi kehilangan DEF. Pada saat yang sama, ia memanggil Kerikil di seluruh lapangan.",
  str_monster_passiveskill_name_2903501 = "Cerritus: Lolongan Marah",
  str_monster_passiveskill_desc_2903501 = "Setiap 2 putaran, Cerritus melolong marah dan menyembuhkan, mendapatkan ATK dan gerakan tetapi kehilangan DEF. Pada saat yang sama, ia memanggil Kerikil di seluruh lapangan.",
  str_monster_passiveskill_desc_2903504 = "Setiap 2 putaran, Cerritus melolong marah dan menyembuhkan, mendapatkan ATK dan gerakan. Pada saat yang sama, ia memanggil Kerikil di seluruh lapangan.",
  str_monster_ability_9200164 = "Menggunakan tombak untuk menyerang target dan dapat memperkuat Eclipsites lainnya.",
  str_monster_name_21600381 = "Phantom",
  str_monster_name_2902902 = "Jormungand",
  str_monster_name_2902902_en = "Jormungand",
  str_monster_desc_2902902 = "Sebuah Eclipsite lahir dalam kondisi ekstrim di akhir zaman. Ia memiliki sosok yang terdistorsi dan telah lama kehilangan kemampuan untuk berpikir secara cerdas. Yang tersisa hanyalah keinginan untuk terus bergerak maju dan melahap segala sesuatu di jalannya.",
  str_monster_ability_2902902 = "Struktur tubuh Jormungand memungkinkannya mereplikasi dirinya sendiri kapan saja. Itu melahap segala rintangan di jalannya, bahkan tubuhnya sendiri.",
  str_monster_passiveskill_name_2902902 = "Jormungand: Tak pernah puas",
  str_monster_passiveskill_desc_2902902 = "Jormungand menyerang lagi setiap kali seorang Aurorian menggunakan Skill Aktif.",
  str_monster_passiveskill_name_2902901 = "Jormungand: Replikasi",
  str_monster_passiveskill_desc_2902901 = "Di awal putaran monster, Jormungand menggandakan diri, bertambah panjang dengan 1 segmen baru.",
  str_monster_passiveskill_name_2900251 = "Menghindar",
  str_monster_passiveskill_desc_2900251 = "Bergerak dengan sangat gesit dan memiliki kesempatan untuk menghindari serangan. (Tidak bisa mengelak saat Lumpuh.)",
  str_monster_name_2002001 = "Venomex",
  str_monster_desc_2002001 = "Dikatakan sebagai kerabat jauh dari spesies Eclipsite yang mampu meledakkan diri, kecuali varietas ini dapat meluncurkan bola lendir berbisa, memberikan kerusakan signifikan pada organisme hidup.",
  str_monster_ability_2002001 = "Menyemprotkan racun dalam garis lurus atau ke lokasi Aurorian, menimbulkan Racun pada musuh dan sekutunya dalam jangkauan racun.",
  str_monster_ability_2904201 = "Memiliki kemampuan untuk menyerang Aurorian dari jarak jauh dan dapat melancarkan serangan layar penuh. Bisa memanggil hantu yang tidak bisa menyerang tapi mengelilingi Aurorian.",
  str_monster_passiveskill_name_2904201 = "Deception",
  str_monster_passiveskill_desc_2904201 = "Saat ketidakterkalahkan berakhir, 2 Phantasm Dreamwalker dipanggil untuk mengelilingi Aurorian. Phantasm tidak bisa menyerang dan tidak bisa diserang.",
  str_monster_passiveskill_desc_2904203 = "Saat ketidakterkalahkan berakhir, 2 Phantasm Dreamwalker dipanggil untuk mengelilingi Aurorian. Phantasm tidak bisa diserang.",
  str_monster_name_2904001 = "Bennuguardian",
  str_monster_name_2904001_en = "Bennuguardian",
  str_monster_desc_2904001 = "Seorang wali kuno yang berada di kedalaman Wilayah Rahasia, terbangun karena seringnya gangguan dari penyusup. Bahkan Eclipsites takut dengan kemampuannya yang kuat. Berkeliaran di sekitar medan perang tanpa tujuan.",
  str_monster_ability_2904001 = "Memiliki kekuatan besar. Mengumpulkan Fury saat diserang. Ketika Fury mencapai level tertentu, memasuki kondisi Marah, mengurangi kerusakan yang diterima dan memberikan keterampilan tambahan yang kuat. Jika Bennuguardian tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh.",
  str_monster_name_2904202 = "Dreamwalker Phantasm",
  str_monster_passiveskill_name_29040011 = "Kelahiran Kembali Bennu",
  str_monster_passiveskill_desc_29040011 = "Jika Bennuguardian tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh. Tumpukan Fury-nya dibersihkan pada saat bersamaan.",
  str_monster_passiveskill_name_29040012 = "Bennu Marah",
  str_monster_passiveskill_desc_29040012 = "Bennuguardian mengumpulkan Fury saat diserang. Ketika Fury mencapai 50 tumpukan, ia memasuki kondisi Marah, mengurangi kerusakan yang diterima dan memberikan keterampilan serangan tambahan yang kuat setelah mengambil tindakan di setiap putaran. Setelah casting skill ini, status Enraged Bennuguardian memudar.",
  str_monster_name_2002101 = "Menipu",
  str_monster_name_2002101_en = "Cozen",
  str_monster_desc_2002101 = "Memiliki kemampuan luar biasa untuk berbaur dengan lingkungannya. Terkadang, bahkan terlihat seperti jebakan biasa. Namun, begitu ia mengungkapkan dirinya, ia meledak dalam amukan yang mematikan.",
  str_monster_ability_2002101 = "Biasanya bersembunyi di Crud. Saat hitungan mundur selesai, ia muncul dan menyerang Aurorian.",
  str_monster_passiveskill_name_2002101 = "Mentah",
  str_monster_passiveskill_desc_2002101 = "Saat hitungan mundur Crud berakhir, Cozen muncul dan menyerang Aurorian.",
  str_monster_name_2904301 = "Regal",
  str_monster_name_2904401 = "Requiem",
  str_monster_name_2904501 = "Frostfire",
  str_monster_name_2904601 = "Mythos",
  str_monster_name_2904301_en = "Regal",
  str_monster_name_2904401_en = "Requiem",
  str_monster_name_2904501_en = "Frostfire",
  str_monster_name_2904601_en = "Mythos",
  str_monster_passiveskill_name_2904301 = "Embun beku Regal",
  str_monster_passiveskill_desc_2904301 = "Memiliki kemampuan serangan balik. Mendapatkan 1 stack Vis setiap kali Aurorian mengeluarkan Skill Aktif. Saat Vis mencapai 10 tumpukan, mendapatkan efek peningkatan ATK yang dapat ditumpuk di awal putaran monster. Berlangsung hingga akhir pertempuran.",
  str_monster_passiveskill_name_2904401 = "Pemecah Tabu Requiem",
  str_monster_passiveskill_desc_2904401 = "Memiliki kemampuan serangan balik. Memperoleh 1 stack Vis setiap kali Aurorian mengeluarkan Skill Aktif. Saat Vis mencapai 10 tumpukan, meluncurkan serangan layar penuh di awal putaran monster, memberikan kerusakan pada semua target.",
  str_monster_passiveskill_name_2904501 = "Frost Fire: Kecelakaan",
  str_monster_passiveskill_desc_2904501 = "Memiliki kemampuan serangan balik. Memperoleh 1 stack Vis setiap kali Aurorian mengeluarkan Skill Aktif. Saat Vis mencapai 10 tumpukan, menandai area lapangan, dan di awal putaran monster, melepaskan kerusakan parah di area yang ditandai.",
  str_monster_passiveskill_name_2904601 = "Sajak Pembibitan: Perburuan",
  str_monster_passiveskill_desc_2904601 = "Memiliki kemampuan serangan balik. Mendapatkan 1 stack Vis setiap kali Aurorian mengeluarkan Skill Aktif. Saat Vis mencapai 10 tumpukan, menandai area lapangan, dan di awal putaran monster, melepaskan kerusakan parah di area yang ditandai.",
  str_monster_name_2904101 = "Yoh",
  str_monster_name_2904101_en = "Yoh",
  str_monster_desc_2904101 = "Pernah menjadi pemimpin ikan ular, dia diperbudak oleh Aurorian untuk dijadikan alat navigasi. Kebencian yang meningkat selama bertahun-tahun telah mengubahnya menjadi musuh yang kuat.",
  str_monster_ability_2904101 = "Memiliki kemampuan sihir yang kuat dan dapat mengontrol proyektil untuk memberikan kerusakan pada musuh.",
  str_monster_name_2002202 = "Kata",
  str_monster_desc_2002202 = "Yoh memproyeksikan Kata-kata dalam pikirannya menjadi kenyataan untuk menyerang musuh-musuhnya.",
  str_monster_ability_2002202 = "Saat ilusi tidak aktif, Yoh mengontrol \"Kata-kata\", melemparkannya seperti proyektil untuk langsung mengenai Aurorian. (Aurorian dapat menghancurkan proyektil selama periode ini untuk menghindari kerusakan.)",
  str_monster_desc_49031011 = "Pegawai teknisi Rediesel Wrench yang sangat percaya diri dengan teknologi komunikasinya. Dia suka mengeluh dan meneriaki orang lain di Comm Channel, tapi dia kebingungan saat ada masalah.",
  str_monster_ability_4903103 = "Selalu bergerak ke lokasi terjauh dari target. Skill memberikan damage area yang besar. Keahlian yang dapat dikenakan biaya memberikan kerusakan layar penuh dan menjatuhkan target kembali.",
  str_monster_ability_4900232 = "Vani bisa menggunakan Energi untuk menyerang dari jarak jauh.",
  str_monster_passiveskill_name_48004341 = "Membangkitkan",
  str_monster_passiveskill_desc_48004341 = "Mara Sol memulihkan 50% HP saat hampir mati, dan kemudian memperoleh kemampuan untuk melakukan serangan balik, tetapi juga menerima peningkatan kerusakan. Skill pasif ini hanya bisa dipicu satu kali.",
  str_monster_passiveskill_name_48004342 = "Chasm",
  str_monster_passiveskill_desc_48004342 = "Berlaku setelah Mara Sol hidup kembali. Setiap kali seorang Aurorian menggunakan Skill Aktif, Mara Sol memanggil Chasm ke lapangan.",
  str_monster_ability_4000124 = "Eclipsite dengan kemampuan pemanggilan level rendah. Tidak bisa bergerak sendiri dan bertarung dengan memanggil Chasms.",
  str_monster_name_2002301 = "Asisten Aphonic",
  str_monster_desc_2002301 = "Kemungkinan jenis \"mentor\" Eclipsite tertentu, mengingat bagaimana mereka berdua menyembuhkan Eclipsites lainnya. Perbedaannya adalah bahwa Eclipsite ini lebih mungkin untuk tetap dekat dengan sekutunya yang lebih besar untuk memanfaatkan efek khusus keahliannya.",
  str_monster_ability_2002301 = "Aphonic Assistant bergerak menuju arah dengan jumlah Eclipsites terbanyak. Dapat memulihkan HP Eclipsites lainnya. Semakin banyak petak yang ditempati Eclipsite lain dalam jangkauan skill Aphonic Assistant, semakin kuat efek penyembuhannya.",
  str_monster_name_2904801 = "Cacing Pasir Merah Muda",
  str_monster_name_2904801_en = "Pink Sandworm",
  str_monster_desc_2904804 = "Cacing pasir langka asli Gurun Rediesel. Itu ditutupi sisik merah muda karena mutasi yang unik, membuatnya lebih kuat dan lebih ganas daripada cacing pasir lainnya. Karena penampilannya yang langka dan istimewa, prevaricator tertentu mengklaim bahwa sisiknya adalah harta langka yang dapat dibuat menjadi ramuan ajaib yang dapat mewujudkan semua keinginan seseorang, tetapi sebenarnya itu hanyalah sisik merah muda biasa tanpa fungsi khusus. .",
  str_monster_ability_2904801 = "Mengebor ke tanah untuk menemukan lokasi targetnya, lalu meledak ke tempat terbuka. Unggul dalam menyemburkan pasir hitam untuk menyerang target di depannya.",
  str_monster_name_2904701 = "Pemburu Mekanik",
  str_monster_name_2904701_en = "Mechanical Huntsman",
  str_monster_desc_2904701 = "Seorang wali kuno diciptakan untuk satu-satunya tujuan melindungi rahasia tanah ini. Serangannya sulit untuk dihindari, dan ia juga memiliki pemulihan diri yang luar biasa agar tetap berfungsi selama berabad-abad. Tidak ada yang mau menghadapinya sendirian.",
  str_monster_ability_2904701 = "Membuat zona yang dijaga dalam 2 kelompok sekitarnya setiap putaran. Aurorian di dalam zona yang dijaga akan menerima kerusakan tambahan setiap kali mereka menyerang atau bergerak. Jika Pemburu Mekanik tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh.",
  str_monster_name_2904901 = "Empat Ksatria",
  str_monster_name_2904901_en = "Empat Ksatria",
  str_monster_desc_2904901 = "Meski terlihat seperti anggota juri biasa, tutup kepala plester di kepala mereka membuat mereka terlihat sangat mencurigakan. Ternyata Eclipsites bersembunyi di bawah mereka! Hal yang membingungkan adalah mereka sepertinya mengikuti instruksi seseorang...",
  str_monster_ability_2904901 = "Empat Ksatria memiliki serangan yang kuat dan kemampuan teleportasi yang luar biasa. Setiap kali salah satu dari Empat Ksatria diserang atau memulihkan HP, ksatria lainnya akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama.",
  str_monster_passiveskill_name_2904901 = "Empat Ksatria: Kebersamaan",
  str_monster_passiveskill_desc_2904901 = "Setiap kali salah satu dari Empat Ksatria diserang atau memulihkan HP, ksatria lainnya akan menerima jumlah kerusakan yang sama atau memulihkan jumlah HP yang sama.",
  str_monster_name_2905501 = "Setan Hati",
  str_monster_name_2905501_en = "Setan Hati",
  str_monster_desc_2905501 = "Kenangan masa lalu membanjiri hatinya, menciptakan Demon Hound yang menakutkan saat kebencian menguasai dirinya.",
  str_monster_ability_2905501 = "Ketika Demon Hati berada di ambang kematian, dia dapat mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh. Dia juga akan melemparkan keterampilan yang kuat dan meningkatkan dirinya sendiri. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang dan melawan Skill Aktif.",
  str_monster_ability_2905502 = "Demon Hati mengkonsumsi sebagian dari HP-nya untuk menyerang dan memulihkan sebagian dari HP-nya yang hilang jika ada Aurorian yang terkena. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang!",
  str_monster_ability_2905503 = "Ketika Demon Hati berada di ambang kematian, dia dapat mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh. Dia juga akan melemparkan keterampilan yang kuat dan meningkatkan dirinya sendiri. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang!",
  str_monster_ability_2905504 = "Ketika Demon Hati berada di ambang kematian, dia dapat mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh. Dia juga akan melemparkan keterampilan yang kuat dan meningkatkan dirinya sendiri. Demon Hati memberikan lebih banyak damage saat HP-nya berkurang dan melawan Skill Aktif.",
  str_monster_passiveskill_name_2905501 = "Setan Hati: Pemulihan",
  str_monster_passiveskill_desc_2905501 = "Ketika Demon Hati berada di HP rendah, dia mengkonsumsi energi regeneratif untuk memulihkan dirinya ke HP penuh.",
  str_monster_passiveskill_name_2905502 = "Setan Hati: Api Nether",
  str_monster_passiveskill_desc_2905502 = "Setiap kali Demon Hati mengkonsumsi energi regeneratif, dia menjadi Demon Hati: Ominous Flame ronde ini, berteleportasi ke samping Aurorian dan mengkonsumsi 15% dari HP-nya saat ini untuk memberikan kerusakan besar pada Aurorian. Jika dia mencapai target, memulihkan 15% dari HPnya yang hilang.",
  str_monster_passiveskill_name_2905503 = "Setan Hati: Rezeki",
  str_monster_passiveskill_desc_2905503 = "Demon Hati memulihkan sebagian dari HPnya yang hilang saat memberikan kerusakan pada Aurorian.",
  str_monster_passiveskill_name_2905504 = "Setan Hati: Liar",
  str_monster_passiveskill_desc_2905504 = "Semakin rendah HP Demon Hati, semakin besar kerusakan yang ditimbulkan oleh skill tersebut.",
  str_monster_passiveskill_name_2905505 = "Setan Hati: Membalas",
  str_monster_passiveskill_desc_2905505 = "Setiap kali seorang Aurorian menggunakan Skill Aktif, Demon Hati akan berteleportasi ke Aurorian sedekat mungkin dalam 1 klaster di sekitarnya, lalu menyerang target dalam 1 klaster di sekitarnya.",
  str_monster_passiveskill_name_2905506 = "Setan Hati: Membalas",
  str_monster_passiveskill_desc_2905506 = "Setiap kali seorang Aurorian menggunakan Skill Aktif, Demon Hati berteleportasi ke Aurorian sedekat mungkin dalam 2 klaster di sekitarnya, lalu menyerang target dalam 1 klaster di sekitarnya.",
  str_monster_name_2905101 = "Pembor",
  str_monster_name_2905101_en = "Driller",
  str_monster_desc_2905101 = "Robot tempur yang dikembangkan oleh Illumina. Itu telah bekerja sangat baik dalam pengujian internal tetapi belum diuji dalam pertempuran yang sebenarnya.",
  str_monster_ability_2905101 = "Pengebor memiliki 2 status. Itu bergerak di sekitar lapangan dalam keadaan normal dan menggali sejumlah Bidang Energi dan Bidang Pendukung setiap putaran. Ketika ada sejumlah Medan Energi di lapangan, itu menyerap dan merakit Anjungan Pengebor.",
  str_monster_name_2905102 = "Platform Pengebor",
  str_monster_name_2905102_en = "Driller Platform",
  str_monster_name_2905001 = "Ratu laba-laba",
  str_monster_name_2905001_en = "Spider Queen",
  str_monster_desc_2905001 = "Eclipsite khusus ini menyerupai laba-laba dan telah mempelajari perilaku kelompok laba-laba selama jalur evolusinya. Itu bersembunyi di kegelapan di mana sinar matahari tidak bisa mencapai.",
  str_monster_ability_2905001 = "Memiliki kemampuan reproduksi yang kuat, ia menjalin jaring laba-laba ke dalam lingkungan berburu.",
  str_monster_name_2002401 = "Penetasan laba-laba",
  str_monster_desc_2002401 = "Keturunan Ratu Laba-laba yang memiliki kesadaran diri yang lemah dan mengikuti setiap perintahnya.",
  str_monster_ability_2002401 = "Atas perintah Ratu Laba-laba, Tukik Laba-laba berkumpul dan menyerang mangsanya sebagai satu kelompok.",
  str_monster_passiveskill_name_2002401 = "Perayapan Web",
  str_monster_passiveskill_desc_2002401 = "Spider Hatchling hanya merayap di sepanjang jaring dan akan membuat jalurnya sendiri saat tidak ada tempat untuk dituju.",
  str_monster_name_2905201 = "Figerald",
  str_monster_name_2905201_en = "Figerald",
  str_monster_desc_2905201 = "Sebagai salah satu Wraith terkuat, dia menyerang dengan seluruh kekuatannya saat statusnya terancam.",
  str_monster_ability_2905201 = "Memiliki kekuatan untuk menghancurkan lingkungan dan selalu menjaga jarak tertentu dari Aurorian.",
  str_monster_name_2002501 = "Prajurit Illumina",
  str_monster_desc_2002501 = "Prajurit tempur biasa di Tentara Illumina, dikenal karena keterampilan mereka dengan senapan dan pisau tempur, serta keuletan, etos kerja, proaktif dalam pertempuran, dan semangat juang yang tak kenal takut.",
  str_monster_ability_2002501 = "Menggunakan lebih banyak serangan jarak jauh. Ketika pertempuran sengit, mendekati musuh dan terlibat dalam pertempuran jarak dekat untuk menghabisi mereka secepat mungkin.",
  str_monster_ability_2002502 = "Pejuang jarak dekat yang terampil dengan kemampuan untuk mendeteksi dan bereaksi terhadap gerakan musuh selama pertempuran sengit, memungkinkan serangan balik yang efektif.",
  str_monster_passiveskill_name_200250103 = "Kegigihan Pertempuran",
  str_monster_passiveskill_desc_200250103 = "Ketika HP lebih rendah dari 50%, semua serangan senjata akan menjadi serangan jarak dekat dengan pisau tempur. Pada saat yang sama, semua Bruise yang terkumpul akan berubah menjadi HP yang dipulihkan dan meningkatkan ATK dan DEF.",
  str_monster_passiveskill_name_200250113 = "Serangan Balik yang Tajam",
  str_monster_passiveskill_desc_200250113 = "Setiap kali musuh menggunakan Skill Aktif, Tentara Illumina melanjutkan dengan 1 petak dan menyerang.",
  str_monster_name_2905301 = "Uji Negara Helios",
  str_monster_name_2905301_en = "Uji Negara Helios",
  str_monster_desc_2905301 = "Setelah hidup sendirian selama lebih dari satu dekade di Dark Zone, prajurit Illumina ini telah melupakan segalanya kecuali pertempuran. Hal yang menakutkan adalah dia menjadi lebih kuat dalam pertempuran setelah dimodifikasi oleh seseorang ...",
  str_monster_ability_2905301 = "Entitas yang memiliki kemampuan tempur yang kuat dan mengumpulkan Memar saat menerima kerusakan. Saat serangannya meleset dari targetnya, Tanda Teror dilepaskan di lapangan. Keterampilan Helios menjadi lebih kuat dengan setiap Tanda Teror di lapangan.",
  str_monster_passiveskill_name_29053011 = "Relentless",
  str_monster_passiveskill_desc_29053011 = "Saat menerima damage, Helios mengakumulasikan Memar setara dengan 50% dari damage yang diterima.",
  str_monster_passiveskill_name_29053012 = "Tanda Teror",
  str_monster_passiveskill_desc_29053012 = "Saat Helios' Dread Rush atau Leap of Terror meleset dari targetnya, Tanda Teror dilepaskan di lapangan: dia memberikan kerusakan pada target secara langsung dan menghasilkan tanda pada petak tempat target berada.",
  str_monster_passiveskill_name_2904701 = "Menghidupkan kembali: Penghitung",
  str_monster_passiveskill_desc_2904701 = "Jika Pemburu Mekanik tidak terkalahkan saat mengambil tindakan, ia akan menghabiskan energi regeneratifnya untuk memulihkan dirinya ke HP penuh. Di babak selanjutnya setelah pulih, Mechanical Huntsman akan menggunakan skill yang sangat berbahaya yang mengurangi HP Aurorian di dalam zona yang dijaga menjadi 1.",
  str_monster_passiveskill_name_2905102 = "Pembongkaran Anjungan Pengebor",
  str_monster_passiveskill_desc_2905102 = "Pengebor dan Anjungan Pengebor memiliki HP independen. Dalam Mode Platform Pengebor, pemain dapat menyerang Pengebor yang bersembunyi di balik platform. Jika Anjungan Pengebor menjadi tak terkalahkan, Anjungan Pengeboran akan secara otomatis dibongkar untuk mengungkap Pengebor.",
  str_monster_passiveskill_name_2905101 = "Kontrol Pengebor",
  str_monster_passiveskill_desc_2905101 = "Saat Pengebor mengambil tindakan, jika ada 6 Medan Energi di lapangan, ia memanggil Platform Pengebor, yang menempati 5 petak tempatnya berdiri.",
  str_monster_name_2905401 = "Joshua: Jiwa yang Tercemar",
  str_monster_name_2905401_en = "Joshua: Tainted Soul",
  str_monster_desc_2905401 = "Invasi materi jahat membawa penderitaan dan kesedihan tanpa henti... Keberadaannya, yang tidak pernah dimaksudkan untuk dunia ini, dihasilkan olehnya...",
  str_monster_ability_2905401 = "Dia memiliki kendali yang sangat besar atas lingkungannya dan sebagian kebal terhadap serangan normal dan keterampilan Aurorian.",
  str_monster_name_2003201 = "Pantomim Kartima",
  str_monster_name_2003201_en = "Mime Kartima",
  str_monster_desc_2003201 = "\"Saya akan menjaga kehormatan Kartima.\"",
  str_monster_ability_2003201 = "Sambil memegang perisai untuk pertahanan, Mime Kartima akan dengan mahir beralih antara cambuk dan perisai untuk menyerang target sesuai dengan posisinya.",
  str_monster_name_2003202 = "Penjaga Palu Lumopolis",
  str_monster_name_2003202_en = "Lumopolis Hammerguard",
  str_monster_desc_2003202 = "Revisi: Penjaga elit Lumopolis, perisai dan baju zirah mereka yang tak tertembus berdiri sebagai benteng, sementara palu yang menggelegar bergema seperti longsoran salju yang dahsyat.",
  str_monster_ability_2003202 = "Sambil memegang perisai untuk pertahanan, Mime Kartima akan dengan mahir beralih antara cambuk dan perisai untuk menyerang target sesuai dengan posisinya.",
  str_monster_passiveskill_name_200320105 = "Kartima: Penjaga perisai",
  str_monster_passiveskill_desc_200320105 = "Kartima mengacungkan tamengnya, mengurangi damage dari serangan frontal. Kehilangan efek saat tertegun, ketakutan, lumpuh, atau terkena efek kontrol lainnya.",
  str_monster_passiveskill_name_200320106 = "Kartima: pantang menyerah",
  str_monster_passiveskill_desc_200320106 = "Kartima kebal terhadap Stun, Frighten, Paralysis, dan Control effect lainnya selama 2 ronde setelah bergabung dalam pertempuran",
  str_monster_passiveskill_desc_200320107 = "Kartima kebal terhadap Stun, Frighten, Paralysis, dan Control effect lainnya selama 1 ronde setelah bergabung dalam pertempuran",
  str_monster_passiveskill_desc_200320108 = "Kartima kebal terhadap Stun, Frighten, Paralysis, dan Control effect lainnya selama 3 ronde setelah bergabung dalam pertempuran",
  str_monster_passiveskill_desc_200320109 = "Kartima kebal terhadap Stun, Frighten, Paralysis, dan control effect lainnya selama 5 ronde setelah bergabung dalam pertempuran",
  str_monster_passiveskill_name_200320205 = "Penjaga perisai",
  str_monster_passiveskill_desc_200320205 = "Lumopolis Hammerguard mengacungkan perisainya, mengurangi kerusakan dari serangan frontal. Kehilangan efek saat tertegun, ketakutan, lumpuh, atau terkena efek kontrol lainnya.",
  str_monster_passiveskill_name_200320206 = "Unyielding",
  str_monster_passiveskill_desc_200320206 = "Kebal terhadap Pingsan, Ketakutan, Kelumpuhan, dan efek Kontrol lainnya selama 2 putaran setelah bergabung dalam pertempuran",
  str_monster_passiveskill_desc_200320207 = "Kebal terhadap Pingsan, Ketakutan, Kelumpuhan, dan efek Kontrol lainnya selama 1 putaran setelah bergabung dalam pertempuran",
  str_monster_passiveskill_desc_200320208 = "Kebal terhadap Pingsan, Ketakutan, Kelumpuhan, dan efek Kontrol lainnya selama 3 putaran setelah bergabung dalam pertempuran",
  str_monster_passiveskill_name_39002111 = "Call of Stone",
  str_monster_passiveskill_desc_39002111 = "Umbrahulk memanggil Pebble secara acak ke medan pertempuran di akhir setiap putaran",
  str_monster_passiveskill_name_3900452 = "Kekuatan yang Ditinggalkan",
  str_monster_passiveskill_desc_3900452 = [[
Saat Forsaken monster menerima damage, efek counter elemen meningkat sebesar 100%.
Monster yang ditinggalkan akan terus meningkatkan diri sesuai dengan kerusakan yang mereka terima.]],
  str_monster_passiveskill_name_3900453 = "Kekuatan yang Ditinggalkan",
  str_monster_passiveskill_desc_3900453 = "Monster yang ditinggalkan akan terus meningkatkan diri sesuai dengan kerusakan yang mereka terima.",
  str_monster_name_2904804 = "Terlupakan: Cacing Pasir Merah Muda",
  str_monster_name_2904804_en = "Forsaken: Pink Sandworm",
  str_monster_name_4904901 = "Terlupakan: Empat Ksatria",
  str_monster_name_4904901_en = "Forsaken: The Four Knights",
  str_monster_name_39038011 = "Terlupakan: Astor",
  str_monster_name_39038011_en = "Forsaken: Astor",
  str_monster_name_3100311 = "Ditinggalkan: Augean",
  str_monster_name_3100311_en = "Forsaken: Augean",
  str_monster_desc_3900311 = "Forsaken: Augean menjadi kebal terhadap semua serangan Aurorian dan memanggil klon untuk melibatkan pemain. Kerusakan yang ditimbulkan pada klon ditransfer ke tubuh utama.",
  str_monster_ability_3100311 = "Menghidupkan kembali klon setiap putaran. Klon dapat menyerang target berkali-kali dan menimbulkan Pendarahan. Penghitung Gerakan: Setiap kali Aurorian menggunakan Skill Aktif di babak ini, jangkauan gerakan klon akan meningkat.",
  str_monster_name_3100312 = "Klon yang Ditinggalkan",
  str_monster_desc_3900312 = [[
1. Semua kerusakan yang diterima akan ditransfer sepenuhnya ke tubuh utama. Tidak bisa kebal terhadap kerusakan berbasis persentase.
2. Klon akan memiliki ATK dan DEF yang sama dengan tubuh utama. Max HP klon akan meningkat sesuai dengan jumlah kerusakan yang diberikan pada tubuh utama.]],
  str_monster_ability_3100312 = "Klon dapat menyerang target berkali-kali. Penghitung Gerakan: Jarak gerakan klon akan meningkat setiap kali Aurorian menggunakan Skill Aktif selama putaran saat ini.",
  str_monster_name_531400511 = "Mia: Lustrous Soul",
  str_monster_name_531400511_en = "Mia: Lustrous Soul",
  str_monster_desc_531400511 = "Seorang ksatria Lumopolis yang menjalani kehidupan terpencil di Umbraton.",
  str_monster_ability_531400511 = "Mendapatkan buff ATK tambahan saat HP rendah. Memberikan diri perisai setiap 3 putaran untuk menahan kerusakan.",
  str_monster_name_4902501 = "Terlupakan: Minos",
  str_monster_name_4902501_en = "Forsaken: Minos",
  str_monster_passiveskill_name_4902501 = "Terlupakan: Pelemahan yang Ditentukan",
  str_monster_passiveskill_desc_4902501 = "Menghasilkan 4 ubin yang melemah pada ubin diagonal setiap putaran.",
  str_monster_passiveskill_name_4902502 = "Terlupakan: Serangan Hantu",
  str_monster_passiveskill_desc_4902502 = "Jika Terlupakan: Minos melewati ubin ditingkatkan atau ubin melemah, hantu akan dipanggil untuk memberikan kerusakan pada Aurorian.",
  str_monster_name_4900511 = "Terlupakan: Nozard",
  str_monster_name_4900511_en = "Forsaken: Nozard",
  str_monster_ability_4900511 = "Marah, Nozard terus-menerus menampar tanah untuk menjatuhkan pemain dan memanggil Gloom Ghouls untuk membantunya dalam pertempuran. Nozard tidak menerima kerusakan dari Serangan Normal.",
  str_monster_name_2905404 = "Joshua: Gelap Angel",
  str_monster_name_2905404_en = "Joshua: Dark Angel",
  str_monster_name_2905405 = "Joshua: Iblis Putih",
  str_monster_name_2905405_en = "Joshua: White Demon",
  str_monster_name_2000255 = "Penjaga Lumo Terkutuk",
  str_monster_name_2000285 = "Teman Perisai Lumo Terkutuk",
  str_monster_name_2000295 = "Lumo Piker Terkutuk",
  str_monster_desc_2905404 = "Sebagai perwujudan dari dendam yang tak ada habisnya, itu adalah bagian dari emosi Joshua yang robek, entitas tangguh yang lahir dalam kehampaan, menyimpan permusuhan terhadap semua jiwa yang memancarkan cinta.",
  str_monster_desc_2905405 = "Makhluk sempurna yang dipanggil dari kedalaman panggilan seorang ibu. Itu telah menumpahkan emosi yang tidak berguna untuk mencapai cita-cita tertinggi, pembunuh sempurna yang tidak terpengaruh oleh perasaan.",
  str_monster_desc_2000255 = "Dulunya adalah penjaga setia Lumopolis, sekarang telah dirusak dan dibuat gila oleh Joshua.",
  str_monster_desc_2000285 = "Bahkan wali terkuat pun tidak dapat menahan korupsi kejahatan. May dinding Lumopolis menjadi murni sekali lagi.",
  str_monster_desc_2000295 = "Dulu, mereka mengatakan pengguna tombak memiliki nasib terburuk, yang ternyata benar, karena invasi kejahatan menjadikan mereka sebagai targetnya sejak awal.",
  str_monster_desc_2000606 = "Terlahir dari emosi negatif, Eclipsite ini akan melacak mereka yang dibebani kutukan.",
  str_monster_ability_2905404 = "Melepaskan kekuatan kutukan yang tak ada habisnya, dan ketika kekuatan kutukan mengalahkan kehidupan yang diberikan oleh cahaya, kegelapan akan menelan segalanya.",
  str_monster_ability_2905405 = "Melepaskan kekuatan kutukan yang tak ada habisnya, dan ketika kekuatan kutukan mengalahkan kehidupan yang diberikan oleh cahaya, kegelapan akan menelan segalanya.",
  str_monster_ability_2000255 = "Para Penjaga, yang pingsan karena kutukan, akan bangkit kembali saat dijerat oleh Lurker atau di hadapan Joshua, melepaskan kekuatan kutukan melalui serangan mereka.",
  str_monster_ability_2000285 = "Teman-teman perisai, dibuat tidak sadarkan diri oleh kutukan, akan bangkit kembali ketika dijerat oleh Lurker atau di hadapan Joshua, melepaskan kekuatan kutukan melalui serangan mereka.",
  str_monster_ability_2000295 = "Piker, dibuat tidak sadarkan diri oleh kutukan, akan bangkit kembali saat terjerat oleh Lurker atau di hadapan Joshua, melepaskan kekuatan kutukan melalui serangan mereka.",
  str_monster_ability_2000606 = "Mencari tentara terkutuk di Lumopolis, merasuki mereka dan menyebabkan tentara yang koma terbangun dan jatuh ke dalam kegilaan.",
  str_monster_passiveskill_name_2000255 = "Dikutuk",
  str_monster_passiveskill_desc_2000255 = "Saat Anda menyerang Aurorian terkutuk, titik Kutukan akan naik. Tapi setelah mati, Aurorian memancarkan semburan cahaya terakhir, mengurangi titik Kutukan.",
  str_monster_passiveskill_desc_4904201 = "Saat tak terkalahkan berakhir, 1 Phantasm dipanggil untuk mengelilingi Aurorian.",
  str_monster_passiveskill_name_4904202 = "Kebangkitan Ilusi",
  str_monster_passiveskill_desc_4904202 = "Illusions hanya menerima damage dari skill dan dapat mentransfer sebagian dari damage ke Dreamwalker. Setelah mati, mereka meninggalkan 1 ubin rusak di pijakan mereka sebelum menghidupkan kembali babak berikutnya.",
  str_monster_passiveskill_desc_49042021 = "Ilusi hanya menerima kerusakan dari serangan target tunggal dan dapat mentransfer sebagian kerusakan ke Dreamwalker. Setelah mati, mereka meninggalkan 1 ubin yang rusak di pijakan mereka sebelum bangkit kembali di babak berikutnya.",
  str_monster_name_5900404 = "Klon Schummer",
  str_monster_ability_4902501 = "Memanggil ubin yang melemah di sekitarnya setiap putaran, dan menyerap ubin yang ditingkatkan dan ubin yang dilemahkan di lapangan saat menyerang. Semakin banyak ubin Minos menyerap, semakin berbahaya serangan Minos.",
  str_monster_desc_29009112 = "Musuh keji telah kembali lagi, dan bertekad untuk memusnahkan semua musuhnya kali ini.",
  str_monster_passiveskill_name_29001821 = "Tiba-tiba: Shadowgeist",
  str_monster_passiveskill_desc_29001821 = "Memanggil 2 Shadowgeist di lokasi acak.",
  str_monster_passiveskill_name_29001421 = "Tiba-tiba: Gloom Ghoul",
  str_monster_passiveskill_desc_29001421 = "Memanggil 2 Gloom Ghouls di lokasi acak.",
  str_monster_ability_29001811 = "Terampil dalam serangan jarak jauh yang akan melumpuhkan target dan memanggil Shadowgeist. Saat Rabid, serangan normalnya mengenai dua kali dengan jangkauan skill yang sangat ditingkatkan, dan dapat memanggil 2 Shadowgeist pada saat yang bersamaan.",
  str_monster_ability_29001411 = "Ahli dalam serangan jarak dekat, serangannya akan men-stun target dengan kemampuan untuk memanggil Gloom Ghoul. Setelah berubah menjadi Rabid, serangan normalnya menjadi serangan ganda dengan jangkauan skill yang sangat meningkat, dan dia dapat memanggil 2 Gloom Ghoul pada saat yang bersamaan.",
  str_monster_passiveskill_name_5900404 = "Schummer: Kembar",
  str_monster_passiveskill_desc_5900404 = "Kerusakan yang diterima oleh klon Schummer akan ditransfer ke Schummer. Saat menjadi tak terkalahkan, dia terkena stun selama 1 ronde, lalu memulihkan semua HP-nya.",
  str_monster_name_2905601 = "Dewi Denuo",
  str_monster_name_2905601_en = "Denuo Goddess",
  str_monster_desc_2905601 = "Sebuah kupu-kupu yang sangat langka, dikabarkan hanya muncul di dekat Lembah Denuo. Sifatnya penyendiri, dengan indera yang sangat tajam. Kekuatan tempur Dewi Denuo dewasa tidak boleh diremehkan.",
  str_monster_ability_2905601 = "Mereka mengkatalis pertumbuhan tanaman melalui penyerbukan, melindungi diri mereka sendiri sambil menimbulkan kerusakan besar pada musuh.",
  str_monster_name_2002601 = "Sadesian Enchantweed",
  str_monster_desc_2002601 = "Awalnya berbentuk lumut, tetapi setelah Dewi Denuo menggunakan Lumina untuk merangsang pertumbuhannya, ia akan berubah menjadi tanaman yang menyerupai bunga dan rempah-rempah.",
  str_monster_ability_2002601 = "Di bawah pengaruh katalitik Dewi Denuo, tanaman ini secara bertahap berevolusi menjadi tanaman yang sangat mematikan.",
  str_monster_name_2002602 = "Sadesian Enchantweed",
  str_monster_desc_2002602 = "Awalnya berbentuk lumut, tetapi setelah Dewi Denuo menggunakan Lumina untuk merangsang pertumbuhannya, ia akan berubah menjadi tanaman yang menyerupai bunga dan rempah-rempah.",
  str_monster_ability_2002602 = "Di bawah pengaruh katalitik Dewi Denuo, tanaman ini secara bertahap berevolusi menjadi tanaman yang sangat mematikan.",
  str_monster_name_2002603 = "Sadesian Enchantweed",
  str_monster_desc_2002603 = "Awalnya berbentuk lumut, tetapi setelah Dewi Denuo menggunakan Lumina untuk merangsang pertumbuhannya, ia akan berubah menjadi tanaman yang menyerupai bunga dan rempah-rempah.",
  str_monster_ability_2002603 = "Di bawah pengaruh katalitik Dewi Denuo, tanaman ini secara bertahap berevolusi menjadi tanaman yang sangat mematikan.",
  str_monster_name_8900181 = "Inspirasi lupa ",
  str_monster_name_8900181_en = "Oblivion Inspirer",
  str_monster_desc_8900181 = "Bisakah dia juga menjadi adik seseorang? Meskipun secara lahiriah dia impulsif dan galak, jelas bahwa di dalam hatinya terdapat jiwa yang rentan.",
  str_monster_name_8900411 = "Ksatria Oblivion",
  str_monster_name_8900411_en = "Oblivion Knight",
  str_monster_desc_8900411 = "Dia terselimuti aura pengkhianatan... dipadu dengan perjuangan terus-menerus melawan takdir yang tidak adil dan dahaga yang tak terpuaskan akan hasrat.",
  str_monster_name_8000451 = "Minion Oblivion",
  str_monster_name_8000451_en = "Minion Oblivion",
  str_monster_name_80011471 = "Pengejar Kegelapan",
  str_monster_name_80011471_en = "Pengejar Kegelapan",
  str_monster_desc_80011471 = "Dia tinggal di antara kenangan dan lupa, mengisyaratkan bahwa dia masih memegang sesuatu di dunia ini.",
  str_monster_ability_533500302 = "Tidak dapat bergerak sendiri, bertarung dengan memanggil Burstbugs yang dapat menghancurkan diri sendiri.",
  str_monster_name_99005021 = "Terlupakan: Solmorph",
  str_monster_name_99005021_en = "Forsaken: Solmorph",
  str_monster_name_99039011 = "Terlupakan: Casta",
  str_monster_name_99039011_en = "Forsaken: Casta",
  str_monster_ability_99005021 = "Menimbulkan kerusakan area besar yang tak terhindarkan; memiliki kemampuan untuk mengganti warna tile papan permainan.",
  str_monster_ability_99039011 = "Menyerang musuh dalam jarak dekat dengan bayonet atau menyerang mereka dari jarak jauh dengan peluru.",
  str_monster_desc_9900501 = "Berevolusi dari Siphorb, ia menyerap begitu banyak Lumina sehingga tidak dapat mengontrol warna cahaya di sekitarnya.",
  str_monster_passiveskill_name_29060011 = "Kesedihan: Bermetamorfosis",
  str_monster_passiveskill_desc_29060011 = "Setiap ronde, panggil a Dawn Berbunga di lokasi yang ditentukan untuk memulihkan HP; setiap Dawn Bunga memberikan dorongan pemulihan ekstra.",
  str_monster_name_2906001 = "Berduka Eve",
  str_monster_name_2906001_en = "Grieving Eve",
  str_monster_desc_2906001 = "Rasa sakit karena isolasi dan ketakutan akan terputus, kenangan masa lalu yang tak tertahankan itu, telah membentuk orang yang dikenal sebagai Eve Hari ini.",
  str_monster_ability_2906001 = "Setiap putaran, panggil a Dawn Berbunga di lokasi yang ditetapkan di medan perang, memulihkan HP sesuai dengan jumlah Dawn Bunga-bunga. Di babak tertentu, dapatkan banyak tumpukan kekebalan, lalu pulihkan HP di babak berikutnya berdasarkan tumpukan kekebalan.",
  str_monster_name_2006001 = "Dawn Bunga",
  str_monster_desc_2006001 = "Bunga putih sederhana ini, kecil dan biasa, adalah salah satu kenyamanan paling berharga di hatinya.",
  str_monster_ability_2006001 = "Memberikan bonus pemulihan HP tambahan untuk Berduka Eve.",
  str_monster_ability_2000401 = "Tidak bisa bergerak atau menyerang. Terhubung dengan Dark Summoner dan menawarkan pengurangan damage.",
  str_monster_name_2003001 = "Pemantik Api Illumina",
  str_monster_desc_2003001 = "\"Reduksi semua lawan menjadi abu\" - Mereka melambangkan efisiensi dan keganasan pasukan Illumina. Di hadapan api yang mengamuk, semua kehidupan berdiri sejajar.",
  str_monster_ability_2003001 = "Mengumpulkan Memar saat menerima kerusakan. Menimbulkan damage pada semua target dalam jangkauan serangan, mengakibatkan Burn pada mereka dan menciptakan api.",
  str_monster_passiveskill_name_2003001 = "Pemain Utama Medan Perang",
  str_monster_passiveskill_desc_2003001 = "Saat menerima damage, Illumina Flamethrower mengakumulasikan Memar setara dengan 50% dari damage yang diterima.",
  str_monster_name_2002901 = "Tangki Illumina L5",
  str_monster_desc_2002901 = "Dibuat melalui modifikasi truk, Tank Illumina L5 memiliki baju besi ringan yang cocok untuk produksi massal. Kemampuan pengisian daya dan meriam tembakan cepatnya membuat unit ringan musuh dapat dihancurkan dengan cepat.",
  str_monster_ability_2002901 = "Berdasarkan posisi musuh, pilih antara menembakkan hujan peluru dengan cepat atau melakukan serangan terburu-buru.",
  str_monster_name_2003401 = "Prajurit Illumina yang Terkorupsi",
  str_monster_name_2003401_en = "Prajurit Illumina yang Terkorupsi",
  str_monster_desc_2003401 = "Dulu sekutu, kini musuh—begitulah ketakutan akan Eclipse. Belas kasihan yang tersisa hanyalah untuk menenangkan mereka.",
  str_monster_ability_2003401 = "Membuat rawa-rawa pada ubin yang dilewati. Ketika HP rendah, meningkatkan ACT secara signifikan dan meningkatkan DEF.",
  str_monster_passiveskill_name_20034011 = "Pikiran yang Terkorupsi",
  str_monster_passiveskill_desc_20034011 = "Jika HP di bawah 40% di awal ronde, unit tersebut memiliki ACT dan DEF yang meningkat serta gaya serangan yang berubah.",
  str_monster_passiveskill_name_20034012 = "Langkah yang Rusak",
  str_monster_passiveskill_desc_20034012 = "Membuat rawa-rawa di ubin yang dilewati.",
  str_monster_name_2003101 = "Sersan Illumina",
  str_monster_desc_2003101 = "Sebagai perwira tingkat dasar dari tentara Illumina, mereka bertanggung jawab untuk memimpin prajurit biasa di medan perang. Sebagian besar dari mereka lulusan dari akademi militer, sementara beberapa yang terpilih dipromosikan dari jajaran veteran berpengalaman.",
  str_monster_ability_2003101 = "Kehadiran mereka meningkatkan kemampuan Prajurit Illumina di sekitar dan membantu mereka pulih dari Luka memar. Jika mereka terpisah dari sekutu atau berada dalam jarak dekat dengan musuh, sersan ini mengambil senjata, menimbulkan kerusakan dengan potongan mematikan dan tendangan berdampak.",
  str_monster_name_2002701 = "Medik Illumina",
  str_monster_desc_2002701 = "Di mana pun Medik Illumina berdiri, semangat meningkat, karena rekan-rekan tahu bahwa luka mereka tidak akan dibiarkan tanpa perawatan. Illumina Federation, yang sangat menyadari hal ini, memberikan perlindungan yang ditingkatkan kepada medik-medik ini, sehingga meningkatkan kemampuan bertahan hidup mereka secara signifikan.",
  str_monster_ability_2002701 = "Seorang Prajurit Illumina tanpa kemampuan bertarung. Mengembalikan HP untuk Prajurit Illumina terdekat dan mengobati beberapa Luka untuk diri mereka sendiri.",
  str_monster_name_2002801 = "Penyiar Sinyal Illumina",
  str_monster_desc_2002801 = "Dilengkapi dengan komunikator kompak, Signalman Illumina menanggung beban berat. Oleh karena itu, Illumina Federation telah mengembangkan perangkat pendukung khusus, yang memfasilitasi transmisi sinyal mereka saat bergerak, yang merupakan asal dari nama unit ini.",
  str_monster_ability_2002801 = "Seorang Prajurit Illumina tanpa kemampuan bertempur tetapi mampu memanggil bala bantuan Illumina ke medan perang.",
  str_monster_passiveskill_name_2002701 = "Keteguhan Medan Perang",
  str_monster_passiveskill_desc_2002701 = "Saat menerima damage, Illumina Medik akan mengumpulkan Memar setara dengan 50% dari damage yang diterima. Selain itu, DEF mereka akan meningkat seiring berkurangnya HP.",
  str_monster_name_2003301 = "Dreadweaver",
  str_monster_desc_2003301 = "Didorong oleh obsesi untuk melenyapkan segalanya, ia mengabaikan pelepasan energi sendiri, tanpa henti mengejar tujuan, meskipun itu berarti perlahan-lahan menuju kehancuran dirinya sendiri.",
  str_monster_ability_2003301 = "Setelah gerakan tim berakhir, Dreadweaver akan segera membuat tim mengubah posisi mereka, mempengaruhi jangkauan Chain Combos. Ketika HP Dreadweaver turun di bawah 50%, ia akan memulai ritual pengorbanan—Pada putaran berikutnya, ia akan membakar HP-nya saat ini hingga tinggal 1 poin, memberikan true damage kepada pemain sebanding dengan beberapa kali lipat HP yang terbakar.",
  str_monster_passiveskill_name_2003301 = "Manipulasi Psionik",
  str_monster_passiveskill_desc_2003301 = "Setelah pergerakan tim berakhir, Dreadweaver akan segera membuat tim mengubah posisi mereka, yang mempengaruhi penggunaan Chain Combo.",
  str_monster_passiveskill_name_2003302 = "Korban Darah",
  str_monster_passiveskill_desc_2003302 = "Ketika HP Dreadweaver turun di bawah 50%, ia akan memulai ritual pengorbanan. Pada putaran berikutnya, ia akan membakar hampir seluruh HP-nya, memberikan kerusakan nyata besar pada pemain. Efek ini hanya dapat diaktifkan sekali.",
  str_monster_name_7001098 = "Ditinggalkan: Schummer si Aviduz",
  str_monster_name_7001098_en = "Forsaken: Schummer the Aviduz",
  str_monster_ability_7001098 = "Secara berkala memanggil petir. Lightning Power akan melumpuhkan target yang terkena. Colossus Shriek dapat menarik Aurorian mendekati si penyihir.",
  str_monster_name_2906101 = "Corrupted Engine VII",
  str_monster_name_2906101_en = "Corrupted Engine VII",
  str_monster_desc_2906101 = "Awalnya mecha tempur raksasa yang dibuat oleh Illumina, namun berubah menjadi ancaman yang sangat ditakuti setelah pilotnya kehilangan akal karena terkontaminasi oleh lumpur.",
  str_monster_ability_2906101 = "Menerjang tanpa henti menuju Benteng Illumina, memberikan kerusakan pada Aurorian di sepanjang perjalanan.",
  str_monster_passiveskill_name_29061011 = "Perbaiki",
  str_monster_passiveskill_desc_29061011 = "Engine VII yang rusak dengan ketidak terkalahkan akan lumpuh. Selama periode ini, ia akan memperbaiki komponennya, dan setelah perbaikan selesai, ia akan dikerahkan kembali untuk pengepungan.",
  str_monster_name_2905701 = "Mudbundle",
  str_monster_name_2905701_en = "Mudbundle",
  str_monster_desc_2905701 = "Konon diciptakan oleh anggota Eclipse, Eclipsite ini merupakan fusi dari berbagai sifat biologis. Ia menciptakan rawa-rawa mengerikan yang dapat melahap segala sesuatu dan mencemari apa pun yang disentuhnya.",
  str_monster_ability_2905701 = "Menciptakan rawa dan tenggelam di dalamnya, menghalangi dan mengganggu pergerakan Aurorian di dalamnya, mengubah medan.",
  str_monster_name_8002005 = "Irridon",
  str_monster_name_8002005_en = "Irridon",
  str_monster_desc_8002005 = "Lumo Hall of Justice Chief Judge. Dia baik, lembut, jujur dan tangguh, serta punya semangat pengabdian diri. Sisi paranoid ada dalam hatinya, tapi dia menekannya.",
  str_monster_ability_8002005 = "Berada di luar lapangan, tidak bisa menjadi target serangan normal. Membagi kerusakan dengan semua musuh di lapangan.",
  str_monster_name_2003501 = "Binatang Rime",
  str_monster_name_2003501_en = "Binatang Rime",
  str_monster_desc_2003501 = "Dengan bulu dan cakar tajamnya, Eclipsite ini memiliki kemiripan yang mencengangkan dengan binatang buas, membuatnya sangat cocok untuk menyusup ke berbagai wilayah perbatasan untuk melacak, mengintai, dan berburu.",
  str_monster_ability_2003501 = "Ini akan memilih skill yang berbeda berdasarkan posisi Aurorian, dan jika serangannya tidak dapat mencapai Aurorian mana pun, ia akan memilih untuk memulihkan HP-nya sendiri.",
  str_monster_name_2900891 = "Irridon: Eximius",
  str_monster_name_2900891_en = "Irridon: Eximius",
  str_monster_desc_2900891 = "Mewarisi ajaran sungguh-sungguh dari ayahnya dan memenuhi semua harapannya, ia telah menjadi Irridon yang sempurna, Chief Judge terhebat yang pernah dikenal!",
  str_monster_ability_2900891 = [[
Sebelum setiap Chain Combo dari Aurorian, ia membentuk Perisai Cahaya untuk menghalau damage.
Meningkatkan semua damage yang diberikan berdasarkan jumlah tumpukan Prejudice pada Aurorian.]],
  str_monster_passiveskill_name_29089011 = "Perisai Cahaya",
  str_monster_passiveskill_desc_29089011 = "Sebelum setiap Chain Combo, membentuk Shield of Light, yang memblokir damage sebanding dengan persentase HP Maks.",
  str_monster_passiveskill_name_29089012 = "Wrath dari Chief Judge",
  str_monster_passiveskill_desc_29089012 = "Memiliki beberapa segmen HP. Di awal setiap ronde, jika dia kehilangan satu segmen HP dibandingkan dengan ronde sebelumnya, dia akan melepaskan Hukuman Hakim Ketua, yang menimbulkan kerusakan besar.",
  str_monster_passiveskill_name_29089021 = "Transmisi Kerusakan",
  str_monster_passiveskill_desc_29089021 = "Kerusakan yang diberikan kepada Irridon: Klon Eximius langsung ditransfer ke Irridon: Eximius.",
  str_monster_name_2003601 = "Crimson Specter",
  str_monster_desc_2003601 = "Kesombongan, prasangka, dan pikiran yang rusak... telah membeku menjadi hantu jahat yang berkeliaran di Lumopolis, meresap ke setiap celah kota abadi ini.",
  str_monster_ability_2003601 = "Ia dapat teleportasi ke lokasi pemain terdekat, memberikan beberapa serangan yang merusak dan mendorong pemain ke belakang. Semakin jauh ia teleportasi, semakin sedikit serangan yang diluncurkan.",
  str_monster_name_2902131 = "No. 33: Penjaga Tanpa Nama",
  str_monster_name_2902131_en = "No. 33 - The Nameless Keeper",
  str_monster_desc_2902131 = "Seorang Aurorian kuno, penjaga reruntuhan bawah tanah di Northlands. Dia telah hidup sendirian selama bertahun-tahun, bahkan kenangannya mulai memudar.",
  str_monster_ability_2902131 = "Mampu menyerang Aurorian dari jarak jauh dari mana saja; Dapat mengubah Elemen Tile di sekitar Aurorian lain dan dirinya sendiri.",
  str_monster_passiveskill_name_290213101 = "Kontrol Area",
  str_monster_passiveskill_desc_290213101 = "Setelah aksinya berakhir di setiap putaran, ia mengubah elemen ubin dalam 2 klaster di sekitar.",
  str_monster_ability_5353002 = "Mahir dalam serangan jarak jauh dan AoE; Memasuki kondisi Rabid ketika HP turun di bawah 30%, terus menerus mengeluarkan skill damage layar penuh. Menghitung 1 Keterampilan Aktif per putaran dan melemparkan 5 tumpukan perisai hitungan untuk perlindungan diri.",
  str_monster_ability_5353007 = "Memberikan kerusakan dalam area tertentu dan mendorong mundur unit musuh.",
  str_monster_passiveskill_name1_2900401 = "Rabid",
  str_monster_passiveskill_desc1_2900401 = "Jatuh ke kondisi Rabid saat HP rendah: lepaskan Colossus: Sonic Blast untuk serangan layar penuh setiap putaran.",
  str_monster_passiveskill_name2_2900401 = "Perisai Memangsa",
  str_monster_passiveskill_desc2_2900401 = "Mengelilingi dirinya dengan 5 tumpukan perisai hitungan, masing-masing menawarkan kekebalan terhadap kerusakan 1 kali (Penghitungan dibatasi hanya 1 kali per putaran).",
  str_monster_passiveskill_name_5353004 = "Pemanggilan Gloom Ghoul",
  str_monster_passiveskill_desc_5353004 = "Memanggil Gloom Ghoul di lokasi acak.",
  str_monster_name_2902801 = "Sanki",
  str_monster_name_2902801_en = "Sanki",
  str_monster_desc_2902801 = "\"Ketika kejahatan memanggil di antara bunga sakura, Sakae melarikan diri, ditinggalkan oleh penduduk; hanya satu dari sepuluh yang selamat.\" Dengan target dalam pandangan, pertempuran demi balas dendamnya dimulai di sini.",
  str_monster_ability_2902801 = "Sanki memiliki mobilitas tinggi, meluncurkan serangan cepat setiap beberapa putaran untuk mendekati target dan memberikan kerusakan dengan cepat. Dalam setiap gerakan, Sanki melepaskan Pedang Sakae ke medan perang, hanya untuk mengambilnya kembali pada gerakan berikutnya, menimbulkan kerusakan besar pada target musuh di sepanjang jalannya.",
  str_monster_name_70011021 = "Terlupakan: Sanki",
  str_monster_name_70011021_en = "Forsaken: Sanki",
  str_monster_passiveskill_name_2902801 = "Sakae: Kontrol",
  str_monster_passiveskill_desc_2902801 = "Sebelum Sanki melakukan aksi, dia melepaskan Pedang Sakae ke empat arah di medan, hanya untuk mengambilnya kembali pada langkah berikutnya. Pedang Sakae memberikan kerusakan besar pada unit musuh di sepanjang jalur mereka saat dilepaskan atau diambil kembali.",
  str_monster_name_70011023 = "Terlupakan: Brock",
  str_monster_name_70011023_en = "Forsaken: Brock",
  str_monster_desc_70011023 = "Anggota tim Rediesel Wrench Loose Screws, Brock adalah orang yang bersemangat dan percaya diri yang kadang-kadang melakukan hal-hal bodoh untuk memuaskan sifat kompetitifnya.",
  str_monster_ability_70011023 = "Dengan ATK dan ACT yang luar biasa, Brock juga dapat menarik musuh ke sekitarnya melalui kemampuan ultimate-nya.",
  str_monster_name_70011041 = "Terlupakan: Schwartz",
  str_monster_name_70011041_en = "Forsaken: Schwartz",
  str_monster_desc_70011041 = "Gubernur Lumopolis, penguasa terhebat, dikenal karena pengabdian tanpa pamrihnya. Ia bahkan mungkin mengunjungi arena secara langsung untuk menilai kemampuan semua orang.",
  str_monster_ability_70011041 = "Schwartz memanfaatkan Kekuatan Petir yang luar biasa, memberinya tingkat mobilitas dan kekuatan penghancur yang menakutkan. Mereka yang berhasil melewati ujian kekuatan formidabelnya dianggap sebagai yang terbaik di antara yang terbaik.",
  str_monster_name_5352021 = "Lumo Shieldmate",
  str_monster_name_5352021_en = "Lumo Shieldmate",
  str_monster_desc_5352021 = "Guard dipersenjatai dengan defense shield yang kuat. Dengan kemampuan untuk bertahan dalam pertempuran sengit, mereka bagaikan tembok kuat yang melindungi rekan-rekannya.",
  str_monster_ability_5352021 = "Seorang penjaga tangguh dengan kemampuan bertahan luar biasa dapat memanggil prajurit Lumopolis lainnya untuk membantu dalam pertempuran dan meningkatkan semangat mereka. Memegang perisai kuat yang dapat digunakan untuk menimbulkan serangan jarak dekat yang menghancurkan.",
  str_monster_name_2905801 = "Emperor of Demise",
  str_monster_name_2905801_en = "Emperor of Demise",
  str_monster_desc_2905801 = "Kaisar Tertinggi Kekacauan, ayah Tohru, seorang veteran dalam banyak perang, adalah kekuatan yang tak terbantahkan kapan pun dan di mana pun.",
  str_monster_ability_2905801 = "Dengan kekuatan yang tangguh, ia menguasai berbagai keterampilan untuk menargetkan pemain dengan presisi atau melancarkan serangan jarak luas, sekaligus mendorong mereka mundur.",
  str_monster_passiveskill_name_2905801 = "Melemahnya Lumina",
  str_monster_passiveskill_desc_2905801 = "Serangan normal dan chain combo pemain menimbulkan damage yang berkurang ke 5 tile yang ditempati bos, kecuali tile pusat.",
  str_monster_ability_140045106 = "Gunakan Nails",
  str_monster_ability_150092106 = "Menimbulkan damage pada musuh dalam area berbentuk X sambil mengonversi tile Merah yang merugikan bagi penyihir.",
  str_monster_ability_160103106 = "Menimbulkan damage pada musuh terdekat sambil mengubah tile Biru yang merugikan bagi penyihir.",
  str_monster_ability_160111106 = "Berperang menggunakan kristal, menimbulkan kerusakan pada semua musuh di medan perang.",
  str_monster_ability_150009106 = "Menimbulkan damage pada musuh dalam area berbentuk lingkaran dan dapat mengakibatkan efek Frighten pada target yang terkena.",
  str_monster_ability_160120106 = "Baju zirah raksasa miliknya, yang bernama Pompey, dapat memberikan kerusakan di area yang luas sambil memberikan kerusakan tambahan kepada musuh dalam 1 kelompok sekitar.",
  str_monster_ability_160089106 = "Terus menerus melepaskan Gold Marsh Sword Rain untuk memberikan kerusakan pada target yang berdekatan.",
  str_monster_name_39004031 = "Terlupakan: Schummer",
  str_monster_name_39004031_en = "Terlupakan: Schummer",
  str_monster_desc_39004031 = "Dulunya Caelestite, lalu bergabung dengan Eclipse dan kekuatannya meningkat tajam.",
  str_monster_ability_39004031 = "Mahir dalam serangan jarak jauh dan area.",
  str_monster_name_39058011 = "Yang Ditinggalkan: Kaisar Kehancuran",
  str_monster_name_39058011_en = "Yang Ditinggalkan: Kaisar Kehancuran",
  str_monster_desc_39058011 = "Kaisar Tertinggi Kekacauan, ayah Tohru, seorang veteran dalam banyak perang, adalah kekuatan yang tak terbantahkan kapan pun dan di mana pun.",
  str_monster_ability_39058011 = "Dengan kekuatan yang tangguh, ia menguasai berbagai keterampilan untuk menargetkan pemain dengan presisi atau melancarkan serangan jarak luas, sekaligus mendorong mereka mundur.",
  str_monster_ability_5362001 = "Akan bersembunyi di Lumiwall terjauh dari pemain; serangannya bisa mengubah elemen tile di jalur serangannya.",
  str_monster_name_5362001 = "Gronru",
  str_monster_name_5362001_en = "Gronru",
  str_monster_desc_5362001 = "Pilot wanita dari mecha raksasa dan saat ini menjabat sebagai Tech Officer dari Illumina Federation. Orang bilang dia pensiunan genius dari militer... Meskipun dia tidak terlalu tertarik dalam pertempuran, dia sangat bersemangat untuk mempelajari dan mengendalikan mesin raksasa hingga hampir menjadi obsesinya.",
  str_monster_ability_5362002 = "Mahir melancarkan serangan jarak dekat, menimbulkan damage pada satu area kolom.",
  str_monster_desc_5362002 = "Pegawai teknisi Rediesel Wrench yang sangat percaya diri dengan teknologi komunikasinya. Dia suka mengeluh dan meneriaki orang lain di Comm Channel, tapi dia kebingungan saat ada masalah.",
  str_monster_ability_5362003 = "Mahir dalam serangan area jarak jauh, skill-nya memberikan efek Poison.",
  str_monster_name_2909001 = "Raja Merman",
  str_monster_name_2909001_en = "Raja Merman",
  str_monster_desc_2909001 = "Dari dunia permukaan ke kota bawah air, seorang bangsawan yang angkuh dan jahat.",
  str_monster_ability_2909001 = "Serangan menimbulkan efek knockback. Dapat memanggil meriam salvo di tepi medan perang.",
  str_monster_passiveskill_name_290900101 = "Penempatan Senapan Salvo",
  str_monster_passiveskill_desc_290900101 = "Di awal setiap putaran pemain, jika kurang dari 2 Salvo Guns di medan perang, memanggil 4 Salvo Guns di tepi medan perang.",
  str_monster_passiveskill_name_290901101 = "Penempatan Senapan Salvo",
  str_monster_passiveskill_desc_290901101 = "Di awal setiap putaran pemain, jika kurang dari 3 Salvo Guns berada di medan perang, memanggil 4 Salvo Guns di tepi medan perang.",
  str_monster_name_70011101 = "Ditinggalkan: Diavola",
  str_monster_name_70011101_en = "Ditinggalkan: Diavola",
  str_monster_desc_70011101 = "Diavola suka bersembunyi dan menghabisi musuhnya secara diam-diam dengan racun.",
  str_monster_ability_70011101 = "Diavola tidak bisa bergerak. Tubuhnya dibungkus oleh daun berduri besar dan kokoh yang mengurangi kerusakan yang diterimanya.",
  str_monster_passiveskill_name_70011101 = "Daun Berduri",
  str_monster_passiveskill_desc_70011101 = "Mengurangi kerusakan yang diterima pada 8 ubin luar Diavola sebesar 30%.",
  str_monster_passiveskill_name_70011102 = "Daun Berduri",
  str_monster_passiveskill_desc_70011102 = "Mengurangi kerusakan yang diterima pada 8 ubin luar Diavola sebesar 50%.",
  str_monster_name_2003801 = "Kapten Geng",
  str_monster_desc_2003801 = "Pemimpin geng yang berpenampilan aneh, ahli dalam senjata api. Kehadirannya hanya menimbulkan masalah bagi Umbraton.",
  str_monster_ability_2003801 = "Attacks after moving away from the target, dealing damage 2 times. Can steal the target's attributes.",
  str_monster_passiveskill_name_2003801 = "Tembakan Mematikan",
  str_monster_passiveskill_desc_2003801 = "Mencuri ATK Dasar dan DEF Dasar Aurorian saat memberikan kerusakan. ATK dan DEF yang dicuri akan dikembalikan setelah 2 putaran atau setelah unit ini dikalahkan.",
  str_monster_name_2003701 = "Pemanah Gangster",
  str_monster_desc_2003701 = "Akurat, aman, diskret, dan sangat kuat, busur silang telah menjadi senjata yang disukai oleh gangster karena sifat-sifat tak tertandingi ini. Musuh yang ahli dalam penggunaannya sering kali sangat berbahaya.",
  str_monster_ability_2003701 = "Dapat menyerang target dalam bentuk silang hingga batas maksimum jangkauannya. Setelah mengenai, mengurangi penyembuhan yang diterima target.",
  str_monster_passiveskill_name_2003701 = "Panah Bayangan",
  str_monster_passiveskill_desc_2003701 = "Setelah mengenai Aurorian, mengurangi healing yang diterima sebesar 40%. Efek ini tidak menumpuk dan akan hilang saat Gang Crossbowman dikalahkan.",
  str_monster_name_2009001 = "Senapan Salvo",
  str_monster_desc_2009001 = "Eclipsite yang menyerupai laras senjata. Memberikan dukungan kepada teman-temannya dan menyerang tim Anda dengan keras!",
  str_monster_ability_2009001 = "Menembak musuh dalam jangkauan serangan. Jika tidak ada target yang tersedia, serangannya ditingkatkan dan menyembuhkan Raja Merman.",
  str_monster_name_8003481 = "Dayna",
  str_monster_desc_8003481 = "Meskipun usianya masih muda, dia sudah menjadi pemimpin Spearows. Dia terkenal karena membangun pijakan yang kuat di jalanan Umbraton dengan tekadnya yang tak tertandingi dan senjata licik yang jahat.",
  str_monster_ability_8003481 = "Menyerang musuh terdekat.",
  str_monster_name_8003781 = "Robyn",
  str_monster_desc_8003781 = "Anggota Spearows di Umbraton. Seorang introvert pemalu, dia tetap dekat dengan saudara perempuannya, Dayna, ketika mencoba untuk bertahan hidup di Umbraton.",
  str_monster_ability_8003781 = "Mengikuti pemain dan memberikan damage area pada musuh di sekitar.",
  str_monster_ability_2300601 = "Lurker dapat menempelkan diri pada Aurorian dalam 1 klaster di sekitar mereka. Setelah menempel, mereka memberikan damage pada Aurorian dan mengurangi ATK mereka.",
  str_monster_name_2909101 = "Rebecca Rawa Beracun",
  str_monster_desc_2909101 = "Pembuluh darahnya berdenyut dengan racun merah darah, siap untuk membasmi ancaman apa pun terhadap keluarganya, termasuk dirinya sendiri.",
  str_monster_ability_2909101 = "Memungkinkan serangan untuk memberikan efek Fusion, menyebabkan target yang terkena efek kehilangan HP di awal putaran mereka. Memanggil Tanda Racun pada tile sekitarnya setiap putaran, memberikan efek Fusion pada musuh di dekatnya yang lewat; Tanda Racun berubah menjadi Tile Gelap di akhir putaran.",
  str_monster_name_2003901 = "Spesialis Dukungan Geng",
  str_monster_desc_2003901 = "Anggota geng raksasa yang sangat kuat, ahli dalam menggunakan lengan mekaniknya untuk bertarung. Selain itu, dia dapat memberikan dukungan kepada pasukan musuh Umbraton lainnya di medan perang.",
  str_monster_ability_2003901 = "Memberikan peningkatan ATK dan DEF kepada anggota Umbraton dalam 1 klaster di sekitarnya; menyembuhkan diri sendiri ketika HP-nya turun di bawah persentase tertentu.",
  str_monster_passiveskill_name_2003901 = "Dukungan Ekstra",
  str_monster_passiveskill_desc_2003901 = "Memberikan peningkatan ATK dan DEF kepada anggota Umbraton dalam 1 klaster di sekitar.",
  str_monster_name_2004101 = "Pembunuh Geng",
  str_monster_desc_2004101 = "\"Serangan terbaik adalah yang datang dari belakang.\" Ahli dalam menyerang titik vital, pisau unit ini sangat mematikan baik dalam pertarungan jalanan maupun di medan perang.",
  str_monster_ability_2004101 = "Meluncurkan 2 serangan berturut-turut dengan cepat terhadap musuh. Mencuri ATK Dasar dan DEF Aurorian saat memberikan kerusakan. ATK dan DEF yang dicuri akan dikembalikan setelah 2 putaran atau setelah unit ini dikalahkan. Mundur setelah menyerang untuk melindungi diri. Jika target tidak dapat diserang, ACT +1 di putaran ini.",
  str_monster_passiveskill_name_2909101 = "Korosi Beracun",
  str_monster_passiveskill_desc_2909101 = "Memungkinkan serangan untuk memberikan efek Fusion, menyebabkan target yang terkena efek kehilangan HP di awal putaran mereka. Memanggil Tanda Racun pada tile sekitarnya setiap putaran, memberikan efek Fusion pada musuh di dekatnya yang lewat; Tanda Racun berubah menjadi Tile Gelap di akhir putaran.",
  str_monster_passiveskill_name_2004101 = "Semangat Bertempur",
  str_monster_passiveskill_desc_2004101 = "Mencuri ATK Dasar dan DEF Dasar Aurorian saat memberikan kerusakan. ATK dan DEF yang dicuri akan dikembalikan setelah 2 putaran atau setelah unit ini dikalahkan.",
  str_monster_name_2909101_en = "Rebecca Rawa Beracun",
  str_monster_name_2003801_en = "Kapten Geng",
  str_monster_name_70011071 = "Terlupakan: Kittypus",
  str_monster_name_70011071_en = "Terlupakan: Kittypus",
  str_monster_desc_70011071 = "Teman spesial Gretel. Ia menyerupai kucing dengan banyak kaki... Ia lucu, tetapi entah kenapa sedikit mengganggu.",
  str_monster_ability_70011071 = "Kittypus melepaskan tentakelnya, menimbulkan kerusakan besar pada Aurorian. Ingat: Tentaclaw Kittypus mentransfer semua kerusakan yang masuk ke inangnya!",
  str_monster_name_70011081 = "Forsaken: Dark Goldor",
  str_monster_name_70011081_en = "Forsaken: Dark Goldor",
  str_monster_desc_70011081 = "Armored Eclipsite dari White Night, Black Underbelly.",
  str_monster_ability_70011081 = "Tidak dapat bergerak tetapi bisa menyerang dan mendorong mundur target dalam area yang luas.",
  str_monster_name_70011091 = "Ditinggalkan: Dewi Denuo",
  str_monster_name_70011091_en = "Ditinggalkan: Dewi Denuo",
  str_monster_desc_70011091 = "Kupu-kupu yang sangat langka. Sifatnya penyendiri, dengan indera yang sangat tajam. Kekuatan bertarungnya jangan diremehkan.",
  str_monster_ability_70011091 = "Mereka mengkatalis pertumbuhan tanaman melalui penyerbukan, melindungi diri mereka sendiri sambil menimbulkan kerusakan besar pada musuh.",
  str_monster_ability_70011083 = "Menyajikan tingkat bahaya yang sangat rendah, ia langsung melarikan diri dalam ketakutan setelah Aurorian menggunakan Skill Aktif mereka.",
  str_monster_name_2909201 = "Stinger: Koalesensi",
  str_monster_name_2909202 = "Ekor Sengat",
  str_monster_name_2909201_en = "Stinger: Koalesensi",
  str_monster_desc_2909201 = "Senjata berbahaya yang diciptakan dengan menggabungkan karakteristik mematikan dari berbagai ciptaan mekanis, termasuk teknologi dari Astra. Sumber daya listrik biasa tidak mampu menjalankan makhluk raksasa ini.",
  str_monster_ability_2909201 = "Setiap Clockwork Beast yang membentuk bagian tubuhnya memiliki serangan unik tersendiri. Ekor dapat mengumpulkan Energi untuk memberikan kerusakan yang pasti pada targetnya, tetapi juga cukup rapuh.",
  str_monster_passiveskill_name_290920101 = "Armor Tak Terkalahkan",
  str_monster_passiveskill_desc_290920101 = "Mendapatkan Shield sebesar persentase HP Maks di awal setiap putaran. Sisa Shield akan dikonversi menjadi HP di akhir putaran.",
  str_monster_passiveskill_name_290920102 = "Penghindaran Kerusakan",
  str_monster_passiveskill_desc_290920102 = "Ekor Stinger hanya bisa dirusak oleh skill Sniper dan kebal terhadap serangan normal dan damage area. Ketika ekornya memiliki sisa HP nol, Stinger lumpuh selama 1 putaran.",
  str_monster_name_2004001 = "Kepiting yang Ditempa di Tungku",
  str_monster_desc_2004001 = "Penciptaan alat mekanis ini dirancang untuk membantu pengrajin membuat penemuan yang cerdas. Kemudian, alat ini dimodifikasi sehingga variasi dari penemuan ini bisa menyimpan Flame Force di perutnya. Alat ini tidak pernah dimaksudkan untuk digunakan sebagai senjata.",
  str_monster_ability_2004001 = "Ia bergerak menyamping seperti kepiting, mengayunkan capitnya, dan dapat memuntahkan api.",
  str_monster_name_70011141 = "Yang Ditinggalkan: Rebecca Rawalumpur Beracun",
  str_monster_name_70011141_en = "Yang Ditinggalkan: Rebecca Rawalumpur Beracun",
  str_monster_name_70011151 = "Ditinggalkan: Mudbundle",
  str_monster_name_70011151_en = "Ditinggalkan: Mudbundle",
  str_monster_ability_2003411 = "Membuat rawa-rawa di ubin yang dilewati. Memiliki DEF yang sangat tinggi, ia akan meregenerasi dan meningkatkan dirinya sendiri setelah ia ditelan.",
  str_monster_name_2906201 = "Vilanor: Perangkap Terkutuk",
  str_monster_name_2906201_en = "Vilanor: Perangkap Terkutuk",
  str_monster_desc_2906201 = "Sebuah pedang yang terampil dibuat dari kecerdasan Kerajaan Ye di Longzhou. Awalnya ditujukan sebagai senjata pertahanan diri bagi mereka yang tidak tahu cara membela diri dengan pedang, tetapi sekarang telah menjadi pedang jahat yang terkutuk setelah jatuh ke tangan penjahat.",
  str_monster_ability_2906201 = "Setelah menjadi Vilanor, kemampuannya sangat ditingkatkan, mendapatkan kekuatan untuk bergerak bebas di medan dan menghasilkan pedang dari energi jahat.",
  str_monster_passiveskill_name_290620101 = "Dendam Mendalam",
  str_monster_passiveskill_desc_290620101 = "Sebelum bergerak, Vilanor memanggil serat-serat Energi Pedang Jahat di lokasi acak berdasarkan jumlah kerusakan yang telah diterimanya di putaran ini. Semakin banyak kerusakan yang diterima di putaran ini, semakin banyak serat Energi Pedang Jahat yang dipanggil.",
  str_monster_name_2004301 = "Energi Pedang Jahat",
  str_monster_desc_2004301 = "Energi pedang yang dilepaskan oleh Vilanor mengambil bentuk seperti pedang setelah mencapai kepadatan tertentu.",
  str_monster_ability_2004301 = "Energi pedang yang dipanggil oleh Vilanor tidak bisa menyerang atau bergerak, tetapi akan menduduki tile tempat ia berada, membuatnya tidak dapat dilalui.",
  str_monster_desc_1602191 = "Kontender - Istvan",
  str_monster_ability_1602191 = "Setelah bergerak, melakukan Normal Attack atau Chain Combo, memberikan banyak damage kepada Eclipsite.",
  str_monster_ability_1602192 = "Setelah bergerak, melakukan Serangan Normal atau Kombo Rantai, memberikan banyak kerusakan pada Aurorian.",
  str_monster_name_1600391 = "Istvan",
  str_monster_name_1600391_en = "ISTVAN",
  str_monster_name_70011191 = "Terlupakan: Fujikumo Nobutora - Devour",
  str_monster_name_70011191_en = "Terlupakan: Fujikumo Nobutora - Devour",
  str_monster_ability_70011191 = "Munculkan sejumlah besar hantu dan lepaskan berbagai kemampuan kuat berdasarkan jarak antara Aurorian dan musuh di setiap putaran.",
  str_monster_passiveskill_name_200440101 = "Kontaminasi Mekanis",
  str_monster_passiveskill_desc_200440101 = "Merefleksikan damage setelah menerima damage dari Serangan Normal Aurorian.",
  str_monster_passiveskill_name_200460101 = "Perbaikan Mekanik",
  str_monster_passiveskill_desc_200460101 = "Memulihkan persentase tertentu dari HP yang hilang di awal setiap putaran.",
  str_monster_name_2004401 = "Soldier Voidcross",
  str_monster_desc_2004401 = "Senjata perang yang diciptakan melalui fusi Eclipsite dan Aurorian. Karakteristik Aurorian dipertahankan sebanyak mungkin, dan mekanisasi tidak terlalu jelas, tetapi masih sangat berbahaya.",
  str_monster_ability_2004401 = "Sebuah bentuk kehidupan mekanis yang menyerang dengan cara meretas dan memotong.",
  str_monster_name_2004501 = "Prajurit Ululat",
  str_monster_desc_2004501 = "Senjata perang yang diciptakan melalui fusi antara Eclipsite dan Aurorian. Senjata ini dilindungi oleh lapisan baju besi mekanik yang tebal, dan kekuatannya telah ditingkatkan sebesar mungkin.",
  str_monster_ability_2004501 = "Kekuatan dan pertahanan bentuk kehidupan mekanis yang telah dimodifikasi ini telah sangat ditingkatkan, dan ia sangat ahli dalam menyerang dengan ledakan dan metode serupa lainnya.",
  str_monster_name_2004601 = "Super-Soldier Meaugm",
  str_monster_name_2004601_en = "Super-Soldier Meaugm",
  str_monster_desc_2004601 = "Senjata super yang diciptakan melalui fusi antara Eclipsite dan Aurorian. Ia tidak lagi memiliki karakteristik Aurorian dan kini menjadi eksistensi yang sepenuhnya mekanis.",
  str_monster_ability_2004601 = "Bentuk kehidupan mekanis yang dimodifikasi ini dapat menggunakan baju besinya yang tebal sebagai senjata, membuatnya sangat sulit untuk ditangani.",
  str_monster_name_2906401 = "Super-Prajurit Blaugm",
  str_monster_name_2906401_en = "Super-Prajurit Blaugm",
  str_monster_desc_2906401 = "Super tentara ini adalah Eclipsite yang telah dilengkapi dengan perangkat mekanis di seluruh tubuhnya untuk membuatnya lebih tangguh, lebih ganas, dan lebih menakutkan.",
  str_monster_ability_2906401 = "Seorang prajurit super yang menakutkan yang unggul dalam menghancurkan musuh di sekitarnya dengan serangannya.",
  str_monster_passiveskill_name_290640101 = "Absorpsi Mekanis",
  str_monster_passiveskill_desc_290640101 = "Mendapatkan 1 tumpukan Armor Mekanis saat menerima Serangan Normal. Setiap tumpukan mengurangi Serangan Normal yang diterima sebesar 1%. Jumlah tumpukan buff ini berkurang setengahnya di awal putaran.",
  str_monster_passiveskill_name_290640102 = "Pertahanan Mekanik",
  str_monster_passiveskill_desc_290640102 = "Mengurangi damage yang diterima dari serangan frontal.",
  str_monster_passiveskill_name_290640103 = "Kegilaan Mekanik",
  str_monster_passiveskill_desc_290640103 = "Meningkatkan kerusakan saat HP sendiri berkurang.",
  str_monster_name_2906301 = "Ulysses Bio",
  str_monster_name_2906301_en = "Ulysses Bio",
  str_monster_desc_2906301 = "Ulysses telah mengubah tubuhnya secara ekstensif untuk mewujudkan idealisme ekstremnya. Dia bukan lagi seorang Aurorian sekarang.",
  str_monster_ability_2906301 = "Ulysses menggunakan strategi serangan yang berbeda berdasarkan kemampuan dari Aurorian.",
  str_monster_passiveskill_desc_8024441 = "Ketika Murkmite mengenai target, mengurangi poin kekuatan target sebanyak 2.",
  str_monster_name_8024161 = "Kehendak Jahat: Bayangan",
  str_monster_name_8024442 = "Kehendak Jahat: Murkmite",
  str_monster_name_80243111 = "Kehendak Jahat: Augean",
  str_monster_name_80243111_en = "Kehendak Jahat: Augean",
  str_monster_name_7001121 = "Ditinggalkan: Raja Merman",
  str_monster_ability_7001121 = "Serangan menimbulkan efek knockback. Dapat memanggil Salvo Guns di lokasi tertentu di medan perang.",
  str_monster_name_7001121_en = "Ditinggalkan: Raja Merman",
  str_monster_passiveskill_name_7001121 = "Penempatan Senapan Salvo",
  str_monster_passiveskill_desc_7001121 = "Di awal putaran pemain, jika kurang dari 3 Salvo Guns ada di medan perang, memanggil 4 Salvo Guns.",
  str_monster_name_2004701 = "Fiendling: Tikus",
  str_monster_desc_2004701 = "Fiendlings omnivora berukuran kecil dengan budidaya yang tidak cukup, tetap mempertahankan sifat liar mereka. Mereka selalu menyelinap ke tempat tinggal Aurorian untuk mencuri makanan. Beberapa yang agresif bahkan mungkin menyebabkan kerusakan.",
  str_monster_ability_2004701 = "Lincah dan cepat, ia dengan gesit bergerak ke belakang target setelah serangan.",
  str_monster_passiveskill_name_2004701 = "Gigitan dari Tikus",
  str_monster_passiveskill_desc_2004701 = "Menarget Aurorian dengan DEF terendah dalam tim saat menyerang, memberikan kerusakan.",
  str_monster_ability_5412041 = "Seorang Eclipsite dengan kemampuan pemanggilan. Tidak dapat bergerak sendiri, ia bertarung dengan memanggil Gloom Ghouls yang memiliki kemampuan serangan jarak jauh. Gloom Ghouls mengorbankan HP mereka sendiri untuk menyembuhkan Croweye saat memasuki pertempuran dan mentransfer kerusakan ke Croweye saat menerima kerusakan.",
  str_monster_passiveskill_name_5412042 = "Simbiosis Pengorbanan",
  str_monster_passiveskill_desc_5412042 = "Ia mengorbankan HP-nya sendiri untuk menyembuhkan Croweye saat memasuki pertempuran dan mentransfer kerusakan ke Croweye saat menerima kerusakan.",
  str_monster_name_541100216 = "Chen'ni",
  str_monster_desc_541100216 = "Anak yang tiba-tiba muncul dari mana-mana itu tampaknya seperti setan aneh yang memiliki penampilan seperti kita?",
  str_monster_ability_541100216 = "Kemampuannya mengejutkan!",
  str_monster_passiveskill_desc_541301215 = "Di awal putaran pemain, jika kurang dari 2 Salvo Guns di medan perang, memanggil 4 Salvo Guns.",
  str_monster_name_2909301 = "Fiendling: Nian",
  str_monster_name_2909301_en = "Fiendling: Nian",
  str_monster_desc_2909301 = "Legenda mengatakan bahwa pada malam Festival Musim Semi, makhluk jahat yang mirip binatang buas turun ke Longzhou, menyebabkan kekacauan. Mereka yang berhasil mengusirnya akan diberkati dengan setahun penuh damai dan keberuntungan.",
  str_monster_ability_2909301 = "Nian akan menghancurkan segala yang terlihat saat mendekati desa. Hanya Aurorian yang memiliki Active Skills yang kuat yang mampu menghentikannya.",
  str_monster_passiveskill_name_2909301 = "Binatang Purba yang Tangguh",
  str_monster_passiveskill_desc_2909301 = "Kehadiran Nian yang menakutkan benar-benar mengerikan! Tile dalam 1 klaster di sekitar tidak dapat dipilih sebagai titik pendaratan Aurorian.",
  str_monster_passiveskill_name_2909302 = "Menerobos Gerbang",
  str_monster_passiveskill_desc_2909302 = "Binatang Nian akan menghancurkan gerbang dan, setelah masuk, merusak segalanya, menyebabkan pertempuran gagal.",
  str_monster_name_70011251 = "Ditinggalkan: Cerritus",
  str_monster_name_70011251_en = "Ditinggalkan: Cerritus",
  str_monster_desc_70011251 = "Eclipsite baru yang ditemui selama eksplorasi tampaknya merupakan varian dari Eclipsite yang kuat, kecuali itu lebih gila dan jauh lebih merusak.",
  str_monster_ability_70011251 = "Terlupakan: Cerritus menyerang Aurorian, memanggil kerikil dan terus-menerus menghasilkan ubin yang melemah di lapangan. Ia juga dapat meningkatkan ACT-nya sendiri selama pertempuran.",
  str_monster_name_70011261 = "Yang Ditinggalkan: Chandra",
  str_monster_name_70011261_en = "Yang Ditinggalkan: Chandra",
  str_monster_desc_70011261 = "Peneliti Illumina yang optimis dan ceria. Dia memiliki kemampuan khusus untuk menyerap emosi negatif dari orang lain dan menyembuhkan trauma mental mereka.",
  str_monster_ability_70011261 = "Forsaken: Chandra dapat melancarkan serangan pada Aurorian dari jarak jauh dan terus meningkatkan jumlah kali skillnya memberikan kerusakan.",
  str_monster_passiveskill_name_70011261 = "Forsaken: Kumpulkan Emosi Negatif",
  str_monster_passiveskill_desc_70011261 = "Dengan setiap pengecoran Forsaken: Negative Emotion Project, skill meluncurkan 1 serangan lagi di waktu berikutnya, memberikan total kerusakan yang meningkat.",
  str_monster_passiveskill_name_80051412 = "Strategi Warfront",
  str_monster_passiveskill_desc_80051412 = "Kurir dapat menyimpan energi pertempuran untuk memotivasi monster. Ketika ada lebih dari 30 poin energi pertempuran, ia memberikan peningkatan ATK permanen sebesar 10% untuk semua monster di lapangan pada akhir setiap putaran. Namun, Kurir akan memicu ledakan energi saat mati, menimbulkan kerusakan besar pada semua monster di lapangan.",
  str_monster_passiveskill_name_80051413 = "Akses Energi",
  str_monster_passiveskill_desc_80051413 = "Kurir secara otomatis mengembalikan 10 tumpukan energi pertempuran di awal setiap putaran. Ketika Aurorian melepaskan Skill Aktif di lapangan, ini mengurangi tumpukan energi pertempuran Kurir sebanyak 4. Selain itu, Kurir kehilangan 1 tumpukan energi pertempuran saat terkena serangan normal Aurorian.",
  str_monster_name_2909401 = "Ira",
  str_monster_name_2909401_en = "Ira",
  str_monster_desc_2909401 = "Sebuah Wraith yang misterius dan tangguh, menjelajahi tanah untuk berlatih. Napasnya memancarkan teror, meramalkan malapetaka bagi mereka yang membangkitkan kemarahannya.",
  str_monster_ability_2909401 = [[
Mampu memanggil Shadowfire dengan Darkflow dalam pertempuran.
Catatan: Meteorit Darkflow milik Ira, yang terdiri dari api yang mengamuk, dapat seketika membunuh Aurorian dalam jangkauannya.]],
  str_monster_name_2004801 = "Shadowfire",
  str_monster_passiveskill_name_2004801 = "Abu Shadowfire",
  str_monster_passiveskill_desc_2004801 = "Setelah dieliminasi, Shadowfire meninggalkan Tile Gelap di lokasinya.",
  str_monster_ability_5435071 = "Serangan menimbulkan knockback. Dapat memanggil meriam salvo di tile terdekat untuk perlindungan diri.",
  str_monster_ability_5435112 = "Berlindung di tempat yang aman, mengorbankan sebagian HP setiap putaran untuk memulihkan HP Philex.",
  str_monster_name_70011271 = "Forsaken: Caracalune",
  str_monster_name_70011271_en = "Forsaken: Caracalune",
  str_monster_name_70011281 = "Ditinggalkan: Maude Solus",
  str_monster_name_70011281_en = "Ditinggalkan: Maude Solus",
  str_monster_ability_70011271 = "Unggul dalam menggunakan serangan area besar. Mengunci elemen ubin di sekitarnya setelah bergerak.",
  str_monster_name_70011321 = "Terlupakan: Laba-laba Queen",
  str_monster_name_70011321_en = "Forsaken: Arachnid Queen",
  str_monster_ability_70011321 = "Memiliki kemampuan reproduksi yang kuat, ia menjalin jaring laba-laba ke dalam lingkungan berburu dan memanggil sejumlah besar keturunan laba-laba untuk bergabung dalam pertempuran setiap 3 putaran.",
  str_monster_name_70110011 = "Forsaken: Berduka Eve",
  str_monster_name_70110011_en = "Forsaken:Berduka Eve",
  str_monster_desc_70110011 = "Rasa sakit karena isolasi dan ketakutan akan terputus, kenangan masa lalu yang tak tertahankan itu, telah membentuk orang yang dikenal sebagai Eve Hari ini.",
  str_monster_ability_70110011 = "Setiap ronde, panggil Dawn Bunga di lokasi tertentu di medan perang, meningkatkan DEF sesuai dengan jumlah Dawn Bunga.",
  str_monster_passiveskill_name_70110011 = "Kesedihan: Bermetamorfosis",
  str_monster_passiveskill_desc_70110011 = "Setiap putaran, panggil Dawn Bunga di lokasi yang ditentukan untuk meningkatkan DEF; setiap Bunga Dawn memberikan peningkatan DEF tambahan.",
  str_monster_name_70110012 = "Dawn Bunga",
  str_monster_desc_70110012 = "Bunga putih sederhana ini, kecil dan biasa, adalah salah satu kenyamanan paling berharga di hatinya.",
  str_monster_ability_70110012 = "Memberikan bonus DEF tambahan untuk Grieving Eve.",
  str_monster_name_7001134 = "Terlupakan: Bennuguardian",
  str_monster_name_7001134_en = "Forsaken:Bennuguardian",
  str_monster_ability_7001134 = "Memiliki kekuatan besar. Mengumpulkan Fury saat diserang. Ketika Fury mencapai level tertentu, memasuki kondisi Marah, mengurangi kerusakan yang diterima dan memberikan keterampilan tambahan yang kuat.",
  str_monster_name_2004901 = "Kabut asap",
  str_monster_desc_2004901 = "Terbentuk dari akumulasi Darkflow yang cepat di sekitar Eclipsite yang mati. Hati-hati! Amarah dan dendam Eclipsite tetap hidup di dalamnya.",
  str_monster_ability_2004901 = "Semua kerusakan yang diterimanya dikurangi menjadi 1. Ia tidak bisa menyerang tetapi akan terus bergerak menuju Aurorian.",
  str_monster_passiveskill_name_2004901 = "Kabut yang Membelit",
  str_monster_passiveskill_desc_2004901 = "Semua damage yang diterimanya dikurangi menjadi 1. Ia tidak bisa menyerang tetapi akan terus bergerak menuju Aurorian dan menghilang jika terkena efek perpindahan. Menghilang secara normal setelah 2 ronde.",
  str_monster_passiveskill_desc_2004902 = "Semua damage yang diterimanya dikurangi menjadi 1. Ia tidak bisa menyerang tetapi akan terus bergerak menuju Aurorian dan menghilang jika terkena efek perpindahan. Menghilang secara normal setelah 3 putaran.",
  str_monster_name_2909501 = "Wortel: Hama",
  str_monster_name_2909501_en = "Wortel: Hama",
  str_monster_desc_2909501 = "Setelah menyerap terlalu banyak kebencian di tempat yang gelap dan membusuk, wortel ini telah berkembang menjadi makhluk aneh yang mencari balas dendam setelah mendapatkan kekuatan Darkflow.",
  str_monster_ability_2909501 = "Melempar wortel, menimbulkan beberapa kali kerusakan. Saat berputar dengan kecepatan tinggi, ia menimbulkan beberapa kali kerusakan pada musuh di area yang luas dan mendorong mereka mundur.",
  str_monster_ability_2909502 = [[
Melempar wortel, menimbulkan beberapa kali kerusakan. Saat berputar dengan kecepatan tinggi, ia menimbulkan beberapa kali kerusakan pada musuh di area yang luas dan mendorong mereka mundur.
Dalam keadaan darurat, ia bisa menyusut dan menggali ke dalam tanah dan melanjutkan pertarungan dari sana.]],
  str_monster_passiveskill_name_2909502 = "Blight: Burrow",
  str_monster_passiveskill_desc_2909502 = "Jika ia tidak terkalahkan saat mengambil tindakan, ia menjadi lebih kecil, menggali ke bawah tanah, dan memulihkan HP-nya menjadi penuh.",
  str_monster_ability_5455121 = "Dapat menggunakan serangan berbentuk silang atau layar penuh, dan memanggil petir.",
  str_monster_ability_4910302 = "Memiliki ATK tinggi, dan dapat memberikan kerusakan berat dalam bentuk radial hingga jangkauan maksimum.",
  str_monster_ability_5455091 = "Kittypus mengibaskan tentakelnya untuk menimbulkan damage besar pada Aurorian.",
  str_monster_name_2909701 = "Magmite Tak pernah puas",
  str_monster_name_2909701_en = "Magmite Tak pernah puas",
  str_monster_desc_2909701 = "Sejenis Eclipsite yang abnormal yang menggunakan lava dan Darkflow untuk menimbulkan kerusakan.",
  str_monster_ability_2909701 = "Dapat menimbulkan kerusakan dalam area yang luas, serta memanggil perisai leburan untuk melindungi dirinya sendiri.",
  str_monster_passiveskill_name_2909701 = "Refleksi Lava",
  str_monster_passiveskill_desc_2909701 = "Saat dilindungi oleh perisai lelehannya, semua serangan normal yang datang dari Aurorian dipantulkan kembali.",
  str_monster_name_80063701 = "Penjahat Kota",
  str_monster_desc_80063701 = "Hoodlum yang telah menguasai penggunaan busur silang dan tahu cara menyerang dengan tepat, diam-diam, dan yang paling penting... aman.",
  str_monster_ability_80063701 = "Dapat menyerang target dalam bentuk silang hingga batas maksimum jangkauannya.",
  str_monster_name_80063801 = "Penjahat Elite Kota",
  str_monster_desc_80063801 = "Dikatakan bahwa mereka adalah prajurit elit yang terampil dalam menggunakan senjata api dan memiliki kelincahan yang luar biasa.",
  str_monster_ability_80063801 = "Menimbulkan kerusakan dua kali setelah menggunakan kegesitannya yang luar biasa untuk menjauh dari target.",
  str_monster_ability_2910242 = "Unggul dalam menggunakan serangan area besar; serangan jarak sangat jauh menimbulkan lebih banyak damage pada target yang lebih jauh.",
  str_monster_ability_2920232 = "Vani bisa menggunakan Energi untuk menyerang dari jarak jauh.",
  str_monster_passiveskill_name_20007011 = "Promosi",
  str_monster_passiveskill_desc_20007011 = "Begitu mencapai tepi Alchemy Board, mereka akan naik tingkat menjadi Enraged Rook, Fallen Knight, Eclipse Bishop, atau Deceptive Queen, sesuai dengan urutan kedatangannya.",
  str_monster_passiveskill_name_20007111 = "Promosi Elite",
  str_monster_passiveskill_desc_20007111 = "Begitu mencapai tepi Alchemy Board, mereka akan dipromosikan menjadi Enraged Rook - RAM, Fallen Knight - CHARGE, Eclipse Bishop - EX, atau Deceptive Queen, sesuai dengan urutan kedatangan mereka.",
  str_monster_passiveskill_name_2910242 = "Jangan Pernah Menyerah",
  str_monster_passiveskill_desc_2910242 = "Mad Horn menjadi lebih kuat setiap kali bilah HP saat ini berkurang menjadi nol.",
  str_monster_passiveskill_name_2010171 = "Mengisi",
  str_monster_passiveskill_desc_2010171 = "Mengurangi cooldown skill Kapten Aurorian sebanyak 1 setiap kali dia dieliminasi.",
  str_monster_passiveskill_name_2914001 = "Fearless",
  str_monster_passiveskill_desc_2914001 = "Hanya menerima 1 damage dari serangan.",
  str_monster_passiveskill_name_29140011 = "Escort",
  str_monster_passiveskill_desc_29140011 = "Vani memulihkan HP sebanding dengan 200% dari kerusakan yang dihasilkan Bennuguardian.",
  str_monster_passiveskill_name_2920232 = "Kegigihan",
  str_monster_passiveskill_desc_2920232 = "Meningkatkan DEF saat HP berkurang.",
  str_monster_passiveskill_name_2010715 = "Pelemah",
  str_monster_passiveskill_desc_2010715 = "Mengurangi DEF Deceptive Queen setiap kali Eclipsite mati.",
  str_monster_passiveskill_name_20107152 = "Perlindungan",
  str_monster_passiveskill_desc_20107152 = "Jika Deceptive Queen memiliki Safeguard saat bertindak, memberikan 3 tumpukan Safeguard ke semua Eclipsite lainnya.",
  str_monster_passiveskill_name_2910801 = "Jangan Pernah Menyerah",
  str_monster_passiveskill_desc_2910801 = "Desolate Monarch menjadi lebih kuat setiap kali batang HP-nya berkurang menjadi nol. Beberapa Eclipsite yang sedang tidur juga akan terbangun.",
  str_monster_passiveskill_name_29006411 = "Kunci",
  str_monster_passiveskill_desc_29006411 = "Melawan Active Skills Aurorian, menimbulkan damage pada Aurorian dan memanggil Tile Terkunci pada 4 Tile di sekitar mereka.",
  str_monster_passiveskill_name_29006611 = "Smash",
  str_monster_passiveskill_desc_29006611 = "Melawan Keterampilan Aktif Aurorian, secara acak memanggil ubin yang rusak.",
  str_monster_name_1502001 = "Terlantar: Anatoli",
  str_monster_name_1502001_en = "Anatoli",
  str_monster_desc_1502001 = "Petugas intelijen yang tenang dan andal dari Federasi Illumina yang sesekali membuat keluhan tak terduga. Tidak ada yang tahu apakah pengaduan tersebut dibuat secara sengaja atau tidak sengaja.",
  str_monster_ability_1502001 = "Menarik unit musuh untuk mengendalikan situasi pertempuran dengan lebih mudah.",
  str_monster_name_1501761 = "Terlupakan: Beretta",
  str_monster_name_1501761_en = "Beretta",
  str_monster_desc_1501761 = "Seorang dokter tempur Lumopolis pernah diselamatkan oleh seorang dokter bernama John. Sejak itu, dia memutuskan untuk menjadi dokter yang baik.",
  str_monster_ability_1501761 = "Dengan terampil menggunakan Tombak Australis untuk memberikan kerusakan pada musuh. Memiliki kemampuan untuk melawan Active Skills Aurorian.",
  str_monster_passiveskill_name_1501761 = "Counter Australis",
  str_monster_passiveskill_desc_1501761 = "Melawan Skill Aktif Aurorian, memberikan 1 tanda Tombak Australis. Memberikan kerusakan 1 kali tambahan saat melakukan Australis Tempest.",
  str_monster_name_70011291 = "Terlupakan: Wicked Dragon Hakudoma",
  str_monster_name_70011291_en = "Terlupakan: Wicked Dragon Hakudoma",
  str_monster_name_5471001 = "Reinhardt",
  str_monster_name_5471001_en = "Reinhardt",
  str_monster_desc_5471001 = "Seorang Grand Marshal sejati dari Illumina Federation. Tak hanya berjiwa kesatria dan mahir bertempur, dia juga merupakan sosok yang jujur dan pemimpin cakap yang sangat dihormati di seantero Illumina.",
  str_monster_ability_5471001 = "Memiliki ATK tinggi dan dapat memberikan kerusakan besar pada target di sekitarnya.",
  str_monster_desc_5471002 = "Sebuah droid tempur yang dimodifikasi oleh Federasi Illumina. Dikalibrasi sesuai dengan atribut spesifik Reinhardt, ia memiliki beberapa kemampuannya.",
  str_monster_name_2909801 = "Tombak: Rotbone Stinger",
  str_monster_name_2909801_en = "Tombak: Rotbone Stinger",
  str_monster_desc_2909801 = "Dulu seorang Colossus perang yang berlari terlebih dahulu ke medan pertempuran atas nama Eclipse, sekarang hanya menjadi tumpukan puing yang hancur, ancaman terakhirnya terletak di tulang ekornya.",
  str_monster_ability_2909801 = "Mampu menimbulkan damage pada target dalam area luas dan menghasilkan unit periferal yang bergerak dalam formasi klaster untuk memblokir Aurorian.",
  str_monster_name_2005101 = "Provokator Pinggiran",
  str_monster_desc_2005101 = "Awalnya bagian dari ekor Spearhead, potongan-potongan ini terlepas satu per satu dan tersebar di seluruh reruntuhan bawah tanah.",
  str_monster_ability_2005101 = "Monster terbang yang dikendalikan oleh kekuatan misterius, terus membentuk formasi aneh untuk melancarkan serangan jarak dekat pada penyusup.",
  str_monster_name_70011421 = "Ditinggalkan: Figerald",
  str_monster_name_70011421_en = "Ditinggalkan: Figerald",
  str_monster_name_70011431 = "Ditinggalkan: Ira",
  str_monster_name_70011431_en = "Ditinggalkan: Ira",
  str_monster_passiveskill_name_2905201 = "Melangkah Menuju Kehampaan",
  str_monster_passiveskill_desc_2905201 = "Ubin yang dipindahkan oleh Aurorian akan runtuh sesuai. Ubin tidak akan runtuh dalam Waktu Aurora setelah Aurorian memindahkannya. Sanity turun sebesar 30 ketika adegan runtuh.",
  str_monster_name_2910101 = "David Porfirio",
  str_monster_name_2910101_en = "David Porfirio",
  str_monster_desc_2910101 = "Kepala keluarga Porfirio. Dia adalah seseorang yang suka mendominasi orang lain dan tanpa henti mengejar kekuasaan dengan segala cara.",
  str_monster_ability_2910101 = "Menggunakan berbagai skill terhadap Aurorian berdasarkan Sanity: Memanggil Necroservants atau menyerang untuk menyembuhkan diri sendiri.",
  str_monster_passiveskill_name_29101011 = "Kegilaan",
  str_monster_passiveskill_desc_29101011 = "Seiring berkurangnya Sanity, David Porfirio menjadi lebih liar, dengan DEF yang lebih rendah tetapi ATK yang lebih tinggi.",
  str_monster_passiveskill_name_29101012 = "Ketakutan Pencegahan",
  str_monster_passiveskill_desc_29101012 = "Hanya ambil 10% dari damage pertama dari setiap Aurorian di setiap putaran.",
  str_monster_name_2005201 = "Necroservant",
  str_monster_desc_2005201 = "Jiwa-jiwa yang malang telah pergi, selamanya tertipu dan terkurung. Sekarang mereka bergentayangan, mencari darah hangat segar untuk tuan mereka.",
  str_monster_ability_2005201 = "Menyebabkan efek kerusakan yang berbeda pada Aurorian berdasarkan Sanity: Menguras Sanity atau mengkonsumsi HP.",
  str_monster_name_2910001 = "Syurton",
  str_monster_desc_2910001 = "Sebuah Vanguard pengepungan yang besar dan gigih. Meski dengan anggota tubuh yang terpencar, ia dapat merusak struktur tanah.",
  str_monster_ability_2910001 = "Dapat menyerang Aurorian dengan berbagai bagian tubuh. Merusak bagian tubuh Syurton akan melukainya.",
  str_monster_name_2910001_en = "Syurton",
  str_monster_passiveskill_name_2910001 = "Penolak-Sun",
  str_monster_passiveskill_desc_2910001 = "Ekor Syurton kebal terhadap serangan normal dan kerusakan area.",
  str_monster_name_2909901 = "Stone Giant of the Ruins",
  str_monster_name_2909901_en = "Raksasa Batu dari Reruntuhan",
  str_monster_desc_2909901 = "In the eyes of future Aurorians, extraordinary advanced technology may be seen as equivalent to magic, and in Fleur's eyes, the stone giant is akin to a mecha.",
  str_monster_ability_2909901 = "Memiliki kemampuan penyembuhan yang kuat.",
  str_monster_passiveskill_name_2909901 = "Aktif Kosong",
